--========================================================--
-- [MAWWW FIX] RUN TOKEN (re-execution safety)
-- Every execution owns one token. When the script is executed again, the
-- previous token is marked dead and every connection registered through
-- MAWWW_Conn is disconnected; loops that test MAWWW_RUN.dead then exit.
-- The shared VD table is intentionally kept (settings survive), so the old
-- "(VD.Destroyed or MAWWW_RUN.dead)" flag alone could never stop loops of an older execution.
--========================================================--
local MAWWW_RUN = { dead = false, conns = {}, id = tostring(os.clock()) }
function MAWWW_Conn(signal, callback)
    local connection = signal:Connect(callback)
    local list = MAWWW_RUN.conns
    list[#list + 1] = connection
    if #list > 800 then
        -- Drop connections that were already disconnected/destroyed with their instance.
        local kept = {}
        for _, item in ipairs(list) do
            local okConnected, connected = pcall(function() return item.Connected end)
            if not okConnected or connected then kept[#kept + 1] = item end
        end
        MAWWW_RUN.conns = kept
    end
    return connection
end

-- Startup notice guard: the merged feature modules may emit many state notices
-- while the UI and callbacks are being registered. Mute boot-time notices and
-- coalesce bursts so they do not stack over the right side of the screen.
local MAWWW_StartupNotificationsMuted = true
local MAWWW_NotifyLastTime = 0
local MAWWW_NotifyBurstStart = os.clock()
local MAWWW_NotifyBurstCount = 0
local MAWWW_NotifyRecent = {}
local MAWWW_NotifyLastPrune = os.clock()
local function MAWWW_AllowNotification(title, content)
    if MAWWW_StartupNotificationsMuted then return false end
    local now = os.clock()
    title = tostring(title or "Mawww Hub")
    content = tostring(content or "")
    local key = string.lower(title .. "\0" .. content)

    local previous = MAWWW_NotifyRecent[key]
    if previous and now - previous < 8 then
        return false
    end
    if now - MAWWW_NotifyLastTime < 0.85 then
        return false
    end
    if now - MAWWW_NotifyBurstStart >= 5 then
        MAWWW_NotifyBurstStart = now
        MAWWW_NotifyBurstCount = 0
    elseif MAWWW_NotifyBurstCount >= 3 then
        return false
    end

    MAWWW_NotifyRecent[key] = now
    MAWWW_NotifyLastTime = now
    MAWWW_NotifyBurstCount += 1

    if now - MAWWW_NotifyLastPrune >= 30 then
        for oldKey, stamp in pairs(MAWWW_NotifyRecent) do
            if now - stamp > 20 then MAWWW_NotifyRecent[oldKey] = nil end
        end
        MAWWW_NotifyLastPrune = now
    end
    return true
end

