    local genv = getgenv()
    if genv and type(genv.MAWWW_StunIndicatorShutdown) == "function" then
        genv.MAWWW_StunIndicatorShutdown()
    end
    if genv and type(genv.MAWWW_StunIndicatorPanelShutdown) == "function" then
        genv.MAWWW_StunIndicatorPanelShutdown()
    end
end)

