    local oldV5 = genv and genv.MAWWW_AutoParryV5
    if oldV5 and type(oldV5.Destroy) == "function" then
        oldV5:Destroy()
    end
end)

--// Disconnect status-panel listeners from a previous execution before deleting their GUIs.
pcall(function()
    local env = _G
    if type(getgenv) == "function" then env = getgenv() end
    for _, cleanupName in ipairs({"MAWWW_ParryStatusPanelsShutdown", "MAWWW_VeilStatusPanelsShutdown"}) do
        local cleanup = env and env[cleanupName]
        if type(cleanup) == "function" then pcall(cleanup) end
    end
end)

--// [MAWWW FIX] Retire the previous execution (after its own shutdown hooks ran above).
pcall(function()
    local env = (type(getgenv) == "function" and getgenv()) or _G
    local old = env.MAWWW_RunToken
    if type(old) == "table" and old ~= MAWWW_RUN then
        old.dead = true
        for _, connection in ipairs(old.conns or {}) do
            pcall(function() connection:Disconnect() end)
        end
        old.conns = {}
    end
    env.MAWWW_RunToken = MAWWW_RUN
end)

--// Cleanup previous instance from all common GUI containers.
for _, container in ipairs({MAWWW_GUI_PARENT, PlayerGui, CoreGui}) do
    pcall(function()
        if not container then return end
        for _, guiName in ipairs({"MawwwHub", "MawwwHubObsidian", "MawwwHub_ALFPremium", "ObsidianUI", "MawwwHubFluent", "MawwwHubKeyGate", "MawwwHubFloating", "MawwwHubPopupLayer", "ToFTargetSelector", "ToFTargetSelectorV1", "ToFTargetSelectorV2", "ToFTargetSelectorV3", "ToFTargetSelectorV4", "ToFTargetSelectorV5", "MawwwHubMusicPanel", "MawwwHubStunIndicatorPanel", "MawwwHubParryStatusVersions", "MawwwHubVeilKnockStatusVersions", "MawwwHubBootError"}) do
            local existing = container:FindFirstChild(guiName)
            if existing then
                if guiName == "MawwwHubFloating" and existing:IsA("ScreenGui")
                    and existing:GetAttribute("MawwwPatchedLauncher") == true then
                    -- Launcher from a patched run: its ancestry handler was disconnected above.
                    existing:Destroy()
                elseif guiName == "MawwwHubFloating" and existing:IsA("ScreenGui") then
                    -- Do not Destroy an older launcher: its AncestryChanged callback
                    -- can recreate it on reparent. Leave it parented but inert.
                    existing.Enabled = false
                    for _, descendant in ipairs(existing:GetDescendants()) do
                        if descendant:IsA("GuiObject") then
                            pcall(function()
                                descendant.Visible = false
                                if descendant:IsA("GuiButton") then
                                    descendant.Active = false
                                    descendant.Selectable = false
                                end
                            end)
                        end
                    end
                else
                    existing:Destroy()
                end
            end
        end
    end)
end

