-- Some Roblox IDs copied from the website refer to a decal/catalog asset rather
-- than the image content ID accepted directly by ImageLabel. Try the Roblox
-- thumbnail resolver first, then fall back to the direct asset URI.
local function MAWWW_ApplyToFTargetImage(imageObject, preferredScaleType, force)
    if not imageObject or not imageObject:IsA("ImageLabel") then return end
    pcall(function()
        imageObject.Visible = true
        imageObject.BackgroundTransparency = 1
        imageObject.ImageTransparency = 0
        imageObject.ScaleType = preferredScaleType or Enum.ScaleType.Crop
    end)

    local direct = MAWWW_TOF_TARGET_MODE_IMAGE_ID
    local thumb = MAWWW_TOF_TARGET_MODE_THUMBNAIL_ID
    local current = imageObject.Image
    if not force and (current == direct or current == thumb) then
        return
    end

    pcall(function() imageObject.Image = thumb end)
    task.spawn(function()
        local contentProvider = game:GetService("ContentProvider")
        pcall(function() contentProvider:PreloadAsync({imageObject}) end)
        if not imageObject.Parent then return end
        local loaded = false
        pcall(function() loaded = imageObject.IsLoaded end)
        if not loaded then
            pcall(function() imageObject.Image = direct end)
            pcall(function() contentProvider:PreloadAsync({imageObject}) end)
        end
        if imageObject.Parent then
            pcall(function()
                imageObject.Visible = true
                imageObject.ImageTransparency = 0
                imageObject.ScaleType = preferredScaleType or Enum.ScaleType.Crop
            end)
        end
    end)
end
