-- Robust role detection used by the TOF target selectors. Different game rounds
-- can expose "Survivor"/"Survivors" or attributes instead of an exact Team name.
function MAWWW_GetTargetRole(player)
    if not player or player == LocalPlayer then return nil end

    local function normalizeRole(value)
        if value == nil then return nil end
        local text = string.lower(tostring(value))
        if text:find("killer", 1, true) or text:find("slasher", 1, true) or text == "monster" then
            return "Killer"
        end
        if text:find("surviv", 1, true) or text:find("civilian", 1, true) then
            return "Survivors"
        end
        if text:find("zombie", 1, true) or text:find("scp", 1, true) then
            return "Zombie"
        end
        return nil
    end

    local role = normalizeRole(player:GetAttribute("Role"))
    if role then return role end
    role = normalizeRole(player:GetAttribute("TeamRole"))
    if role then return role end
    role = normalizeRole(player:GetAttribute("Class"))
    if role then return role end
    role = normalizeRole(player.Team and player.Team.Name)
    if role then return role end

    local char = player.Character
    if char then
        role = normalizeRole(char:GetAttribute("Role"))
        if role then return role end
        role = normalizeRole(char:GetAttribute("TeamRole"))
        if role then return role end
        role = normalizeRole(char:GetAttribute("Class"))
        if role then return role end
        if char:GetAttribute("IsKiller") == true or char:GetAttribute("IsKillerRole") == true then
            return "Killer"
        end
        if char:GetAttribute("IsSurvivor") == true then
            return "Survivors"
        end
        if char:GetAttribute("IsZombie") == true then
            return "Zombie"
        end
    end

    if player:GetAttribute("IsKiller") == true or player:GetAttribute("IsKillerRole") == true then
        return "Killer"
    end
    if player:GetAttribute("IsSurvivor") == true then
        return "Survivors"
    end
    if player:GetAttribute("IsZombie") == true then
        return "Zombie"
    end

    return nil
end
