function New(className, props, parent)
    local obj = Instance.new(className)
    for k, v in pairs(props or {}) do
        local ok, err = pcall(function() obj[k] = v end)
        if not ok then
            warn("[Mawww Hub] UI property skipped:", className, k, err)
        end
    end
    local okParent, parentErr = pcall(function() obj.Parent = parent end)
    if not okParent then
        warn("[Mawww Hub] UI parent assignment failed:", className, parentErr)
    end

    -- Input safety: interactive Roblox GUI objects should never be left
    -- non-interactable or underneath a container/ScrollingFrame layer.
    -- Keep existing explicit high ZIndex values untouched.
    if obj:IsA("GuiButton") then
        pcall(function() obj.Active = true end)
        pcall(function() obj.Interactable = true end)
        pcall(function()
            if obj.ZIndex < 20 then
                obj.ZIndex = 20
            end
        end)
    elseif obj:IsA("TextBox") then
        pcall(function() obj.Active = true end)
        pcall(function() obj.Interactable = true end)
        pcall(function()
            if obj.ZIndex < 20 then
                obj.ZIndex = 20
            end
        end)
    end

    return obj
end

function Corner(parent, radius)
    return New("UICorner", {
        CornerRadius = UDim.new(0, radius or 8),
    }, parent)
end

function Stroke(parent, color, thickness, transparency)
    return New("UIStroke", {
        Color = color or Theme.Border,
        Thickness = thickness or 1,
        Transparency = transparency or 0,
    }, parent)
end

function Tween(obj, info, props)
    return TweenService:Create(obj, info, props)
end

function formatRounding(step)
    step = tonumber(step)
    if not step or step >= 1 then
        return 0
    end
    local n = 0
    local x = math.abs(step)
    while x < 1 and n < 6 do
        x = x * 10
        n = n + 1
    end
    return n
end


--========================================================--
-- MAWWW HUB • SHARED HTTP FETCHER
-- UI framework bootstrap follows below and targets deividcomsono/Obsidian.
-- Existing feature logic remains connected through a compatibility adapter.
--========================================================--

-- Some executors block game:HttpGet but expose request/http_request/syn.request.
-- Try those first, validate the response, and only then fall back to HttpGet.
local function MAWWW_FetchText(url)
    local requestFns = {}
    local function addRequest(fn)
        if type(fn) == "function" then
            table.insert(requestFns, fn)
        end
    end
    addRequest(request)
    addRequest(http_request)
    pcall(function() addRequest(http.request) end)
    pcall(function() addRequest(syn.request) end)

    for _, requestFn in ipairs(requestFns) do
        local ok, response = pcall(function()
            return requestFn({
                Url = url,
                Method = "GET",
                Headers = { ["User-Agent"] = "Mozilla/5.0 MawwwHub" },
            })
        end)
        if ok and type(response) == "table" then
            local status = tonumber(response.StatusCode or response.StatusCodeValue or response.Status)
            local body = response.Body or response.body or response.Data or response.data
            if type(body) == "string" and #body > 1000
                and (not status or (status >= 200 and status < 300)) then
                local trimmed = body:gsub("^%s+", ""):lower()
                if not trimmed:match("^<!doctype html") and not trimmed:match("^<html") then
                    return body, nil
                end
            end
        end
    end

    local ok, body = pcall(function() return game:HttpGet(url) end)
    if ok and type(body) == "string" and #body > 1000 then
        local trimmed = body:gsub("^%s+", ""):lower()
        if not trimmed:match("^<!doctype html") and not trimmed:match("^<html") then
            return body, nil
        end
    end
    return nil, tostring(body or "empty response")
end

local MAWWW_BootGui = nil

-- If the library cannot load, show a visible diagnostic instead of silently
-- returning before the launcher, key gate, and main hub can be created.
local function MAWWW_ShowBootError(message)
    pcall(function()
        if MAWWW_BootGui then MAWWW_BootGui:Destroy(); MAWWW_BootGui = nil end
        local diagnosticGui = Instance.new("ScreenGui")
        diagnosticGui.Name = "MawwwHubBootError"
        diagnosticGui.ResetOnSpawn = false
        diagnosticGui.IgnoreGuiInset = true
        diagnosticGui.DisplayOrder = 2147483000
        diagnosticGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        diagnosticGui.Parent = PlayerGui

        local panel = Instance.new("Frame")
        panel.Name = "DiagnosticPanel"
        panel.Size = UDim2.new(0.9, 0, 0, 190)
        panel.Position = UDim2.new(0.05, 0, 0.5, -95)
        panel.BackgroundColor3 = Color3.fromRGB(16, 18, 26)
        panel.BorderSizePixel = 0
        panel.Parent = diagnosticGui
        Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 12)

        local title = Instance.new("TextLabel")
        title.BackgroundTransparency = 1
        title.Position = UDim2.fromOffset(14, 10)
        title.Size = UDim2.new(1, -28, 0, 30)
        title.Font = Enum.Font.GothamBold
        title.TextSize = 16
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.TextColor3 = Color3.fromRGB(255, 78, 102)
        title.Text = "Mawww Hub — UI loader failed"
        title.Parent = panel

        local detail = Instance.new("TextLabel")
        detail.BackgroundTransparency = 1
        detail.Position = UDim2.fromOffset(14, 44)
        detail.Size = UDim2.new(1, -28, 1, -54)
        detail.Font = Enum.Font.Gotham
        detail.TextSize = 12
        detail.TextWrapped = true
        detail.TextYAlignment = Enum.TextYAlignment.Top
        detail.TextXAlignment = Enum.TextXAlignment.Left
        detail.TextColor3 = Color3.fromRGB(225, 229, 239)
        detail.Text = "The UI library could not be downloaded or compiled. Check executor HTTP access, then execute again. Details: " .. string.sub(tostring(message), 1, 280)
        detail.Parent = panel
    end)
end


