    MAWWW_AddUniqueRoot(roots, PlayerGui)
    MAWWW_AddUniqueRoot(roots, CoreGui)
    if type(gethui) == "function" then
        local ok, hidden = pcall(gethui)
        if ok then MAWWW_AddUniqueRoot(roots, hidden) end
    end
    return roots
end

local function MAWWW_CollectScreenGuis()
    -- ScreenGuis are direct children of their container. The old version called
    -- GetDescendants() on CoreGui/PlayerGui and used table.find (O(n^2)) on every
    -- sweep, which caused frame hitches. Nested ScreenGuis are still collected
    -- one level below direct children (e.g. a ScreenGui inside a Folder).
    local found, seen = {}, {}
    local function add(item)
        if item:IsA("ScreenGui") and not seen[item] then
            seen[item] = true
            found[#found + 1] = item
        end
    end
    for _, root in ipairs(MAWWW_GetGuiRoots()) do
        add(root)
        local okChildren, children = pcall(function() return root:GetChildren() end)
        if okChildren and children then
            for _, child in ipairs(children) do
                add(child)
                if child:IsA("Folder") or child:IsA("Configuration") then
                    local okInner, inner = pcall(function() return child:GetChildren() end)
                    if okInner and inner then
                        for _, item in ipairs(inner) do add(item) end
                    end
                end
            end
        end
    end
    return found
end

local _mawwwScreenGuisBefore = {}
for _, gui in ipairs(MAWWW_CollectScreenGuis()) do _mawwwScreenGuisBefore[gui] = true end

