local function MAWWW_ResolveScreenGui(nativeWindow)
    local keys = {"ScreenGui", "ScreenGUI", "Gui", "GUI", "MainGui", "MainGUI", "RootGui", "RootGUI", "Screen"}
    for _, key in ipairs(keys) do
        local ok, value = pcall(function() return nativeWindow[key] end)
        if ok and typeof(value) == "Instance" then
            if value:IsA("ScreenGui") then return value end
            local ancestor = value:FindFirstAncestorOfClass("ScreenGui")
            if ancestor then return ancestor end
        end
    end

    local candidates = MAWWW_CollectScreenGuis()
    local best, bestScore = nil, -math.huge
    for _, gui in ipairs(candidates) do
        local name = string.lower(tostring(gui.Name or ""))
        local score = 0
        if not _mawwwScreenGuisBefore[gui] then score += 100 end
        if name:find("gluto", 1, true) then score += 30 end
        if name:find("mawww", 1, true) then score += 24 end
        if name:find("alf", 1, true) then score += 20 end
        if name:find("window", 1, true) then score += 8 end
        local hasTitle = false
        pcall(function()
            for _, item in ipairs(gui:GetDescendants()) do
                if item:IsA("TextLabel") or item:IsA("TextButton") then
                    local text = string.lower(tostring(item.Text or ""))
                    if text:find("mawww hub", 1, true) then hasTitle = true; break end
                end
            end
        end)
        if hasTitle then score += 35 end
        if score > bestScore then best, bestScore = gui, score end
    end
    return best
end

local function MAWWW_ResolveMainFrame(nativeWindow, screenGui)
    local keys = {"MainFrame", "MainWindow", "Root", "WindowFrame", "Main", "Frame", "Container", "Window"}
    for _, key in ipairs(keys) do
        local ok, value = pcall(function() return nativeWindow[key] end)
        if ok and typeof(value) == "Instance" and value:IsA("GuiObject") then
            if not screenGui or value:IsDescendantOf(screenGui) then return value end
        end
    end
    if not screenGui then return nil end

    local viewport = Workspace.CurrentCamera and Workspace.CurrentCamera.ViewportSize or Vector2.new(800, 600)
    local viewportArea = math.max(1, viewport.X * viewport.Y)
    local best, bestScore = nil, -math.huge
    local function consider(item, isDirect)
        if not item:IsA("GuiObject") then return end
        local name = string.lower(tostring(item.Name or ""))
        local size = item.AbsoluteSize
        local width, height = size.X, size.Y
        if width <= 1 then width = math.max(item.Size.X.Offset, item.Size.X.Scale * viewport.X) end
        if height <= 1 then height = math.max(item.Size.Y.Offset, item.Size.Y.Scale * viewport.Y) end
        if width < 260 or height < 140 then return end
        local area = width * height
        local score = math.min(area / 12000, 48)
        if isDirect then score += 18 end
        if name == "mainframe" or name == "mainwindow" or name == "windowframe" then score += 75 end
        if name == "main" or name == "window" or name == "root" then score += 35 end
        if name:find("notification", 1, true) or name:find("popup", 1, true) or name:find("tooltip", 1, true) then score -= 80 end
        if area > viewportArea * 0.94 and not name:find("main", 1, true) and not name:find("window", 1, true) then score -= 60 end
        if item.BackgroundTransparency >= 0.98 then score -= 8 end
        if score > bestScore then best, bestScore = item, score end
    end
    for _, child in ipairs(screenGui:GetChildren()) do consider(child, true) end
    for _, child in ipairs(screenGui:GetDescendants()) do consider(child, false) end
    return best
end

