function Window:AddTab(config)
    config = config or {}
    local requestedName = tostring(config.Name or "Tab")
    local destinationName = MAWWW_TAB_NAME_MAP[requestedName] or requestedName
    local existing = self.NativeTabs and self.NativeTabs[destinationName]
    if existing then return existing end
    local nativeConfig = {}
    for key, value in pairs(config) do nativeConfig[key] = value end
    nativeConfig.Name = destinationName
    local tab = self.Native:AddTab(nativeConfig)
    if self.NativeTabs then self.NativeTabs[destinationName] = tab end
    return tab
end
