local _mawwwAccentThemes = {
    ["Neverlose Crimson"] = Color3.fromRGB(245, 70, 90),
    ["StarHub Gold"] = Color3.fromRGB(245, 185, 65),
    ["Emerald Cyber"] = Color3.fromRGB(56, 220, 140),
    ["Electric Violet"] = Color3.fromRGB(168, 85, 247),
    ["Midnight Gold"] = Color3.fromRGB(255, 196, 80),
    ["Sakura Blossom"] = Color3.fromRGB(255, 135, 190),
    ["Arctic Cyan"] = Color3.fromRGB(60, 220, 240),
    ["Sunset Flame"] = Color3.fromRGB(255, 100, 75),
    ["Electric Lime"] = Color3.fromRGB(175, 245, 70),
    ["Midnight Stealth"] = Color3.fromRGB(125, 135, 160),
}

function MAWWW_ApplyObsidianTheme(name)
    local accent = _mawwwAccentThemes[tostring(name or "Electric Violet")]
    if not accent then return false end

    pcall(function()
        Theme.Accent = accent
        Theme.Accent2 = accent:Lerp(Color3.new(1, 1, 1), 0.22)
        Theme.Purple = accent
        Theme.Slider = accent
    end)

    local scheme = ObsidianLibrary and ObsidianLibrary.Scheme
    if type(scheme) == "table" then
        pcall(function() scheme.BackgroundColor = Theme.Background or Color3.fromRGB(7, 7, 9) end)
        pcall(function() scheme.MainColor = Theme.Surface or Color3.fromRGB(18, 16, 24) end)
        pcall(function() scheme.AccentColor = accent end)
        pcall(function() scheme.OutlineColor = Theme.Border or Color3.fromRGB(65, 48, 82) end)
        pcall(function() scheme.FontColor = Theme.Text or Color3.fromRGB(248, 248, 250) end)
        pcall(function() scheme.RedColor = Theme.Red or Color3.fromRGB(255, 55, 82) end)
        pcall(function() scheme.DestructiveColor = Theme.Red or Color3.fromRGB(255, 55, 82) end)
        pcall(function() scheme.WhiteColor = Theme.Text or Color3.fromRGB(248, 248, 250) end)
    end

    -- Obsidian stores semantic color keys in Registry; re-apply registered
    -- properties so theme changes affect controls that already exist.
    pcall(function()
        for object, properties in pairs(ObsidianLibrary.Registry or {}) do
            if typeof(object) == "Instance" and type(properties) == "table" and object.Parent then
                for property, semanticKey in pairs(properties) do
                    if type(semanticKey) == "string" and scheme and scheme[semanticKey] ~= nil then
                        pcall(function() object[property] = scheme[semanticKey] end)
                    end
                end
            end
        end
    end)
    MAWWW_ActiveThemeName = tostring(name)
    return true
end

Fluent = {NotifyInsideWindow = true}
function Fluent:SetErrorHandler(callback) self._errorHandler = callback end
function Fluent:SetTheme(name)
    return MAWWW_ApplyObsidianTheme(name)
end
function Fluent:Notify(payload)
    payload = payload or {}
    local title = tostring(payload.Title or payload.title or "Mawww Hub")
    local content = tostring(payload.Content or payload.Description or payload.message or "")
    local duration = math.clamp(tonumber(payload.Duration or payload.Time) or 3.5, 1, 12)
    if SUPPRESS_NOTIFY == true then return end
    local ok, result = pcall(function()
        return ObsidianLibrary:Notify({
            Title = title,
            Description = content,
            Time = duration,
            Icon = payload.Icon or "bell",
        })
    end)
    if not ok then
        warn("[Mawww Hub] Obsidian notification failed:", tostring(result))
    end
    return result
end

