function MAWWW_SetWindowScreenEnabled(enabled)
    pcall(function()
        local root = Window and Window.Root
        if root then
            local screenGui = root:FindFirstAncestorOfClass("ScreenGui")
            if screenGui then MAWWW_WindowScreenGui = screenGui end
        end
        if MAWWW_WindowScreenGui then
            pcall(function() MAWWW_WindowScreenGui.IgnoreGuiInset = true end)
            -- A respawn must never reset/remove the hub window.
            pcall(function() MAWWW_WindowScreenGui.ResetOnSpawn = false end)
            if enabled == true and not MAWWW_WindowScreenGui.Parent then
                local okParent = pcall(function() MAWWW_WindowScreenGui.Parent = MAWWW_GUI_PARENT end)
                if not okParent then
                    warn("[Mawww Hub] The main UI was destroyed by another script. Re-execute Mawww Hub to rebuild it.")
                end
            end
            MAWWW_WindowScreenGui.Enabled = enabled == true
        end
        if root and not enabled then root.Visible = false end
    end)
end

function Window:Show()
