        local native = self.Native
        if native and type(native.Show) == "function" then native:Show()
        elseif native and type(native.SetVisible) == "function" then native:SetVisible(true) end
    end)
    pcall(function() if self.ScreenGui then self.ScreenGui.Enabled = true end end)
    pcall(function() if self.Root then self.Root.Visible = true end end)
    task.defer(function()
