        if native and type(native.Hide) == "function" then native:Hide()
        elseif native and type(native.SetVisible) == "function" then native:SetVisible(false) end
    end)
    pcall(function() if self.Root then self.Root.Visible = false end end)
end

function MAWWW_CenterWindow()
    pcall(function()
        local root = Window and Window.Root
        local camera = Workspace.CurrentCamera
        if not root or not camera then return end
        local viewport = camera.ViewportSize
        if viewport.X <= 0 or viewport.Y <= 0 then return end

        -- Clamp the saved/mobile size to the current viewport before centering.
        -- Using a center anchor avoids stale AbsoluteSize values while the window
        -- is being shown or resized by the library.
        local requested = Window.Size or _mawwwWindowSize
        local width = tonumber(requested.X.Offset) or 0
        local height = tonumber(requested.Y.Offset) or 0
        if width <= 0 then width = root.AbsoluteSize.X end
        if height <= 0 then height = root.AbsoluteSize.Y end
        if width <= 0 then width = _mawwwWindowSize.X.Offset end
        if height <= 0 then height = _mawwwWindowSize.Y.Offset end
        width = math.clamp(width, 1, math.max(1, viewport.X - 12))
        height = math.clamp(height, 1, math.max(1, viewport.Y - 12))
        root.Size = UDim2.fromOffset(math.floor(width), math.floor(height))
        root.AnchorPoint = Vector2.new(0.5, 0.5)
        root.Position = UDim2.new(0.5, 0, 0.60, 0)
        Window.Position = root.Position
    end)
end

