-- Keep one canonical Mawww floating launcher. Some feature/status panels create
-- a second small Mawww logo when their UI is opened. Hide those extra launchers,
-- including ones nested inside the main UI root, without touching status cards or
-- feature-specific floating controls that use different image assets.
local MAWWW_PRIMARY_LAUNCHER_ASSET = "92826170205694"
-- Assets used specifically for Mawww Hub's own launcher/brand buttons. Keep
-- feature buttons (for example the Invisible/TOF asset) out of this list.
local MAWWW_HUB_BRANDING_ASSETS = {
    MAWWW_PRIMARY_LAUNCHER_ASSET,
    "80159865448231", -- New main floating launcher icon; legacy duplicates should also be hidden.
    "88250532753444",
    "893565094168",
}

local function MAWWW_IsHubBrandingImage(image)
    image = string.lower(tostring(image or ""))
    for _, assetId in ipairs(MAWWW_HUB_BRANDING_ASSETS) do
        if image:find(assetId, 1, true) ~= nil then return true end
    end
    return false
end

local function MAWWW_IsHomeHeroObject(object)
    local current = object
    while current do
        local name = string.lower(tostring(current.Name or ""))
        if name == "mawwwhomeheroimage" or name == "mawwwhomeheroframe" then
            return true
        end
        if current == (Window and Window.ScreenGui) then break end
        current = current.Parent
    end
    return false
end

local function MAWWW_GetGuiSize(object)
    local size = Vector2.new(0, 0)
    pcall(function() size = object.AbsoluteSize end)
    if size.X <= 1 or size.Y <= 1 then
        pcall(function()
            size = Vector2.new(
                math.max(object.Size.X.Offset, object.Size.X.Scale * 100),
                math.max(object.Size.Y.Offset, object.Size.Y.Scale * 100)
            )
        end)
    end
    return size
end

local function MAWWW_IsSmallLauncherShape(size)
    return size and size.X >= 34 and size.X <= 140
        and size.Y >= 34 and size.Y <= 140
        and size.X / math.max(size.Y, 1) >= 0.70
        and size.X / math.max(size.Y, 1) <= 1.40
end

local function MAWWW_FindSmallLauncherContainer(object, screen)
    local current = object
    local smallFrame = nil
    while current and current ~= screen do
        if current:IsA("GuiButton") or current:IsA("Frame") then
            local size = MAWWW_GetGuiSize(current)
            if MAWWW_IsSmallLauncherShape(size) then
                if current:IsA("GuiButton") then return current end
                if not smallFrame then smallFrame = current end
            end
        end
        current = current.Parent
    end
    if smallFrame then return smallFrame end
    if object:IsA("GuiObject") and MAWWW_IsSmallLauncherShape(MAWWW_GetGuiSize(object)) then
        return object
    end
    return nil
end

local function MAWWW_HideLauncherObject(target)
    if not target then return end
    pcall(function()
        target.Visible = false
        if target:IsA("GuiButton") then
            target.Active = false
            target.Selectable = false
        end
    end)
end

-- [MAWWW FIX] Only Mawww-owned ScreenGuis are inspected for duplicate launchers.
-- Game GUIs and separate feature buttons (Quick Toggle, Myers Grab, ToF selectors,
-- Invisible button, ...) are never hidden by the duplicate-launcher sweep.
function MAWWW_IsOwnedLauncherScan(screen)
    if not screen then return false end
    if Window and screen == Window.ScreenGui then return true end
    local name = string.lower(tostring(screen.Name or ""))
    if name == "mawwwhub_quicktoggle" or name == "mawwwhubkeygate" then return false end
    return name:find("mawww", 1, true) ~= nil
end

function MAWWW_HideNativeWhiteLogo()
    pcall(function()
        for _, screen in ipairs(MAWWW_CollectScreenGuis()) do
            if screen and screen.Parent and screen ~= FloatingGui and MAWWW_IsOwnedLauncherScan(screen) then
                local screenName = string.lower(tostring(screen.Name or ""))
                local isLegacyFloatingGui = screenName == "mawwwhubfloating"
                if isLegacyFloatingGui then
                    -- Disable old launchers in place; destroying can trigger an
                    -- older AncestryChanged handler and make them reappear.
                    pcall(function()
                        screen.Enabled = false
                        for _, item in ipairs(screen:GetDescendants()) do
                            if item:IsA("GuiObject") then MAWWW_HideLauncherObject(item) end
                        end
                    end)
                else
                    for _, object in ipairs(screen:GetDescendants()) do
                        if object:IsA("GuiObject") and not MAWWW_IsHomeHeroObject(object) then
                            local lowerName = string.lower(tostring(object.Name or ""))
                            local nameLooksLikeLauncher = lowerName:find("launcher", 1, true) ~= nil
                                or lowerName:find("openbutton", 1, true) ~= nil
                                or (lowerName:find("floatingbutton", 1, true) ~= nil
                                    and lowerName:find("mawww", 1, true) ~= nil)
                                or lowerName:find("logobutton", 1, true) ~= nil
                            local namedHubLauncher = lowerName:find("mawww", 1, true) ~= nil
                                and nameLooksLikeLauncher

                            local image = ""
                            if object:IsA("ImageLabel") or object:IsA("ImageButton") then
                                pcall(function() image = string.lower(tostring(object.Image or "")) end)
                            end
                            local isHubBrandingLogo = MAWWW_IsHubBrandingImage(image)

                            local target = MAWWW_FindSmallLauncherContainer(object, screen)
                            local insideMainRoot = Window and Window.Root
                                and object:IsDescendantOf(Window.Root) or false
                            -- Main-root content is normally left alone. The exception
                            -- is a small button/container carrying the actual floating
                            -- logo, or an explicitly named launcher control.
                            local allowedInsideMainRoot = not insideMainRoot
                                or namedHubLauncher
                                or (isHubBrandingLogo and target ~= nil)

                            if target and allowedInsideMainRoot
                                and (nameLooksLikeLauncher or isHubBrandingLogo) then
                                MAWWW_HideLauncherObject(target)
                            elseif nameLooksLikeLauncher and MAWWW_IsSmallLauncherShape(MAWWW_GetGuiSize(object))
                                and allowedInsideMainRoot then
                                MAWWW_HideLauncherObject(object)
                            end
                        end
                    end
                end
            end
        end
    end)
end

task.defer(MAWWW_HideNativeWhiteLogo)
for _, delaySeconds in ipairs({0.15, 0.40, 0.85, 1.50, 2.50, 4.0}) do
    task.delay(delaySeconds, MAWWW_HideNativeWhiteLogo)
end

-- Watch for late-created launchers and logo assets. A short periodic sweep below
-- also catches images whose asset URL is assigned after the control is created.
local MAWWW_LauncherDedupeConnections = {}
local MAWWW_LauncherImageConnections = setmetatable({}, {__mode = "k"})

local function MAWWW_IsLauncherDedupeCandidate(object)
    if not object then return false end
    local name = string.lower(tostring(object.Name or ""))
    if object:IsA("ScreenGui") then
        return name == "mawwwhubfloating"
            or (name:find("mawww", 1, true) ~= nil
                and (name:find("launcher", 1, true) ~= nil or name:find("floating", 1, true) ~= nil))
    end
    if name:find("launcher", 1, true) ~= nil or name:find("openbutton", 1, true) ~= nil
        or name:find("logobutton", 1, true) ~= nil
        or (name:find("mawww", 1, true) ~= nil and name:find("floatingbutton", 1, true) ~= nil) then
        return true
    end
    if object:IsA("ImageLabel") or object:IsA("ImageButton") then
        local image = ""
        pcall(function() image = string.lower(tostring(object.Image or "")) end)
        if MAWWW_IsHubBrandingImage(image) then return true end
    end
    return false
end

local function MAWWW_WatchLauncherImage(object)
    if not object or MAWWW_LauncherImageConnections[object] then return end
    if not (object:IsA("ImageLabel") or object:IsA("ImageButton")) then return end
    local ok, connection = pcall(function()
        return object:GetPropertyChangedSignal("Image"):Connect(function()
            task.delay(0.05, function()
                pcall(MAWWW_HideNativeWhiteLogo)
            end)
        end)
    end)
    if ok and connection then MAWWW_LauncherImageConnections[object] = connection end
end

local function MAWWW_BindLauncherDedupeWatcher()
    local roots = {}
    pcall(function() roots = MAWWW_GetGuiRoots() end)
    for _, root in ipairs(roots) do
        if root then
            pcall(function()
                for _, screen in ipairs(root:GetChildren()) do
                    if screen:IsA("ScreenGui") and MAWWW_IsOwnedLauncherScan(screen) then
                        for _, item in ipairs(screen:GetDescendants()) do
                            if MAWWW_IsLauncherDedupeCandidate(item) then MAWWW_WatchLauncherImage(item) end
                        end
                    end
                end
            end)
            if not MAWWW_LauncherDedupeConnections[root] then
                local ok, connection = pcall(function()
                    return MAWWW_Conn(root.DescendantAdded, function(object)
                        -- Cheap name/class pre-check first; only Mawww-owned screens matter.
                        if not MAWWW_IsLauncherDedupeCandidate(object) then return end
                        local owner = object:IsA("ScreenGui") and object or object:FindFirstAncestorOfClass("ScreenGui")
                        if not owner or not MAWWW_IsOwnedLauncherScan(owner) then return end
                        MAWWW_WatchLauncherImage(object)
                        task.delay(0.10, function()
                            pcall(MAWWW_HideNativeWhiteLogo)
                        end)
                    end)
                end)
                if ok and connection then MAWWW_LauncherDedupeConnections[root] = connection end
            end
        end
    end
end

task.defer(MAWWW_BindLauncherDedupeWatcher)
task.delay(0.6, MAWWW_BindLauncherDedupeWatcher)

-- A launcher from an older execution may have its own visibility loop. Keep any
-- non-canonical ScreenGui with the same launcher name disabled without destroying
-- it (destroying can trigger its old reparent callback and recreate the duplicate).
task.spawn(function()
    while not MAWWW_RUN.dead do
        task.wait(1.0)
        pcall(function()
            for _, root in ipairs(MAWWW_GetGuiRoots()) do
                for _, child in ipairs(root:GetChildren()) do
                    if child:IsA("ScreenGui")
                        and string.lower(tostring(child.Name or "")) == "mawwwhubfloating"
                        and child ~= FloatingGui then
                        child.Enabled = false
                    end
                end
            end
        end)
    end
end)

-- Low-rate safety net. The DescendantAdded watcher above already reacts to late
-- launchers; this only catches images whose asset id is assigned later. It scans
-- Mawww-owned ScreenGuis only (see MAWWW_IsOwnedLauncherScan) and is visibility-only.
task.spawn(function()
    while not MAWWW_RUN.dead do
        task.wait(3.0)
        pcall(function()
            if type(MAWWW_HideNativeWhiteLogo) == "function" then
                MAWWW_HideNativeWhiteLogo()
            end
        end)
    end
end)
--========================================================--
-- MOBILE CONTROLS / FLOATING LAUNCHER + CUSTOM TOP TITLE-BAR CONTROLS
-- Top-bar actions are implemented by dedicated buttons to avoid Fluent callbacks.
-- Settings controls are kept separate; the Hide Hub Settings button is removed.
--========================================================--
MAWWW_Compact = false
MAWWW_SavedSize = _mawwwWindowSize
MAWWW_SavedPosition = nil

-- Re-center only when the viewport changes. Avoid a permanent RenderStepped
-- poll; on mobile this callback used to wake up every frame even while idle.
MAWWW_LastViewport = nil
MAWWW_ViewportConnection = nil
function MAWWW_BindViewportCamera(camera)
    if MAWWW_ViewportConnection then
        pcall(function() MAWWW_ViewportConnection:Disconnect() end)
        MAWWW_ViewportConnection = nil
    end
    if not camera then return end
    local viewport = camera.ViewportSize
    MAWWW_LastViewport = tostring(viewport.X) .. "x" .. tostring(viewport.Y)
    MAWWW_ViewportConnection = camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
        if MAWWW_UI_UNLOCKED == true and not MAWWW_Compact then
            task.defer(MAWWW_CenterWindow)
        end
    end)
end
MAWWW_BindViewportCamera(Workspace.CurrentCamera)
Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
    MAWWW_BindViewportCamera(Workspace.CurrentCamera)
    if MAWWW_UI_UNLOCKED == true and not MAWWW_Compact then
        task.defer(MAWWW_CenterWindow)
    end
end)

--========================================================--
-- FLOATING LAUNCHER
--========================================================--
function MAWWW_BuildFloatingLauncher()
    -- A rebuilt launcher must never inherit a stuck drag state from the old button.
    FloatDragging = false
    FloatDidMove = false
    FloatDragMode = nil
    FloatActiveTouchInput = nil
FloatingGui = Instance.new("ScreenGui")
FloatingGui.Name = "MawwwHubFloating"
FloatingGui.ResetOnSpawn = false
FloatingGui.IgnoreGuiInset = true
FloatingGui.DisplayOrder = 1000000
FloatingGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
FloatingGui.Enabled = true
FloatingGui:SetAttribute("MawwwPatchedLauncher", true)

-- Always prefer PlayerGui for the launcher. It is independent from Fluent's window.
PlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui") or PlayerGui
FloatingParent = PlayerGui
pcall(function()
    FloatingGui.Parent = FloatingParent
end)

FloatingButton = Instance.new("ImageButton")
FloatingButton.Name = "MawwwHubFloatingButton"
FloatingButton.Size = _mawwwIsMobile and UDim2.fromOffset(50, 50) or UDim2.fromOffset(56, 56)
FloatingButton.Position = UDim2.fromOffset(18, 220)
FloatingButton.AnchorPoint = Vector2.new(0, 0)
FloatingButton.BackgroundColor3 = Color3.fromRGB(20, 14, 28)
FloatingButton.BackgroundTransparency = 0.08
FloatingButton.BorderSizePixel = 0
FloatingButton.AutoButtonColor = false
FloatingButton.Image = ""
FloatingButton.Active = true
FloatingButton.Selectable = true
FloatingButton.ZIndex = 100
FloatingButton.Parent = FloatingGui
Corner(FloatingButton, _mawwwIsMobile and 13 or 15)
Stroke(FloatingButton, Theme.Accent, 1.4)

FloatingIcon = Instance.new("ImageLabel")
FloatingIcon.Name = "Icon"
FloatingIcon.Size = UDim2.new(1, -8, 1, -8)
FloatingIcon.Position = UDim2.fromOffset(4, 4)
FloatingIcon.BackgroundTransparency = 1
FloatingIcon.Image = MAWWW_FLOATING_ICON_ID
FloatingIcon.ImageTransparency = 0
FloatingIcon.ScaleType = Enum.ScaleType.Fit
FloatingIcon.ZIndex = 101
FloatingIcon.Parent = FloatingButton

FloatingFallback = Instance.new("TextLabel")
FloatingFallback.Name = "Fallback"
FloatingFallback.Size = UDim2.fromScale(1, 1)
FloatingFallback.BackgroundTransparency = 1
FloatingFallback.Text = "M"
FloatingFallback.TextColor3 = Theme.Accent
FloatingFallback.TextSize = _mawwwIsMobile and 22 or 25
FloatingFallback.Font = Enum.Font.GothamBold
FloatingFallback.ZIndex = 102
FloatingFallback.Visible = false
FloatingFallback.Parent = FloatingButton
    if typeof(MAWWW_FloatLastPos) == "UDim2" then
        FloatingButton.Position = MAWWW_FloatLastPos
    end
end
MAWWW_BuildFloatingLauncher()

MAWWW_FloatingWantedVisible = false
FloatDragging = false
FloatDragStart = nil
FloatStartPos = nil
FloatDidMove = false
FloatSuppressActivatedUntil = 0
FLOAT_DRAG_THRESHOLD = 6
MAWWW_FluentShow = nil
MinTopButton = nil

function MAWWW_ClampFloatingPosition()
    pcall(function()
        local camera = Workspace.CurrentCamera
        if not camera then return end
        local vp = camera.ViewportSize
        local size = FloatingButton.AbsoluteSize

        -- Keep calculations in the same coordinate space as GuiObject.Position.
        -- Mixing AbsolutePosition with UDim2 offsets can introduce a top inset
        -- difference, which made the launcher jump upward on touch devices.
        local current = FloatingButton.Position
        local maxX = math.max(6, vp.X - size.X - 6)
        local maxY = math.max(6, vp.Y - size.Y - 6)
        local x = math.clamp(current.X.Offset, 6, maxX)
        local y = math.clamp(current.Y.Offset, 6, maxY)
        FloatingButton.Position = UDim2.fromOffset(math.floor(x), math.floor(y))
    end)
end

-- Drag is locked to the pointer that started it. This avoids multi-touch jumps
-- and prevents unrelated touches elsewhere on the screen from moving the icon.
FloatActiveTouchInput = nil
FloatDragMode = nil

function MAWWW_EndFloatingDrag(input)
    if not FloatDragging then return end

    if FloatDragMode == "Mouse" then
        if not input or input.UserInputType ~= Enum.UserInputType.MouseButton1 then
            return
        end
    elseif FloatDragMode == "Touch" then
        if not input or input ~= FloatActiveTouchInput then
            return
        end
    else
        return
    end

    FloatDragging = false
    FloatDragMode = nil
    FloatActiveTouchInput = nil
    MAWWW_ClampFloatingPosition()
    pcall(function() MAWWW_FloatLastPos = FloatingButton.Position end)

    if FloatDidMove then
        FloatSuppressActivatedUntil = os.clock() + 0.30
        -- Keep the moved flag long enough to absorb the Activated event that
        -- Roblox may emit after the finger/mouse is released.
        task.delay(0.35, function()
            if os.clock() >= FloatSuppressActivatedUntil then
                FloatDidMove = false
            end
        end)
    else
        FloatDidMove = false
    end
    FloatDragStart = nil
    FloatStartPos = nil
end

-- Button-bound handlers live in a function so a rebuilt launcher gets them again.
function MAWWW_BindFloatingButton()
FloatingButton.InputBegan:Connect(function(input)
    local inputType = input.UserInputType
    if inputType ~= Enum.UserInputType.MouseButton1
        and inputType ~= Enum.UserInputType.Touch then
        return
    end
    if FloatDragging then return end

    FloatDragging = true
    FloatDidMove = false
    FloatDragStart = Vector2.new(input.Position.X, input.Position.Y)

    -- Save the actual offset-based Position, not AbsolutePosition. Both the
    -- movement delta and the destination now use one coordinate space.
    local currentPosition = FloatingButton.Position
    FloatStartPos = Vector2.new(currentPosition.X.Offset, currentPosition.Y.Offset)

    if inputType == Enum.UserInputType.Touch then
        FloatDragMode = "Touch"
        FloatActiveTouchInput = input
        -- Some clients report touch release more reliably through the
        -- InputObject state than through the global InputEnded event.
        input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then
                MAWWW_EndFloatingDrag(input)
            end
        end)
    else
        FloatDragMode = "Mouse"
        FloatActiveTouchInput = nil
    end
end)

FloatingButton.Activated:Connect(function()
    if not MAWWW_UI_UNLOCKED then return end
    if FloatDragging then return end
    if os.clock() < FloatSuppressActivatedUntil then return end
    if FloatDidMove then
        FloatDidMove = false
        return
    end
    if type(MAWWW_FluentShow) == "function" then
        MAWWW_FluentShow()
    end
end)

    -- If the launcher is removed (parent cleared / PlayerGui rebuilt / Destroy),
    -- recreate or re-parent it instead of leaving the hub impossible to reopen.
    local boundGui = FloatingGui
    MAWWW_Conn(boundGui.AncestryChanged, function()
        if MAWWW_RUN.dead then return end
        if boundGui ~= FloatingGui then return end
        if boundGui.Parent ~= PlayerGui then
            task.defer(MAWWW_EnsureFloatingGui)
        end
    end)
end
MAWWW_BindFloatingButton()

MAWWW_Conn(UserInputService.InputChanged, function(input)
    if not FloatDragging or not FloatDragStart or not FloatStartPos then return end

    local pointerMatches = false
    if FloatDragMode == "Mouse" then
        pointerMatches = input.UserInputType == Enum.UserInputType.MouseMovement
    elseif FloatDragMode == "Touch" then
        pointerMatches = input == FloatActiveTouchInput
    end
    if not pointerMatches then return end

    local pointerPosition = Vector2.new(input.Position.X, input.Position.Y)
    local delta = pointerPosition - FloatDragStart
    if math.abs(delta.X) > FLOAT_DRAG_THRESHOLD or math.abs(delta.Y) > FLOAT_DRAG_THRESHOLD then
        FloatDidMove = true
    end

    local camera = Workspace.CurrentCamera
    if not camera then return end
    local viewport = camera.ViewportSize
    local size = FloatingButton.AbsoluteSize
    local maxX = math.max(6, viewport.X - size.X - 6)
    local maxY = math.max(6, viewport.Y - size.Y - 6)
    local x = math.clamp(FloatStartPos.X + delta.X, 6, maxX)
    local y = math.clamp(FloatStartPos.Y + delta.Y, 6, maxY)
    FloatingButton.Position = UDim2.fromOffset(math.floor(x), math.floor(y))
end)

MAWWW_Conn(UserInputService.InputEnded, function(input)
    MAWWW_EndFloatingDrag(input)
end)

function MAWWW_EnsureFloatingGui()
    if MAWWW_RUN.dead then return end
    -- PlayerGui can be replaced by the game; always refresh the reference.
    PlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui") or PlayerGui
    local alive = FloatingGui ~= nil and FloatingButton ~= nil
    if alive then
        local okParent = pcall(function()
            if FloatingGui.Parent ~= PlayerGui then FloatingGui.Parent = PlayerGui end
        end)
        -- A destroyed ScreenGui rejects re-parenting: rebuild it instead.
        if not okParent or FloatingGui.Parent ~= PlayerGui then alive = false end
    end
    if not alive then
        local okBuild = pcall(MAWWW_BuildFloatingLauncher)
        if okBuild then
            pcall(MAWWW_BindFloatingButton)
            pcall(function() FloatingButton.Visible = MAWWW_FloatingWantedVisible == true end)
        end
    end
    pcall(function()
        FloatingGui.Enabled = true
        FloatingGui.DisplayOrder = 1000000
        FloatingButton.Active = true
        FloatingButton.Selectable = true
    end)
end

function MAWWW_SetFloatingVisible(visible)
    visible = visible == true
    -- The launcher is only allowed while the main hub is intentionally hidden
    -- (the X/close action). A panel toggle must never make a second icon appear.
    if visible and MAWWW_UI_WANTED_VISIBLE == true then
        visible = false
    end
    MAWWW_FloatingWantedVisible = visible
    if visible then
        -- A drag that never received its InputEnded (button hidden mid-drag) must not block Activated.
        FloatDragging = false
        FloatDidMove = false
        FloatDragMode = nil
        FloatActiveTouchInput = nil
    end
    MAWWW_EnsureFloatingGui()
    pcall(function()
        FloatingGui.Enabled = true
        FloatingButton.Visible = visible
        FloatingButton.Active = visible
        FloatingButton.Selectable = visible
    end)
    -- When a feature panel creates a legacy logo after startup, immediately hide
    -- it instead of waiting for the periodic duplicate sweep.
    if type(MAWWW_HideNativeWhiteLogo) == "function" then
        task.defer(function() pcall(MAWWW_HideNativeWhiteLogo) end)
    end
end

task.spawn(function()
    while FloatingGui and not MAWWW_RUN.dead do
        task.wait(0.5)
        if MAWWW_FloatingWantedVisible then
            MAWWW_EnsureFloatingGui()
            pcall(function()
                FloatingButton.Visible = true
                FloatingButton.Active = true
            end)
        end
    end
end)

function MAWWW_SetContentVisible(visible)
    visible = visible == true
    -- Obsidian exposes the active content pages and nav buttons per tab.
    pcall(function()
        local activeTab = Window.ActiveTab
        for _, tab in ipairs(Window.Tabs or {}) do
            if tab.Page then
                tab.Page.Visible = visible and (activeTab == nil or tab == activeTab)
            end
            if tab.Button then tab.Button.Visible = visible end
        end
    end)
    -- Keep header and our own minimize/close controls visible in compact mode.
    pcall(function() if Window.SearchBox then Window.SearchBox.Visible = visible end end)
end

function MAWWW_RestoreFull()
    MAWWW_Compact = false
    if MinTopButton then MinTopButton.Text = "−" end
    MAWWW_SetContentVisible(true)
    pcall(function()
        local restoreSize = MAWWW_SavedSize or _mawwwWindowSize
        Window.Size = restoreSize
        if Window.Root then
            Window.Root.Size = restoreSize
            Window.Root.Visible = true
        end
        MAWWW_CenterWindow()
    end)
end

function MAWWW_SetCompact()
    pcall(function()
        if Window.Size then
            MAWWW_SavedSize = Window.Size
        end
    end)

    MAWWW_Compact = true
    if MinTopButton then MinTopButton.Text = "+" end
    MAWWW_UI_WANTED_VISIBLE = true
    MAWWW_SetContentVisible(false)
    MAWWW_SetFloatingVisible(false)

    local compactW = _mawwwIsMobile and 520 or 680
    local compactH = _mawwwIsMobile and 58 or 64
    local compactSize = UDim2.fromOffset(compactW, compactH)

    pcall(function()
        Window.Size = compactSize
        if Window.Root then
            Window.Root.Size = compactSize
            Window.Root.Visible = true
        end
        MAWWW_CenterWindow()
    end)
end

MAWWW_FluentShow = function()
    if not MAWWW_UI_UNLOCKED then return end
    MAWWW_UI_WANTED_VISIBLE = true
    MAWWW_SetWindowScreenEnabled(true)
    MAWWW_RestoreFull()
    if MinTopButton then MinTopButton.Text = "−" end
    pcall(function() Window:Show() end)
    MAWWW_SetWindowScreenEnabled(true)
    pcall(function()
        if Window.Root then Window.Root.Visible = true end
    end)
    MAWWW_CenterWindow()
    task.defer(MAWWW_CenterWindow)
    task.delay(0.12, MAWWW_CenterWindow)
    task.delay(0.35, MAWWW_CenterWindow)
    if type(MAWWW_HideNativeWhiteLogo) == "function" then
        task.defer(MAWWW_HideNativeWhiteLogo)
        task.delay(0.20, MAWWW_HideNativeWhiteLogo)
    end
    MAWWW_SetFloatingVisible(false)
end

function MAWWW_FluentHide(showFloating)
    MAWWW_UI_WANTED_VISIBLE = false
    MAWWW_Compact = false
    MAWWW_SetContentVisible(true)
    pcall(function() Window:Hide() end)
    pcall(function()
        if Window.Root then Window.Root.Visible = false end
    end)
    MAWWW_SetWindowScreenEnabled(false)
    MAWWW_SetFloatingVisible(showFloating == true)
end

function MAWWW_FluentSetVisible(visible)
    visible = visible == true
    if not MAWWW_UI_UNLOCKED then
        MAWWW_UI_WANTED_VISIBLE = false
        pcall(function() Window:Hide() end)
        pcall(function()
            if Window.Root then Window.Root.Visible = false end
        end)
        MAWWW_SetFloatingVisible(false)
        return
    end
    if visible then
        MAWWW_FluentShow()
    else
        MAWWW_FluentHide(true)
    end
end

getgenv().MAWWW_SetUIVisible = MAWWW_FluentSetVisible

--========================================================--
-- TOP TITLE-BAR BUTTONS (custom, independent of Obsidian's native actions)
-- - = compact/minimize; tap again to restore
-- X = hide the main window and show the floating launcher
--========================================================--
function MAWWW_IsLikelyTopRightControl(obj)
    if not obj or not obj:IsA("GuiButton") then return false end

    local name = string.lower(tostring(obj.Name or ""))
    if name:sub(1, 12) == "mawwwhub_top" then return false end

    local ancestor = obj.Parent
    while ancestor do
        if ancestor.Name == "MawwwHub_CustomTopControls" then return false end
        if ancestor == (Window and Window.Root) then break end
        ancestor = ancestor.Parent
    end

    local root = Window and Window.Root
    if not root then return false end
    local rootSize = root.AbsoluteSize
    if rootSize.X <= 0 or rootSize.Y <= 0 then return false end

    -- This area includes slightly taller title bars used by some Fluent builds.
    -- It is deliberately limited to small controls at the right edge of the
    -- window so feature buttons in tabs are never removed.
    local relX = obj.AbsolutePosition.X - root.AbsolutePosition.X
    local relY = obj.AbsolutePosition.Y - root.AbsolutePosition.Y
    local size = obj.AbsoluteSize
    local smallButton = size.X > 0 and size.X <= 54 and size.Y > 0 and size.Y <= 54
    local inTitleRight = smallButton
        and relY >= -6 and relY <= 68
        and relX >= (rootSize.X - 150)
        and relX <= (rootSize.X + 6)
    if not inTitleRight then return false end

    local exactControlNames = {
        close = true, closebutton = true, xbutton = true, exitbutton = true,
        minbutton = true, minimizebutton = true, minimizebtn = true,
        minimize = true, minusbutton = true, minimize_button = true,
        maxbutton = true, maximizebutton = true, maximize = true,
    }
    if exactControlNames[name] then return true end

    local text, image = "", ""
    pcall(function() text = string.lower(tostring(obj.Text or "")) end)
    pcall(function() image = string.lower(tostring(obj.Image or "")) end)
    local textMatch = text == "x" or text == "×" or text == "-"
        or text == "−" or text == "–" or text == "+" or text == "□"
    local imageMatch = image:find("close", 1, true) ~= nil
        or image:find("minus", 1, true) ~= nil
        or image:find("minimize", 1, true) ~= nil
        or image:find("maximize", 1, true) ~= nil

    -- Native controls are small buttons in this title-bar strip; hide them so
    -- only Mawww Hub's single custom minimize and close buttons remain visible.
    return textMatch or imageMatch or inTitleRight
end

function MAWWW_DisableNativeTopRightControl(obj)
    if not MAWWW_IsLikelyTopRightControl(obj) then return end
    pcall(function()
        obj.Active = false
        obj.Selectable = false
        obj.Interactable = false
        obj.Visible = false
    end)
end

function MAWWW_DisableExistingNativeTopControls()
    pcall(function()
        local root = Window and Window.Root
        if not root then return end

        -- First scan the window itself.
        for _, obj in ipairs(root:GetDescendants()) do
            MAWWW_DisableNativeTopRightControl(obj)
        end

        -- Some Fluent-modded versions keep the title buttons as siblings of
        -- the root window frame, inside the same ScreenGui.
        local screenGui = root:FindFirstAncestorOfClass("ScreenGui")
        if screenGui then
            for _, obj in ipairs(screenGui:GetDescendants()) do
                MAWWW_DisableNativeTopRightControl(obj)
            end
        end
    end)
end

-- Run after layout/animation settles and catch late-created native controls.
MAWWW_DisableExistingNativeTopControls()
task.defer(MAWWW_DisableExistingNativeTopControls)
for _, delaySeconds in ipairs({0.10, 0.25, 0.50, 0.90, 1.40, 2.00}) do
    task.delay(delaySeconds, MAWWW_DisableExistingNativeTopControls)
end
pcall(function()
    if Window.Root then
        Window.Root.DescendantAdded:Connect(function(obj)
            task.defer(function()
                MAWWW_DisableNativeTopRightControl(obj)
            end)
        end)
        local screenGui = Window.Root:FindFirstAncestorOfClass("ScreenGui")
        if screenGui then
            screenGui.DescendantAdded:Connect(function(obj)
                task.defer(function()
                    MAWWW_DisableNativeTopRightControl(obj)
                end)
            end)
        end
    end
end)

TopControls = Instance.new("Frame")
TopControls.Name = "MawwwHub_CustomTopControls"
TopControls.BackgroundTransparency = 1
TopControls.BorderSizePixel = 0
TopControls.AnchorPoint = Vector2.new(1, 0)
TopControls.Position = UDim2.new(1, -4, 0, 1)
TopControls.Size = UDim2.fromOffset(76, 34)
TopControls.ZIndex = 125
TopControls.Active = false
TopControls.ClipsDescendants = false
TopControls.Parent = Window.Root

function MAWWW_CreateTopButton(name, text, xOffset, textColor, callback)
    local button = Instance.new("TextButton")
    button.Name = name
    button.BackgroundColor3 = Color3.fromRGB(24, 25, 31)
    button.BackgroundTransparency = 0.20
    button.BorderSizePixel = 0
    button.AutoButtonColor = false
    button.Active = true
    button.Selectable = true
    button.Size = UDim2.fromOffset(34, 30)
    button.Position = UDim2.fromOffset(xOffset, 1)
    button.Font = Enum.Font.GothamBold
    button.Text = text
    button.TextSize = text == "×" and 23 or 21
    button.TextColor3 = textColor
    button.ZIndex = 126
    button.Parent = TopControls
    pcall(function() Corner(button, 7) end)
    pcall(function() Stroke(button, Theme.Border or Theme.Accent, 1) end)
    button.Activated:Connect(function()
        if not MAWWW_UI_UNLOCKED then return end
        local ok, err = pcall(callback)
        if not ok then
            warn("[Mawww Hub] Title-bar button failed:", err)
        end
    end)
    return button
end

