-- Lightweight compatibility wrapper for the old V3/V4 source modules.
Library = {
    _configFlags = {},
    Scheme = {},
    ShowCustomCursor = false,
}

function Library:Notify(payload)
    payload = payload or {}
    if SUPPRESS_NOTIFY == true then return end
    local title = tostring(payload.Title or payload.title or "Mawww Hub")
    local content = tostring(payload.Description or payload.Content or payload.message or "")
    if not MAWWW_AllowNotification(title, content) then return end
    pcall(function()
        Fluent:Notify({
            Title = title,
            Content = content,
            Duration = math.min(tonumber(payload.Time or payload.Duration) or 4, 3.5),
            Type = tostring(payload.Type or "Info"),
            Icon = payload.Icon or "info",
        })
    end)
end

function Library:Unload()
    getgenv().MAWWW_SetUIVisible(false)
end

function Library:Toggle()
    if MAWWW_UI_WANTED_VISIBLE then
        getgenv().MAWWW_SetUIVisible(false)
    else
        getgenv().MAWWW_SetUIVisible(true)
    end
end

function Library:MakeDraggable()
    -- Fluent handles its own draggable window/minimizer behavior.
end

function Library:RefreshCursor() end
function Library:SetNotifySide() end

getgenv().MAWWW_MawwwHub_Library = Library

-- Ensure every returned Fluent element still exposes the methods expected by
-- the existing config system (SetValue/Set/Get/Refresh/SetValues).
function MAWWW_InvokeElementMethod(raw, methodName, ...)
    if not raw then return false, nil end
    local fn = raw[methodName]
    if type(fn) ~= "function" then return false, nil end
    local args = {...}
    return pcall(function()
        return fn(raw, table.unpack(args))
    end)
end

function MAWWW_WrapElement(raw)
    if not raw then return nil end
    local wrapper = { Raw = raw }

    function wrapper:Get()
        local ok, value = MAWWW_InvokeElementMethod(raw, "GetValue")
        if ok then return value end
        ok, value = MAWWW_InvokeElementMethod(raw, "Get")
        if ok then return value end
        local okValue, current = pcall(function() return raw.Value end)
        if okValue then return current end
        return nil
    end

    wrapper.GetValue = wrapper.Get

    function wrapper:Set(value)
        local ok, result = MAWWW_InvokeElementMethod(raw, "SetValue", value)
        if ok then return result end
        ok, result = MAWWW_InvokeElementMethod(raw, "Set", value)
        if ok then return result end
        return nil
    end

    wrapper.SetValue = wrapper.Set

    function wrapper:Refresh(values)
        local ok, result = MAWWW_InvokeElementMethod(raw, "SetValues", values)
        if ok then return result end
        ok, result = MAWWW_InvokeElementMethod(raw, "Refresh", values)
        if ok then return result end
        return nil
    end

    wrapper.SetValues = wrapper.Refresh
    setmetatable(wrapper, { __index = raw })
    return wrapper
end

function MAWWW_NormalizeMultiDefault(value)
    if type(value) ~= "table" then return value end
    if #value == 0 then return value end
    local map = {}
    for _, item in ipairs(value) do
        map[item] = true
    end
    return map
end

-- Lightweight Obsidian pages: batched canvas sizing, no page-slide tween, and reduced dashboard loops. Feature sections are
-- arranged into two real vertical columns. The single-column Home tab remains
-- full width. Section roots stay intact so Fluent's control API keeps working.
-- Obsidian tab/control compatibility adapter. All existing feature-registration
-- code below continues to call the same VDUI/MakeLogicTab methods.
local function MAWWW_ObsidianIcon(icon)
    local aliases = {
        house = "house", home = "house", dashboard = "layout-dashboard",
        settings = "settings", user = "user-round", player = "user-round",
        shield = "shield", survivor = "shield-check", swords = "swords", killer = "swords",
        crosshair = "crosshair", aim = "crosshair", eye = "eye", esp = "eye",
        image = "image", visuals = "image", zap = "zap", bot = "bot",
        automation = "bot", server = "server", utility = "server", utilities = "server",
        menu = "menu", userinfo = "info", ["circle-dot"] = "circle-dot",
        list = "list", wrench = "wrench", info = "info",
    }
    if type(icon) == "string" and (icon:match("^rbxassetid://") or icon:match("^https?://")) then
        return icon
    end
    local key = string.lower(tostring(icon or "list"))
    return aliases[key] or "list"
end

local function MAWWW_ObsidianFrame(raw)
    if type(raw) ~= "table" then return nil end
    local frame = raw.Frame or raw.Holder or raw.Base or raw.TextLabel or raw.Label
    if frame and typeof(frame) == "Instance" and frame:IsA("GuiObject") then
        raw.Frame = raw.Frame or frame
    end
    return raw.Frame
end

local MAWWW_ObsidianLabelCounter = 0
local function MAWWW_ObsidianLabel(nativeBox, text, size, wrap)
    MAWWW_ObsidianLabelCounter += 1
    local labelText = tostring(text or "")
    local labelId = "MawwwObsidianLabel_" .. tostring(MAWWW_ObsidianLabelCounter)
    local label

    -- Obsidian's current API uses AddLabel(id, options). Keep a fallback for
    -- versions that expose only the simpler AddLabel(text, doesWrap) overload.
    local ok, result = pcall(function()
        return nativeBox:AddLabel(labelId, {
            Text = labelText,
            Size = tonumber(size) or 11,
            DoesWrap = wrap ~= false,
        })
    end)
    if ok then label = result end
    if not label then
        local fallbackOk, fallback = pcall(function()
            return nativeBox:AddLabel(labelText, wrap ~= false)
        end)
        if fallbackOk then
            label = fallback
        else
            error(tostring(fallback))
        end
    end

    if type(label) == "table" then
        pcall(function()
            label.Frame = label.Frame or label.Holder or label.TextLabel or label.Label
        end)
    end
    return label
end

function MAWWW_ObsidianGroupboxAdapter(nativeBox, displayTitle)
    -- Compatibility adapter: legacy Mawww registrations stay unchanged, while
    -- controls are created using the AddSection/AddToggle/AddSlider API exposed by the UI library.
    local group = {
        _obsidianBox = nativeBox,
        _glutoSection = nativeBox,
        _mawwwTitle = displayTitle,
        Container = nativeBox and (nativeBox.Container or nativeBox.Holder or nativeBox.Frame or nativeBox.SectionFrame),
        Card = nativeBox and (nativeBox.Holder or nativeBox.Frame or nativeBox.SectionFrame),
    }

    local function decorate(raw)
        if type(raw) == "table" then
            MAWWW_ObsidianFrame(raw)
            if type(raw.GetValue) == "function" and type(raw.Get) ~= "function" then
                raw.Get = function(self) return self:GetValue() end
            end
            if type(raw.SetValue) == "function" and type(raw.Set) ~= "function" then
                raw.Set = function(self, value) return self:SetValue(value) end
            end
            if type(raw.SetValues) == "function" and type(raw.Refresh) ~= "function" then
                raw.Refresh = function(self, values) return self:SetValues(values) end
            end
        end
        return raw
    end

    local function callControl(methodName, config, fallbackName)
        local fn = nativeBox and nativeBox[methodName]
        if type(fn) == "function" then
            local ok, result = pcall(fn, nativeBox, config)
            if ok and result ~= false then return decorate(result) end
            warn("[Mawww Hub] UI control failed:", tostring(config and (config.Title or config.Text) or methodName), tostring(result))
        end
        if fallbackName and nativeBox and type(nativeBox[fallbackName]) == "function" then
            local ok, result = pcall(nativeBox[fallbackName], nativeBox, config)
            if ok then return decorate(result) end
        end
        return nil
    end

    function group:AddToggle(id, config)
        config = config or {}
        return callControl("AddToggle", {
            Title = tostring(config.Title or id or "Toggle"),
            Default = config.Default == true,
            Callback = config.Callback,
            Description = config.Description,
            Save = false,
        })
    end

    function group:AddSlider(id, config)
        config = config or {}
        local minValue = tonumber(config.Min) or 0
        local maxValue = tonumber(config.Max) or 100
        if maxValue < minValue then minValue, maxValue = maxValue, minValue end
        local initial = tonumber(config.Default)
        if initial == nil then initial = tonumber(config.Value) end
        if initial == nil then initial = minValue end
        initial = math.clamp(initial, minValue, maxValue)
        local decimals = tonumber(config.Rounding)
        if decimals == nil then decimals = formatRounding(config.Step) end
        decimals = math.clamp(tonumber(decimals) or 0, 0, 4)
        local increment = tonumber(config.Increment) or (10 ^ (-decimals))
        return callControl("AddSlider", {
            Title = tostring(config.Title or id or "Slider"),
            Default = initial,
            Min = minValue,
            Max = maxValue,
            Increment = increment,
            Decimals = decimals,
            Suffix = tostring(config.Suffix or ""),
            Callback = config.Callback,
            Save = false,
        })
    end

    function group:AddDropdown(id, config)
        config = config or {}
        local values = config.Values or config.Options or {}
        local multi = config.Multi == true
        local initial = config.Default
        if initial == nil then initial = config.Value end
        if multi then
            initial = MAWWW_NormalizeMultiDefault(initial)
            if type(initial) == "table" then
                local selected = {}
                for _, value in ipairs(values) do
                    if initial[value] == true then table.insert(selected, value) end
                end
                if #selected == 0 then
                    for key, value in pairs(initial) do
                        if value == true and type(key) == "string" then table.insert(selected, key) end
                    end
                end
                initial = selected
            else
                initial = {}
            end
        elseif initial == nil then
            initial = values[1] or ""
        elseif type(initial) == "string" and #values > 0 then
            local found = false
            for _, value in ipairs(values) do
                if tostring(value) == initial then found = true; break end
            end
            if not found then initial = values[1] or "" end
        end
        return callControl("AddDropdown", {
            Title = tostring(config.Title or id or "Dropdown"),
            Options = values,
            Values = values,
            Default = initial,
            Multi = multi,
            Callback = config.Callback,
            Save = false,
        })
    end

    function group:AddButton(config, callback)
        if type(config) ~= "table" then config = {Title = tostring(config or "Button"), Callback = callback} end
        return callControl("AddButton", {
            Title = tostring(config.Title or config.Text or "Button"),
            Description = config.Description or config.Tooltip,
            Callback = config.Callback or config.Func or config.CallbackFunction,
            Icon = config.Icon,
            Save = false,
        })
    end

    function group:AddInput(id, config)
        config = config or {}
        return callControl("AddInput", {
            Title = tostring(config.Title or id or "Input"),
            Default = tostring(config.Default or config.Value or ""),
            Placeholder = tostring(config.Placeholder or ""),
            PlaceholderText = tostring(config.Placeholder or ""),
            Numeric = config.Numeric == true,
            ClearOnFocus = config.ClearTextOnFocus == true,
            Callback = config.Callback,
            Save = false,
        }, "AddTextBox")
    end

    function group:AddDivider()
        if nativeBox and type(nativeBox.AddDivider) == "function" then
            local ok, result = pcall(function() return nativeBox:AddDivider() end)
            if ok then return result end
        end
        return callControl("AddParagraph", {Title = "", Content = "────────"})
    end

    function group:AddParagraph(config)
        config = config or {}
        local title = tostring(config.Title or "")
        local content = tostring(config.Content or config.Text or "")
        local raw = callControl("AddParagraph", {Title = title, Content = content, Save = false}, "AddLabel")
        if not raw and nativeBox and type(nativeBox.AddLabel) == "function" then
            raw = callControl("AddLabel", {Text = (title ~= "" and (title .. "\n") or "") .. content})
        end
        local result = {Raw = raw, Frame = raw and (raw.Frame or raw.Holder or raw.Label or raw.TextLabel) or nil}
        function result:Get()
            if raw then
                local ok, value = pcall(function()
                    if type(raw.GetValue) == "function" then return raw:GetValue() end
                    if type(raw.GetText) == "function" then return raw:GetText() end
                    if type(raw.Get) == "function" then return raw:Get() end
                    local inst = raw.Frame or raw.Holder or raw.Label or raw.TextLabel
                    if inst and inst:IsA("TextLabel") then return inst.Text end
                end)
                if ok and value ~= nil then return tostring(value) end
            end
            return content
        end
        function result:Set(value)
            content = tostring(value or "")
            if raw then
                pcall(function()
                    if type(raw.SetValue) == "function" then raw:SetValue(content)
                    elseif type(raw.SetText) == "function" then raw:SetText(content)
                    elseif type(raw.Set) == "function" then raw:Set(content)
                    else
                        local inst = raw.Frame or raw.Holder or raw.Label or raw.TextLabel
                        if inst and inst:IsA("TextLabel") then inst.Text = content end
                    end
                end)
            end
        end
        result.GetValue = result.Get
        result.SetValue = result.Set
        return result
    end

    function group:AddLabel(text)
        return self:AddParagraph({Content = tostring(text or "")})
    end

    function group:AddImage(config)
        config = config or {}
        local parent = self.Container
        if not parent or typeof(parent) ~= "Instance" or not parent:IsA("GuiObject") then
            return nil
        end
        local frame = Instance.new("Frame")
        frame.Name = "MawwwFeatureImage"
        frame.BackgroundTransparency = 1
        frame.BorderSizePixel = 0
        frame.Size = UDim2.new(1, 0, 0, tonumber(config.Height) or 118)
        frame.Parent = parent
        local image = Instance.new("ImageLabel")
        image.Name = "FeatureImage"
        image.BackgroundTransparency = 1
        image.BorderSizePixel = 0
        image.Size = UDim2.fromScale(1, 1)
        image.Image = tostring(config.Image or "")
        image.ScaleType = Enum.ScaleType.Crop
        image.Parent = frame
        return {Frame = frame, Instance = image, Get = function() return image.Image end, Set = function(_, value) image.Image = tostring(value or "") end, GetValue = function() return image.Image end, SetValue = function(_, value) image.Image = tostring(value or "") end}
    end

    function group:AddKeybind(id, config)
        config = config or {}
        local title = tostring(config.Title or id or "Keybind")
        local modeDefault = string.lower(tostring(config.Mode or "Toggle"))
        local currentName = tostring(config.Default or "RightAlt")
        local currentKeyCode, currentUserInputType
        local active = false
        local listening = false
        local frame, button

        local function applyKey(value)
            currentKeyCode, currentUserInputType = nil, nil
            if typeof(value) == "EnumItem" then
                currentName = value.Name
                if value.EnumType == Enum.KeyCode then
                    currentKeyCode = value
                elseif value.EnumType == Enum.UserInputType then
                    currentUserInputType = value
                end
            else
                currentName = tostring(value or "RightAlt")
                if currentName == "MB1" or currentName == "MouseButton1" then
                    currentUserInputType = Enum.UserInputType.MouseButton1
                elseif currentName == "MB2" or currentName == "MouseButton2" then
                    currentUserInputType = Enum.UserInputType.MouseButton2
                else
                    pcall(function() currentKeyCode = Enum.KeyCode[currentName] end)
                end
            end
        end
        applyKey(currentName)

        local function matchesInput(input)
            if currentUserInputType then
                return input.UserInputType == currentUserInputType
            end
            return input.UserInputType == Enum.UserInputType.Keyboard
                and currentKeyCode ~= nil and input.KeyCode == currentKeyCode
        end

        -- Use a small native row inside the section content. This avoids an empty
        -- shortcut group when the remote UI library lacks/changes AddKeybind.
        local parent = group.Container
        if parent and typeof(parent) == "Instance" and parent:IsA("GuiObject") then
            local order = 1
            pcall(function()
                for _, child in ipairs(parent:GetChildren()) do
                    if child:IsA("GuiObject") then order = math.max(order, (tonumber(child.LayoutOrder) or 0) + 1) end
                end
            end)

            frame = Instance.new("Frame")
            frame.Name = "MawwwKeybind_" .. tostring(id):gsub("[^%w_%-]", "_")
            frame.BackgroundTransparency = 1
            frame.BorderSizePixel = 0
            frame.Size = UDim2.new(1, 0, 0, 38)
            frame.LayoutOrder = order
            frame.Parent = parent

            -- If the UI library does not provide a direct UIListLayout for this
            -- section, place each key row after the existing section contents.
            local hasDirectListLayout = false
            pcall(function() hasDirectListLayout = parent:FindFirstChildOfClass("UIListLayout") ~= nil end)
            if not hasDirectListLayout then
                local bottom = 0
                pcall(function()
                    for _, child in ipairs(parent:GetChildren()) do
                        if child ~= frame and child:IsA("GuiObject") then
                            local top = child.Position.Y.Offset + child.Position.Y.Scale * parent.AbsoluteSize.Y
                            local height = child.AbsoluteSize.Y
                            if height <= 0 then height = child.Size.Y.Offset end
                            bottom = math.max(bottom, top + height)
                        end
                    end
                    frame.Position = UDim2.fromOffset(0, bottom + 5)
                    if parent:IsA("ScrollingFrame") then
                        local canvas = parent.CanvasSize
                        parent.CanvasSize = UDim2.new(canvas.X.Scale, canvas.X.Offset, canvas.Y.Scale, math.max(canvas.Y.Offset, bottom + 48))
                    end
                end)
            end

            local label = Instance.new("TextLabel")
            label.Name = "TitleLabel"
            label.BackgroundTransparency = 1
            label.BorderSizePixel = 0
            label.Position = UDim2.fromOffset(2, 0)
            label.Size = UDim2.new(1, -102, 1, 0)
            label.Font = Enum.Font.GothamMedium
            label.Text = title
            label.TextSize = 12
            label.TextColor3 = (Theme and Theme.Text) or Color3.fromRGB(238, 238, 245)
            label.TextXAlignment = Enum.TextXAlignment.Left
            label.TextYAlignment = Enum.TextYAlignment.Center
            label.TextWrapped = true
            label.Parent = frame

            button = Instance.new("TextButton")
            button.Name = "KeybindButton"
            button.AnchorPoint = Vector2.new(1, 0.5)
            button.Position = UDim2.new(1, -2, 0.5, 0)
            button.Size = UDim2.fromOffset(92, 28)
            button.BackgroundColor3 = (Theme and (Theme.Surface or Theme.Background)) or Color3.fromRGB(30, 25, 38)
            button.BorderSizePixel = 0
            button.AutoButtonColor = true
            button.Font = Enum.Font.GothamBold
            button.Text = currentName
            button.TextSize = 12
            button.TextColor3 = (Theme and Theme.Text) or Color3.fromRGB(250, 250, 255)
            button.TextTruncate = Enum.TextTruncate.AtEnd
            button.Parent = frame

            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(0, 7)
            corner.Parent = button
            local stroke = Instance.new("UIStroke")
            stroke.Thickness = 1
            stroke.Color = (Theme and Theme.Border) or Color3.fromRGB(76, 58, 94)
            stroke.Transparency = 0.15
            stroke.Parent = button

            button.Activated:Connect(function()
                -- On touch-only devices, avoid leaving a key row stuck at "Press key...".
                -- A hardware keyboard is needed for keyboard-based rebinding/activation.
                if not UserInputService.KeyboardEnabled then
                    button.Text = currentName
                    pcall(function()
                        if type(notify) == "function" then
                            notify("Keyboard Shortcut", "Connect a hardware keyboard to change or activate keyboard shortcuts.", 3)
                        end
                    end)
                    return
                end
                listening = true
                button.Text = "Press key..."
                button.TextColor3 = (Theme and Theme.Accent) or Color3.fromRGB(168, 85, 247)
            end)
        else
            -- Last-resort native API if this library exposes no accessible section container.
            local fallback = callControl("AddKeybind", {
                Title = title,
                Default = currentKeyCode or currentUserInputType or Enum.KeyCode.RightAlt,
                Callback = function(value) applyKey(value) end,
                Save = false,
            })
            if fallback then
                return {
                    Raw = fallback, Picker = fallback,
                    Get = function() return currentName end,
                    GetValue = function() return currentName end,
                    Set = function(_, value) applyKey(value) end,
                    SetValue = function(_, value) applyKey(value) end,
                }
            end
            warn("[Mawww Hub] Keybind row could not be created: section content container unavailable")
            return nil
        end

        local function runCallback(value)
            if type(config.Callback) == "function" then
                local ok, err = pcall(config.Callback, value)
                if not ok then warn("[Mawww Hub] Keybind callback failed:", tostring(err)) end
            end
        end

        local beganConnection = MAWWW_Conn(UserInputService.InputBegan, function(input, processed)
            if listening then
                if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode ~= Enum.KeyCode.Unknown then
                    if input.KeyCode == Enum.KeyCode.Escape then
                        listening = false
                        if button and button.Parent then
                            button.Text = currentName
                            button.TextColor3 = (Theme and Theme.Text) or Color3.fromRGB(250, 250, 255)
                        end
                    else
                        applyKey(input.KeyCode)
                        listening = false
                        if button and button.Parent then
                            button.Text = currentName
                            button.TextColor3 = (Theme and Theme.Text) or Color3.fromRGB(250, 250, 255)
                        end
                    end
                end
                return
            end
            if processed or UserInputService:GetFocusedTextBox() then return end
            if not matchesInput(input) then return end
            local mode = modeDefault
            if mode == "always" then return
            elseif mode == "press" then
                runCallback(true)
            elseif mode == "hold" then
                if not active then active = true; runCallback(true) end
            else
                active = not active
                runCallback(active)
            end
        end)
        local endedConnection = MAWWW_Conn(UserInputService.InputEnded, function(input)
            if not matchesInput(input) then return end
            if modeDefault == "hold" and active then active = false; runCallback(false) end
        end)

        local result = {
            Type = "Keybind",
            Frame = frame, Instance = button,
            Connections = {beganConnection, endedConnection},
        }
        function result:Get() return currentName end
        function result:GetValue() return currentName end
        function result:Set(value)
            applyKey(value)
            if button and button.Parent then
                button.Text = currentName
                button.TextColor3 = (Theme and Theme.Text) or Color3.fromRGB(250, 250, 255)
            end
        end
        result.SetValue = result.Set
        return result
    end

    function group:AddColorpicker(id, config)
        config = config or {}
        local initial = config.Default or config.Value or Theme.Accent or Color3.fromRGB(168, 85, 247)
        local raw = callControl("AddColorPicker", {
            Title = tostring(config.Title or id or "Color"),
            Default = initial,
            Transparency = config.Transparency,
            Callback = config.Callback,
            Save = false,
        }, "AddColorpicker")
        local result = {Raw = raw, Picker = raw, Frame = raw and (raw.Frame or raw.Holder) or nil}
        function result:Get()
            if raw then
                local ok, value = pcall(function()
                    if type(raw.GetValue) == "function" then return raw:GetValue() end
                    if type(raw.Get) == "function" then return raw:Get() end
                    return raw.Value or raw.Color
                end)
                if ok and value ~= nil then return value end
            end
            return initial
        end
        function result:Set(value)
            if raw then pcall(function() if type(raw.SetValue) == "function" then raw:SetValue(value) elseif type(raw.Set) == "function" then raw:Set(value) end end) end
        end
        result.GetValue = result.Get
        result.SetValue = result.Set
        return result
    end

    return group
end

VDUI = {
    Tabs = {},
    TabOrder = {},
    NativeEntries = {},
    Destroyed = false,
}

function MAWWW_CreateFluentFeatureTab(name, icon, singleColumn)
    local destinationName = MAWWW_TAB_NAME_MAP[tostring(name)] or tostring(name)
    local cachedEntry = VDUI.NativeEntries and VDUI.NativeEntries[destinationName]
    if cachedEntry then return cachedEntry end
    local order = #Window.Tabs + 1
    local nativeTab = Window:AddTab({
        Name = destinationName,
        Icon = MAWWW_ObsidianIcon(icon),
        Order = order,
    })
    if type(nativeTab) ~= "table" then
        error("AddTab did not return a tab object for " .. tostring(name))
    end
    local entry = {
        _fluent = nativeTab,
        _obsidianTab = nativeTab,
        _starTab = nativeTab,
        _glutoTab = nativeTab,
        _left = nil,
        _right = nil,
        _columnLayout = nil,
        _singleColumn = singleColumn == true,
        _leftOrder = 0,
        _rightOrder = 0,
        index = nil,
        name = destinationName,
        Page = nativeTab.Container or nativeTab.Page or nativeTab.Content,
        Button = nativeTab.Button or nativeTab.TabButton,
        LeftCol = nil,
        RightCol = nil,
        Container = nativeTab.Container or nativeTab.Page or nativeTab.Content,
    }
    if entry.Button and entry.Button.Activated then
        entry.Button.Activated:Connect(function() Window.ActiveTab = entry end)
    end
    table.insert(Window.Tabs, entry)
    VDUI.NativeEntries[destinationName] = entry
    if not Window.ActiveTab then Window.ActiveTab = entry end
    return entry
end

function VDUI:AddTab(name, icon, singleColumn)
    name = tostring(name or "Tab")
    local entry = MAWWW_CreateFluentFeatureTab(name, icon, singleColumn)
    entry.index = #self.TabOrder + 1

    function entry:AddGroupbox(side, title)
        local displayTitle = MAWWW_CleanSectionTitle(title or "Section")
        local ok, nativeBox = pcall(function()
            return self._glutoTab:AddSection(displayTitle)
        end)
        if not ok or not nativeBox then
            warn("[Mawww Hub] UI section failed:", displayTitle, tostring(nativeBox))
            return nil
        end
        return MAWWW_ObsidianGroupboxAdapter(nativeBox, displayTitle)
    end

    self.Tabs[name] = entry
    table.insert(self.TabOrder, name)
    return entry
end

function VDUI:SelectTab(name)
    local entry = self.Tabs[tostring(name or "")]
    local tab = entry and (entry._glutoTab or entry._obsidianTab)
    if not tab then return false end
    local ok, err = pcall(function()
        if type(tab.Select) == "function" then tab:Select()
        elseif type(tab.Show) == "function" then tab:Show()
        elseif type(tab.Activate) == "function" then tab:Activate()
        elseif Window.Native and type(Window.Native.SelectTab) == "function" then Window.Native:SelectTab(tab) end
        Window.ActiveTab = entry
    end)
    if not ok then warn("[Mawww Hub] Could not select tab:", tostring(name), tostring(err)) end
    return ok
end

function VDUI:Notify(title, message, duration, typ, icon)
    if SUPPRESS_NOTIFY == true then return end
    title = tostring(title or "Mawww Hub")
    message = tostring(message or "")
    if not MAWWW_AllowNotification(title, message) then return end
    pcall(function()
        Fluent:Notify({
            Title = title,
            Content = message,
            Duration = math.min(tonumber(duration) or 4, 3.5),
            Type = tostring(typ or "Info"),
            Icon = icon or "info",
        })
    end)
end

function VDUI:SetBackgroundAsset() end
function VDUI:SetBackgroundVideo() end

-- Compact feature rows and let the themed UI show through the controls.
-- Desc labels are kept to one line in narrow two-column groupboxes so controls
-- such as Parry Range/Distance do not expand vertically and create huge gaps.
-- Consistent feature-row styling. Keep this strictly presentational: callbacks,
-- state keys, and element instances are not replaced.
function MAWWW_HideFeatureDescription(object)
    if not object or not object:IsA("TextLabel") then return end
    local lowerName = string.lower(tostring(object.Name or ""))
    if not (lowerName:find("desc", 1, true) or lowerName:find("description", 1, true)) then return end
    pcall(function()
        object.Visible = false
        object.TextWrapped = false
        object.TextScaled = false
        object.AutomaticSize = Enum.AutomaticSize.None
        object.Size = UDim2.new(object.Size.X.Scale, object.Size.X.Offset, 0, 0)
    end)
end

function MAWWW_StyleFeatureText(object)
    if not object or not object:IsA("TextLabel") then return end
    MAWWW_HideFeatureDescription(object)
    if not object.Visible then return end

    -- Control labels are tagged by MAWWW_CompactFeatureElement. Keep long names
    -- readable instead of truncating them to "Abyss..." / "Killer Facing...".
    local controlKind = nil
    pcall(function() controlKind = object:GetAttribute("MAWWWControlTextKind") end)
    if controlKind then
        pcall(function()
            object.TextScaled = false
            object.TextTruncate = Enum.TextTruncate.None
            object.TextWrapped = true
            object.TextXAlignment = Enum.TextXAlignment.Left
            object.TextYAlignment = Enum.TextYAlignment.Center
            if controlKind == "Toggle" then
                object.TextSize = math.clamp(tonumber(object.TextSize) or 12, 11, 12)
            else
                object.TextSize = math.clamp(tonumber(object.TextSize) or 12, 11, 12)
            end
        end)
        return
    end

    local name = string.lower(tostring(object.Name or ""))
    local isTitle = name == "title" or name == "titlelabel"
        or name == "label" or name == "textlabel"
        or name:find("controltitle", 1, true) ~= nil
        or name:find("featuretitle", 1, true) ~= nil
    if not isTitle then return end

    pcall(function()
        object.TextWrapped = false
        object.TextScaled = false
        object.TextXAlignment = Enum.TextXAlignment.Left
        object.TextSize = math.clamp(tonumber(object.TextSize) or 12, 11, 13)
        object.TextTruncate = Enum.TextTruncate.AtEnd
    end)
end

function MAWWW_StyleFeatureTexts(root)
    if not root then return end
    for _, object in ipairs(root:GetDescendants()) do
        MAWWW_StyleFeatureText(object)
    end
end

function MAWWW_CompactFeatureElement(raw, targetHeight)
    if not raw then return end
    local frame = raw.Frame
    if not frame or not frame:IsA("GuiObject") then return end

    local controlKind = tostring(raw.Type or "")
    local minHeight = tonumber(targetHeight) or 0
    if controlKind == "Slider" then
        minHeight = math.max(minHeight, 52)
    elseif controlKind == "Dropdown" then
        minHeight = math.max(minHeight, 50)
    elseif controlKind == "Input" then
        minHeight = math.max(minHeight, 48)
    end
    targetHeight = minHeight > 0 and minHeight or targetHeight

    -- Mark only the actual control title, not every TextLabel in the UI. This
    -- permits wrapping for long labels while keeping switch/value widgets intact.
    pcall(function()
        local titleLabel = nil
        if controlKind == "Toggle" and raw.TextLabel and raw.TextLabel:IsA("TextLabel") then
            titleLabel = raw.TextLabel
        else
            titleLabel = frame:FindFirstChildWhichIsA("TextLabel", false)
        end
        if titleLabel then
            titleLabel:SetAttribute("MAWWWControlTextKind", controlKind)
            titleLabel.TextWrapped = true
            titleLabel.TextScaled = false
            titleLabel.TextTruncate = Enum.TextTruncate.None
            titleLabel.TextXAlignment = Enum.TextXAlignment.Left
            titleLabel.TextSize = 12
            if controlKind == "Slider" or controlKind == "Dropdown" or controlKind == "Input" then
                titleLabel.Size = UDim2.new(titleLabel.Size.X.Scale, titleLabel.Size.X.Offset, 0, 24)
            elseif controlKind == "Toggle" then
                titleLabel.Size = UDim2.new(1, -40, 1, 0)
            end
        end
    end)

    pcall(function()
        frame.AutomaticSize = Enum.AutomaticSize.None
        -- Preserve intentionally transparent wrapper frames; only keep native
        -- painted rows opaque so the old wallpaper cannot bleed through them.
        local transparency = tonumber(frame.BackgroundTransparency)
        if transparency and transparency < 1 then
            frame.BackgroundTransparency = math.min(transparency, 0.12)
        end
        frame.ClipsDescendants = false
    end)

    MAWWW_StyleFeatureTexts(frame)
    -- Fluent can create title/description labels after returning the control.
    -- Style those late children too, but never interfere with input events.
    frame.DescendantAdded:Connect(function(object)
        if object:IsA("TextLabel") then
            task.defer(function()
                if object.Parent then MAWWW_StyleFeatureText(object) end
            end)
        end
    end)

    local function refreshCompact()
        if not frame.Parent then return end
        MAWWW_StyleFeatureTexts(frame)
        local height = tonumber(targetHeight)
        if height and height > 0 then
            pcall(function()
                frame.AutomaticSize = Enum.AutomaticSize.None
                local current = frame.Size
                if current.Y.Scale ~= 0 or current.Y.Offset ~= height then
                    frame.Size = UDim2.new(current.X.Scale, current.X.Offset, 0, height)
                end
            end)
        end
    end

    frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(refreshCompact)
    task.defer(refreshCompact)
end

-- Slider rows reserve extra height for readable wrapped titles in two-column sections.
-- The value rail remains anchored to the bottom of the row.
function MAWWW_CompactSliderElement(raw)
    pcall(MAWWW_CompactFeatureElement, raw, 52)
    if not raw then return end
    local frame = raw.Frame
    if not frame or not frame:IsA("GuiObject") then return end

    local sizeConstraint
    for _, child in ipairs(frame:GetChildren()) do
        if child:IsA("Frame") then
            local constraint = child:FindFirstChildOfClass("UISizeConstraint")
            if constraint then
                sizeConstraint = constraint
                break
            end
        end
    end

    local function refreshLayout()
        if not frame.Parent then return end
        local width = tonumber(frame.AbsoluteSize.X) or 0
        if width <= 0 then return end
        local railWidth = math.clamp(width * 0.42, 78, 132)
        if sizeConstraint then
            sizeConstraint.MaxSize = Vector2.new(railWidth, math.huge)
        end
        MAWWW_StyleFeatureTexts(frame)
        if frame.Size.Y.Scale ~= 0 or frame.Size.Y.Offset ~= 52 then
            frame.Size = UDim2.new(frame.Size.X.Scale, frame.Size.X.Offset, 0, 52)
        end
    end

    frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(refreshLayout)
    task.defer(refreshLayout)
end

