MAWWW_CleanSectionTitle = function(value)
    local title = tostring(value or "Section")
    title = title:gsub("^%s+", ""):gsub("%s+$", ""):gsub("%s+", " ")
    return MAWWW_SECTION_TITLE_MAP[title] or title
end

function MAWWW_CleanFeatureDisplayTitle(value, kind)
    local title = tostring(value or "")
    title = title:gsub("^%s+", ""):gsub("%s+$", ""):gsub("%s+", " ")
    local mapped = MAWWW_FEATURE_TITLE_MAP[title]
    if mapped then
        if kind == "label" and mapped.label then return mapped.label end
        if kind == "control" and mapped.control then return mapped.control end
    end
    if kind == "label" and MAWWW_LABEL_TITLE_MAP[title] then
        return MAWWW_LABEL_TITLE_MAP[title]
    end
    if kind == "control" and MAWWW_CONTROL_TITLE_MAP[title] then
        return MAWWW_CONTROL_TITLE_MAP[title]
    end
    title = title:gsub("TOF", "ToF")
    title = title:gsub("Twist of Fate", "ToF")
    title = title:gsub("Skillcheck", "Skill Check")
    title = title:gsub("skillcheck", "Skill Check")
    title = title:gsub("Killer: ", "Killer · ")
    if title == "Target Mode" then return "Target Role" end
    if title == "Silent Aim Key" or title == "Toggle Key" then return "Aim Toggle Key" end
    return title
end

function MAWWW_NormalizeTitleKey(value)
    return tostring(value or ""):lower():gsub("[^%w]", "")
end

-- Compatibility proxy matching the source registration API exactly.
function MakeLogicTab(group)
    local proxy = {}

    function proxy:Toggle(config)
        config = config or {}
        local id = tostring(config.Flag or config.Name or ("MawwwToggle_" .. tostring(os.clock())))
        local initial = config.Value
        if initial == nil then initial = config.Default end

        local ok, raw = pcall(function()
            return group:AddToggle(id, {
                Title = MAWWW_CleanFeatureDisplayTitle(config.Title or "Toggle", "control"),
                Description = "",
                Default = initial == true,
                Callback = config.Callback,
                Icon = config.Icon,
            })
        end)
        if not ok then
            warn("[Mawww Hub] Obsidian Toggle failed:", config.Title, raw)
            return nil
        end
        pcall(MAWWW_CompactFeatureElement, raw, 38)
        return MAWWW_WrapElement(raw)
    end

    function proxy:Slider(config)
        config = config or {}
        local id = tostring(config.Flag or config.Name or ("MawwwSlider_" .. tostring(os.clock())))
        local initial = config.Default
        if initial == nil then initial = config.Value end
        local min = tonumber(config.Min) or 0
        local max = tonumber(config.Max) or 100
        local rounding = config.Rounding
        if rounding == nil then rounding = formatRounding(config.Step) end

        local ok, raw = pcall(function()
            return group:AddSlider(id, {
                Title = MAWWW_CleanFeatureDisplayTitle(config.Title or "Slider", "control"),
                Description = "",
                Default = tonumber(initial) or min,
                Min = min,
                Max = max,
                Rounding = tonumber(rounding) or 0,
                Callback = config.Callback,
            })
        end)
        if not ok then
            warn("[Mawww Hub] Obsidian Slider failed:", config.Title, raw)
            return nil
        end
        pcall(MAWWW_CompactSliderElement, raw)
        return MAWWW_WrapElement(raw)
    end

    function proxy:Dropdown(config)
        config = config or {}
        local id = tostring(config.Flag or config.Name or ("MawwwDropdown_" .. tostring(os.clock())))
        local initial = config.Value
        if initial == nil then initial = config.Default end
        local values = config.Values or {}
        if config.Multi == true then
            initial = MAWWW_NormalizeMultiDefault(initial)
        end

        local ok, raw = pcall(function()
            return group:AddDropdown(id, {
                Title = MAWWW_CleanFeatureDisplayTitle(config.Title or "Dropdown", "control"),
                Description = "",
                Values = values,
                Default = initial,
                Multi = config.Multi == true,
                Animated = config.Animated == true,
                -- Keep Fluent's native close/dismiss behavior by default.
                -- Popups can opt into outside-window mode explicitly when required.
                DropdownOutsideWindow = config.DropdownOutsideWindow == true,
                DropdownBackgroundTransparency = config.DropdownBackgroundTransparency,
                DropdownBackgroundImage = config.DropdownBackgroundImage or config.DropdownBackgroundImages,
                Callback = config.Callback,
            })
        end)
        if not ok then
            warn("[Mawww Hub] Obsidian Dropdown failed:", config.Title, raw)
            return nil
        end
        pcall(MAWWW_CompactFeatureElement, raw, 40)
        return MAWWW_WrapElement(raw)
    end

    function proxy:Button(config)
        config = config or {}
        local ok, raw = pcall(function()
            return group:AddButton({
                Title = MAWWW_CleanFeatureDisplayTitle(config.Title or "Button", "control"),
                Description = "",
                Callback = config.Callback,
                Icon = config.Icon,
            })
        end)
        if not ok then
            warn("[Mawww Hub] Obsidian Button failed:", config.Title, raw)
            return nil
        end
        pcall(MAWWW_CompactFeatureElement, raw, 36)
        return MAWWW_WrapElement(raw)
    end

    function proxy:Input(config)
        config = config or {}
        local id = tostring(config.Flag or config.Name or ("MawwwInput_" .. tostring(os.clock())))
        local initial = config.Value
        if initial == nil then initial = config.Default end

        local ok, raw = pcall(function()
            return group:AddInput(id, {
                Title = MAWWW_CleanFeatureDisplayTitle(config.Title or "Input", "control"),
                Description = "",
                Placeholder = tostring(config.Placeholder or ""),
                Default = tostring(initial or ""),
                Callback = config.Callback,
            })
        end)
        if not ok then
            warn("[Mawww Hub] Obsidian Input failed:", config.Title, raw)
            return nil
        end
        pcall(MAWWW_CompactFeatureElement, raw, 40)
        return MAWWW_WrapElement(raw)
    end

    function proxy:Divider()
        return pcall(function() group:AddDivider() end)
    end

    function proxy:Label(text)
        local displayText = MAWWW_CleanFeatureDisplayTitle(text or "", "label")
        local sectionTitle = group and group._mawwwTitle
        if sectionTitle then
            local normalizedLabel = MAWWW_NormalizeTitleKey(displayText)
            local normalizedSection = MAWWW_NormalizeTitleKey(
                MAWWW_CleanFeatureDisplayTitle(sectionTitle, "label")
            )
            if normalizedLabel ~= "" and normalizedLabel == normalizedSection then
                return nil
            end
        end
        local ok, raw = pcall(function()
            return group:AddParagraph({
                Content = tostring(displayText or ""),
            })
        end)
        if not ok then
            warn("[Mawww Hub] Obsidian Label failed:", raw)
            return nil
        end
        return MAWWW_WrapElement(raw)
    end

    function proxy:Keybind(config)
        config = config or {}
        local id = tostring(config.Flag or config.Name or ("MawwwKeybind_" .. tostring(os.clock())))
        local default = config.Default
        if default == nil then default = config.Value end
        if typeof(default) == "EnumItem" then
            default = default.Name
        end

        local ok, raw = pcall(function()
            return group:AddKeybind(id, {
                Title = MAWWW_CleanFeatureDisplayTitle(config.Title or "Keybind", "control"),
                Description = "",
                Default = tostring(default or "RightAlt"),
                Mode = tostring(config.Mode or "Toggle"),
                Callback = config.Callback,
            })
        end)
        if not ok then
            warn("[Mawww Hub] Obsidian Keybind failed:", config.Title, raw)
            return nil
        end
        pcall(MAWWW_CompactFeatureElement, raw, 38)
        return MAWWW_WrapElement(raw)
    end

    function proxy:Colorpicker(config)
        config = config or {}
        local id = tostring(config.Flag or config.Name or ("MawwwColor_" .. tostring(os.clock())))
        local default = config.Default or config.Value or Color3.fromRGB(255, 255, 255)

        local ok, raw = pcall(function()
            return group:AddColorpicker(id, {
                Title = MAWWW_CleanFeatureDisplayTitle(config.Title or "Color", "control"),
                Description = "",
                Default = default,
                Transparency = tonumber(config.Transparency) or 0,
                Gradient = config.Gradient == true,
                Callback = config.Callback,
            })
        end)
        if not ok then
            warn("[Mawww Hub] Obsidian Colorpicker failed:", config.Title, raw)
            return nil
        end
        pcall(MAWWW_CompactFeatureElement, raw, 38)
        return MAWWW_WrapElement(raw)
    end

    return proxy
end

-- Home tab: mount a real ImageLabel next to the rendered Welcome cards so the
-- photo remains visible across different versions of the UI library.
HomeTab = VDUI:AddTab("Home", "house", true)
do
    local home = HomeTab:AddGroupbox("left", "Welcome")
    if home then
        -- Create the native cards first. Their actual rendered instances provide
        -- a reliable parent for the image, even when the UI library's section
        -- object does not expose Container/Holder consistently.
        local welcomeParagraph = home:AddParagraph({
            Title = "Mawww Hub",
            Content = "Welcome to Mawww Hub. Choose a category from the sidebar to open its features.",
        })
        local mobileTipParagraph = home:AddParagraph({
            Title = "Mobile tip",
            Content = "Use the window controls to hide or restore the hub. Scroll inside each tab to reach more options.",
        })

        local function mawwwGetParagraphGui(paragraph)
            if type(paragraph) ~= "table" then return nil end
            local direct = {}
            local function addCandidate(candidate)
                if candidate ~= nil then table.insert(direct, candidate) end
            end
            addCandidate(paragraph.Frame)
            addCandidate(paragraph.Holder)
            addCandidate(paragraph.Label)
            addCandidate(paragraph.TextLabel)
            local raw = paragraph.Raw
            if type(raw) == "table" then
                addCandidate(raw.Frame)
                addCandidate(raw.Holder)
                addCandidate(raw.Label)
                addCandidate(raw.TextLabel)
            end
            for _, candidate in ipairs(direct) do
                if typeof(candidate) == "Instance" and candidate:IsA("GuiObject") then
                    return candidate
                end
            end
            return nil
        end

        local welcomeGui = mawwwGetParagraphGui(welcomeParagraph)
        local tipGui = mawwwGetParagraphGui(mobileTipParagraph)
        local heroParent = nil

        -- Prefer the lowest common GuiObject ancestor of the two actual cards.
        -- It is the content holder that owns their layout in the live UI.
        if welcomeGui and tipGui then
            local ancestor = welcomeGui.Parent
            while ancestor and ancestor ~= game do
                if ancestor:IsA("GuiObject") and tipGui:IsDescendantOf(ancestor) then
                    heroParent = ancestor
                    break
                end
                ancestor = ancestor.Parent
            end
        end

        -- Library-version fallbacks, after the rendered-card lookup.
        local parentCandidates = {}
        local function addParentCandidate(candidate)
            if candidate ~= nil then table.insert(parentCandidates, candidate) end
        end
        addParentCandidate(home.Container)
        addParentCandidate(home.Card)
        addParentCandidate(home._obsidianBox and home._obsidianBox.Container)
        addParentCandidate(home._obsidianBox and home._obsidianBox.Content)
        addParentCandidate(home._obsidianBox and home._obsidianBox.ContentFrame)
        addParentCandidate(home._obsidianBox and home._obsidianBox.Holder)
        addParentCandidate(home._obsidianBox and home._obsidianBox.Frame)
        addParentCandidate(home._obsidianBox and home._obsidianBox.SectionFrame)
        addParentCandidate(HomeTab.Page)
        addParentCandidate(HomeTab.Container)
        if not heroParent then
            for _, candidate in ipairs(parentCandidates) do
                if typeof(candidate) == "Instance" and candidate:IsA("GuiObject") then
                    heroParent = candidate
                    break
                end
            end
        end

        if heroParent then
            pcall(function()
                local oldHero = heroParent:FindFirstChild("MawwwHomeHeroFrame")
                if oldHero then oldHero:Destroy() end
            end)

            local frame = Instance.new("Frame")
            frame.Name = "MawwwHomeHeroFrame"
            frame.BackgroundColor3 = Color3.fromRGB(28, 27, 33)
            frame.BackgroundTransparency = 0
            frame.BorderSizePixel = 0
            frame.Size = UDim2.new(1, 0, 0, 176)
            frame.LayoutOrder = -10000
            frame.ClipsDescendants = true
            frame.Visible = true
            frame.ZIndex = 48
            frame.Parent = heroParent

            local image = Instance.new("ImageLabel")
            image.Name = "MawwwHomeHeroImage"
            image.BackgroundTransparency = 1
            image.BorderSizePixel = 0
            image.Position = UDim2.fromScale(0, 0)
            image.Size = UDim2.fromScale(1, 1)
            image.ScaleType = Enum.ScaleType.Crop
            image.ImageTransparency = 0
            image.Visible = true
            image.ZIndex = 49
            -- Start with the known Mawww logo so Home never begins with an empty tile.
            -- The requested photo replaces it as soon as Roblox confirms it loaded.
            image.Image = MAWWW_FLOATING_LOGO_ID
            image.Parent = frame

            pcall(function()
                local corner = Instance.new("UICorner")
                corner.CornerRadius = UDim.new(0, 10)
                corner.Parent = frame
                local stroke = Instance.new("UIStroke")
                stroke.Color = Color3.fromRGB(120, 83, 190)
                stroke.Transparency = 0.16
                stroke.Thickness = 1
                stroke.Parent = frame
            end)

            local listLayout = heroParent:FindFirstChildOfClass("UIListLayout")
            if listLayout then
                local anchorOrder = 0
                if welcomeGui then pcall(function() anchorOrder = welcomeGui.LayoutOrder end) end
                frame.LayoutOrder = math.min(-10000, (tonumber(anchorOrder) or 0) - 1)
            else
                -- For manual-position layouts, insert before the first card and move
                -- existing content down instead of covering it with the photo.
                local top = math.huge
                for _, child in ipairs(heroParent:GetChildren()) do
                    if child:IsA("GuiObject") and child ~= frame then
                        local y = child.Position.Y.Offset + child.Position.Y.Scale * heroParent.AbsoluteSize.Y
                        top = math.min(top, y)
                    end
                end
                if top == math.huge then top = 0 end
                frame.Position = UDim2.new(0, 0, 0, top)
                for _, child in ipairs(heroParent:GetChildren()) do
                    if child:IsA("GuiObject") and child ~= frame then
                        local y = child.Position.Y.Offset + child.Position.Y.Scale * heroParent.AbsoluteSize.Y
                        if y >= top - 2 then
                            local pos = child.Position
                            child.Position = UDim2.new(pos.X.Scale, pos.X.Offset, pos.Y.Scale, pos.Y.Offset + 184)
                        end
                    end
                end
                if heroParent:IsA("ScrollingFrame") then
                    pcall(function()
                        local current = heroParent.CanvasSize
                        heroParent.CanvasSize = UDim2.new(current.X.Scale, current.X.Offset, current.Y.Scale, math.max(current.Y.Offset, top + 184))
                    end)
                end
            end

            -- Load the requested asset through Roblox's thumbnail endpoint first,
            -- then the direct content URI. Keep the working logo if the photo is
            -- private, moderated, not an image/decal, or otherwise unavailable.
            task.spawn(function()
                local contentProvider = game:GetService("ContentProvider")
                local photoUris = {
                    HOME_PHOTO_THUMB_ID,
                    "https://www.roblox.com/asset-thumbnail/image?assetId=97815205163579&width=420&height=420&format=png",
                    HOME_PHOTO_ID,
                }
                for _, imageUri in ipairs(photoUris) do
                    if not image.Parent or not frame.Parent then return end
                    local failed = false
                    pcall(function()
                        image.Image = imageUri
                        image.Visible = true
                        contentProvider:PreloadAsync({image}, function(_, status)
                            if status == Enum.AssetFetchStatus.Failure then failed = true end
                        end)
                    end)
                    task.wait(0.25)
                    local loaded = false
                    pcall(function() loaded = image.IsLoaded end)
                    if loaded and not failed then
                        return
                    end
                end

                if image.Parent and frame.Parent then
                    pcall(function()
                        image.Image = MAWWW_FLOATING_LOGO_THUMB_ID
                        image.Visible = true
                        contentProvider:PreloadAsync({image})
                    end)
                    task.wait(0.2)
                    local logoLoaded = false
                    pcall(function() logoLoaded = image.IsLoaded end)
                    if not logoLoaded then
                        pcall(function() image.Image = MAWWW_FLOATING_LOGO_ID end)
                    end
                    warn("[Mawww Hub] Could not load Home photo asset 97815205163579; showing the available Mawww Hub logo instead.")
                end
            end)
        else
            -- Last-resort path: explicitly insert the image into the active Home page.
            -- This is intentionally visible even when the section internals change.
            local page = HomeTab.Page or HomeTab.Container
            if typeof(page) == "Instance" and page:IsA("GuiObject") then
                local frame = Instance.new("Frame")
                frame.Name = "MawwwHomeHeroFrame"
                frame.BackgroundColor3 = Color3.fromRGB(28, 27, 33)
                frame.BorderSizePixel = 0
                frame.Size = UDim2.new(1, -12, 0, 176)
                frame.Position = UDim2.fromOffset(6, 6)
                frame.LayoutOrder = -10000
                frame.ZIndex = 48
                frame.Parent = page
                local image = Instance.new("ImageLabel")
                image.Name = "MawwwHomeHeroImage"
                image.BackgroundTransparency = 1
                image.Size = UDim2.fromScale(1, 1)
                image.ScaleType = Enum.ScaleType.Crop
                image.Image = MAWWW_FLOATING_LOGO_ID
                image.ZIndex = 49
                image.Parent = frame
                task.spawn(function()
                    local contentProvider = game:GetService("ContentProvider")
                    for _, imageUri in ipairs({HOME_PHOTO_THUMB_ID, HOME_PHOTO_ID}) do
                        pcall(function() image.Image = imageUri; contentProvider:PreloadAsync({image}) end)
                        task.wait(0.25)
                        if image.IsLoaded then return end
                    end
                    pcall(function() image.Image = MAWWW_FLOATING_LOGO_ID end)
                end)
            else
                warn("[Mawww Hub] Home photo fallback could not find a GUI parent.")
            end
        end
    end
end

