--========================================================--
-- MAWWW HUB FREE: premium-only features remain locked even when an old
-- saved config or a keyboard shortcut tries to enable them.
--========================================================--
local MAWWW_PREMIUM_FEATURES_LOCKED = true
local MAWWW_PremiumLockRuntimeReady = false
local function MAWWW_EnforceFreePremiumLocks()
    for _, key in ipairs({
        "VeilEnabled", "VeilV2Enabled", "VeilV3Enabled",
        "TOF_SilentAim", "TOF2_Enabled", "TOF2_SourceEnabled", "TOF3_SilentAim",
        "PistolEnabled", "PistolV4FlashSilentAim", "PistolV5Enabled",
        "GenBoost", "Invisible",
    }) do
        VD[key] = false
    end
    -- Disable built-in key toggles as a second layer behind the locked UI.
    VD.TOF_Key = "None"
    VD.TOF2_Key = "None"
    VD.TOF3_Key = "None"
    VD.GenBoost = false
    VD.HideGenBypass = true
    VD.Invisible = false
    VD.InvisibleHideIcon = true

    -- At startup the engines may not have been initialized yet. Once runtime
    -- setup is complete, actively stop any engine touched by a config load.
    if MAWWW_PremiumLockRuntimeReady then
        pcall(function() if type(MAWWW_SetToFSilentAim) == "function" then MAWWW_SetToFSilentAim(false) end end)
        pcall(function() if type(MAWWW_SetToFV3SilentAim) == "function" then MAWWW_SetToFV3SilentAim(false) end end)
        pcall(function() if ToFV2 and type(ToFV2.Stop) == "function" then ToFV2.Stop() end end)
        pcall(function() if ToFV3Module and type(ToFV3Module.Stop) == "function" then ToFV3Module.Stop() end end)
        pcall(function() if type(getgenv().MAWWW_SetSilentPistolV5) == "function" then getgenv().MAWWW_SetSilentPistolV5(false) end end)
        pcall(function() if type(MAWWW_DisableInvisibleRuntime) == "function" then MAWWW_DisableInvisibleRuntime(false) end end)
        pcall(function()
            if type(W) == "table" and type(W.setGenBypass) == "function" then W.setGenBypass(false) end
            if type(GenBypass) == "table" then
                GenBypass.Enabled = false
                GenBypass.Hidden = true
            end
            if type(W) == "table" and type(W.GB_UpdateButton) == "function" then W.GB_UpdateButton() end
        end)
        pcall(function()
            if type(AimConfig) == "table" then
                AimConfig.Aim_Silent = false
                AimConfig.Flash_Silent = false
            end
        end)
    end
end
MAWWW_EnforceFreePremiumLocks()

-- Preserve the selected Parry V2-V5 ranges independently from UI visibility/state.
