local MAWWW_ParryPanelStableRanges = getgenv().MAWWW_ParryPanelStableRanges
if type(MAWWW_ParryPanelStableRanges) ~= "table" then
    MAWWW_ParryPanelStableRanges = {}
    getgenv().MAWWW_ParryPanelStableRanges = MAWWW_ParryPanelStableRanges
end
local function MAWWW_SeedParryRange(index, vdKey, defaultValue, minValue, maxValue)
    local cached = tonumber(MAWWW_ParryPanelStableRanges[index])
    local configured = tonumber(VD[vdKey])
    local value = cached or configured or defaultValue
    value = math.clamp(value, minValue, maxValue)
    MAWWW_ParryPanelStableRanges[index] = value
    VD[vdKey] = value
end
