local MAWWW_PremiumLockNoticeShown = {}
local function MAWWW_ShowPremiumLockForTab(tab)
    local feature = MAWWW_PremiumLockedTabs[tab]
    if not feature then return false end
    if not MAWWW_PremiumLockNoticeShown[tab] then
        MAWWW_PremiumLockNoticeShown[tab] = true
        pcall(function()
            tab:Label("🔒 KHUSUS PREMIUM\n" .. feature .. " hanya tersedia di Mawww Hub Premium.\nFitur dikunci pada versi Free.")
        end)
    end
    return true
end

function RegToggle(tab, text, desc, default, vdKey, extraCallback)
    if not tab then return nil end
    if MAWWW_ShowPremiumLockForTab(tab) then return nil end
    if vdKey and VD_Elements[vdKey] then return VD_Elements[vdKey] end

    local ok, obj = pcall(function()
        local initial = MAWWW_GetVDOrDefault(vdKey, default)
        return tab:Toggle({
            Title = MAWWW_CleanFeatureDisplayTitle(text, "control"),
            Desc = desc or "",
            Flag = vdKey,
            Value = initial,
            Callback = function(v)
                if vdKey then VD[vdKey] = v end
                if extraCallback then pcall(extraCallback, v) end
            end,
        })
    end)

    if not ok then
        warn("[Purple X Hub] Toggle failed:", text, obj)
        return nil
    end

    if obj and vdKey then
        VD_Elements[vdKey] = obj
    end

    return obj
end

local MAWWW_ParryRangeSliderKeys = {
    Wisnu_ParryDistance = true,
    SURV_ParryDistanceV3 = true,
    PARRY_V4_Distance = true,
    SURV_ParryRadiusV5 = true,
}

function RegSlider(tab, text, desc, default, min, max, step, vdKey, extraCallback)
    if not tab then return nil end
    if MAWWW_ShowPremiumLockForTab(tab) then return nil end
    if vdKey and VD_Elements[vdKey] then return VD_Elements[vdKey] end

    local isParryRangeSlider = vdKey ~= nil and MAWWW_ParryRangeSliderKeys[vdKey] == true
    local sliderReady = false
    local sliderCreateStartedAt = os.clock()
    local authoritativeInitialValue = vdKey and tonumber(MAWWW_GetVDOrDefault(vdKey, default)) or nil

    local ok, obj = pcall(function()
        return tab:Slider({
            Title = MAWWW_CleanFeatureDisplayTitle(text, "control"),
            Desc = desc or "",
            Flag = vdKey,
            Default = MAWWW_GetVDOrDefault(vdKey, default),
            Min = min,
            Max = max,
            Step = step,
            Rounding = formatRounding(step),
            Callback = function(v)
                -- Some UI builds emit a callback with their fallback slider value while
                -- creating/rebuilding the control. Do not let that overwrite a saved
                -- Parry V2-V5 range unless the user actually changes it after creation.
                if isParryRangeSlider then
                    local incoming = tonumber(v)
                    local current = tonumber(VD[vdKey]) or authoritativeInitialValue
                    local isEarlyCreateCallback = (not sliderReady) or (os.clock() - sliderCreateStartedAt < 0.25)
                    if isEarlyCreateCallback and current and incoming and math.abs(incoming - current) > 0.0001 then
                        if extraCallback then pcall(extraCallback, current) end
                        return
                    end
                end
                if vdKey then VD[vdKey] = v end
                if extraCallback then pcall(extraCallback, v) end
            end,
        })
    end)

    if ok then sliderReady = true end
    if not ok then
        warn("[Purple X Hub] Slider failed:", text, obj)
        return nil
    end

    if obj and vdKey then
        VD_Elements[vdKey] = obj
    end

    return obj
end

function RegDropdown(tab, text, desc, values, default, multi, vdKey, extraCallback)
    if not tab then return nil end
    if MAWWW_ShowPremiumLockForTab(tab) then return nil end
    if vdKey and VD_Elements[vdKey] then return VD_Elements[vdKey] end

    local ok, obj = pcall(function()
        local isToFTargetMode = vdKey ~= nil and MAWWW_TOF_TARGET_MODE_DROPDOWN_KEYS[vdKey] == true
        return tab:Dropdown({
            Title = MAWWW_CleanFeatureDisplayTitle(text, "control"),
            Desc = desc or "",
            Flag = vdKey,
            Values = values or {},
            Value = MAWWW_GetVDOrDefault(vdKey, default),
            Default = MAWWW_GetVDOrDefault(vdKey, default),
            Multi = multi == true,
            DropdownBackgroundImage = isToFTargetMode and MAWWW_TOF_TARGET_MODE_IMAGE_ID or nil,
            DropdownBackgroundTransparency = isToFTargetMode and 0.62 or nil,
            Callback = function(v)
                if vdKey then VD[vdKey] = v end
                if extraCallback then pcall(extraCallback, v) end
            end,
        })
    end)

    if not ok then
        warn("[Purple X Hub] Dropdown failed:", text, obj)
        return nil
    end

    if obj and vdKey then
        -- Mawww source uses :Refresh() on some dropdowns; Obsidian uses :SetValues().
        pcall(function()
            if type(obj.Refresh) ~= "function" and type(obj.SetValues) == "function" then
                obj.Refresh = function(self, values)
                    return self:SetValues(values)
                end
            end
        end)
        VD_Elements[vdKey] = obj
    end

    return obj
end

function RegButton(tab, text, desc, callback)
    if not tab then return nil end
    if MAWWW_ShowPremiumLockForTab(tab) then return nil end
    local ok, obj = pcall(function()
        return tab:Button({
            Title = MAWWW_CleanFeatureDisplayTitle(text, "control"),
            Desc = desc or "",
            Callback = callback,
        })
    end)
    if not ok then
        warn("[Purple X Hub] Button failed:", text, obj)
        return nil
    end
    return obj
end

function RegInput(tab, text, desc, default, vdKey, extraCallback)
