RegButton(Tabs.Status, "Refresh Status Snapshot", "Show role, player count, ping, and estimated FPS.", function()
    local playerCount = #MawwwGetPlayers()
    local role = "Unknown"
    pcall(function() role = tostring(GetRole()) end)
    local pingText = "Unavailable"
    pcall(function()
        local statsService = game:GetService("Stats")
        local item = statsService.Network.ServerStatsItem:FindFirstChild("Data Ping")
        if item then
            local value = tonumber(item:GetValue())
            if value then pingText = tostring(math.floor(value + 0.5)) .. " ms" end
        end
    end)
    local fpsText = "Unavailable"
    pcall(function()
        local dt = RunService.RenderStepped:Wait()
        if dt and dt > 0 then fpsText = tostring(math.floor(1 / dt + 0.5)) .. " FPS" end
    end)
    notify("Status", string.format("Role: %s\nPlayers: %d\nPing: %s\nFPS: %s", role, playerCount, pingText, fpsText), 5)
end)

