    UnlimitedZoom = VD.UnlimitedZoom == true,
    FixedFOV = VD.FOVEnabled == true,
}

-- Restore and disconnect a previous execution before creating new connections.
pcall(function()
    local previousRestore = DBD_GlobalEnv.MAWWW_DBDCameraRestore
    if type(previousRestore) == "function" then
        previousRestore()
    end
end)
pcall(function()
    local previousConnection = DBD_GlobalEnv.MAWWW_DBDCameraConn
    if previousConnection then previousConnection:Disconnect() end
    DBD_GlobalEnv.MAWWW_DBDCameraConn = nil
    local previousCharacterConnection = DBD_GlobalEnv.MAWWW_DBDCameraCharacterConnection
    if previousCharacterConnection then previousCharacterConnection:Disconnect() end
    DBD_GlobalEnv.MAWWW_DBDCameraCharacterConnection = nil
end)

-- Clean up camera properties left behind by an older build before the UI opens.
-- Only normalize them if an old camera toggle was actually active.
if DBD_PreviousCameraFlags.DBD
    or DBD_PreviousCameraFlags.FirstPerson
    or DBD_PreviousCameraFlags.ThirdPerson
    or DBD_PreviousCameraFlags.ShiftLock
    or DBD_PreviousCameraFlags.UnlimitedZoom
    or DBD_PreviousCameraFlags.FixedFOV then
    pcall(function()
        local camera = workspace.CurrentCamera
        if camera and (DBD_PreviousCameraFlags.DBD or DBD_PreviousCameraFlags.FixedFOV) then
            camera.FieldOfView = 70
        end
        if DBD_PreviousCameraFlags.DBD or DBD_PreviousCameraFlags.FirstPerson or DBD_PreviousCameraFlags.UnlimitedZoom then
            LocalPlayer.CameraMode = Enum.CameraMode.Classic
            LocalPlayer.CameraMinZoomDistance = 0.5
            LocalPlayer.CameraMaxZoomDistance = 128
        end
        local character = LocalPlayer.Character
        if character then
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            if humanoid then
                if DBD_PreviousCameraFlags.DBD or DBD_PreviousCameraFlags.ThirdPerson then
                    humanoid.CameraOffset = Vector3.zero
                end
                if DBD_PreviousCameraFlags.ShiftLock then
                    humanoid.AutoRotate = true
                end
            end
            if DBD_PreviousCameraFlags.FirstPerson then
                local head = character:FindFirstChild("Head")
                if head then head.LocalTransparencyModifier = 0 end
                for _, object in ipairs(character:GetChildren()) do
                    if object:IsA("Accessory") then
                        local handle = object:FindFirstChild("Handle")
                        if handle then handle.LocalTransparencyModifier = 0 end
                    end
                end
            end
        end
    end)
end

-- Startup safety: camera features are opt-in on every execution. Keep the rest
-- of the hub state untouched, but never inherit camera overrides from an old run.
VD.DBDCamera = false
VD.DBDCameraUseCharScale = false
VD.DBDCameraCharScale = 1
VD.DBDCameraFOV = 70
VD.FirstPersonCamera = false
VD.ThirdPerson = false
VD.ShiftLock = false
VD.UnlimitedZoom = false
VD.FOVEnabled = false
VD.CAM_FOVEnabled = false

local DBD_Config = {
    Enabled = false,
    Distance = math.clamp(tonumber(VD.DBDCameraDistance) or 25, 1, 60),
    FOV = 70,
    Height = tonumber(VD.DBDCameraHeight) or 0,
    CharScale = 1,
    UseCharScale = false,
}

local DBD_OriginalCameraState = nil
local DBD_CharacterSnapshot = nil
local DBD_Conn = nil
local DBD_CharacterConnection = nil
local DBD_ScaleNames = {"BodyHeightScale", "BodyWidthScale", "BodyDepthScale", "HeadScale"}

local function DBD_CaptureCharacterState(char)
    char = char or LocalPlayer.Character
    if not char then
        DBD_CharacterSnapshot = nil
        return
    end

    local snapshot = {
        Character = char,
        Humanoid = nil,
        CameraOffset = Vector3.zero,
        Scales = {},
    }
    local hum = char:FindFirstChildOfClass("Humanoid")
    snapshot.Humanoid = hum
    if hum then
        pcall(function() snapshot.CameraOffset = hum.CameraOffset end)
        for _, scaleName in ipairs(DBD_ScaleNames) do
            local scaleObject = hum:FindFirstChild(scaleName, true)
            if scaleObject and scaleObject:IsA("NumberValue") then
                snapshot.Scales[scaleName] = {
                    Object = scaleObject,
                    Value = scaleObject.Value,
                }
            end
        end
    end
    DBD_CharacterSnapshot = snapshot
end

local function DBD_RestoreCharacterState()
    local snapshot = DBD_CharacterSnapshot
    if not snapshot then return end

    pcall(function()
        local hum = snapshot.Humanoid
        if hum and hum.Parent then
            hum.CameraOffset = snapshot.CameraOffset or Vector3.zero
        end
    end)
    for _, saved in pairs(snapshot.Scales or {}) do
        pcall(function()
            if saved.Object and saved.Object.Parent then
                saved.Object.Value = saved.Value
            end
        end)
    end
end

local function DBD_ApplyCharScale()
    if not DBD_Config.UseCharScale then return end
    local char = LocalPlayer.Character
    if not char then return end
    if not DBD_CharacterSnapshot or DBD_CharacterSnapshot.Character ~= char then
        DBD_CaptureCharacterState(char)
    end

    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local scale = math.clamp(tonumber(DBD_Config.CharScale) or 1, 0.01, 1)
    for _, scaleName in ipairs(DBD_ScaleNames) do
        local scaleObject = hum:FindFirstChild(scaleName, true)
        if scaleObject and scaleObject:IsA("NumberValue") then
            pcall(function() scaleObject.Value = scale end)
        end
    end
end

local function DBD_CaptureCameraState()
    if DBD_OriginalCameraState then return end
    local camera = workspace.CurrentCamera
    DBD_OriginalCameraState = {
        FieldOfView = camera and camera.FieldOfView or 70,
        MinZoom = LocalPlayer.CameraMinZoomDistance,
        MaxZoom = LocalPlayer.CameraMaxZoomDistance,
    }
    DBD_CaptureCharacterState(LocalPlayer.Character)
end

local function DBD_StopLoop()
    local localConnection = DBD_Conn
    DBD_Conn = nil
    if localConnection then
        pcall(function() localConnection:Disconnect() end)
    end
    local globalConnection = DBD_GlobalEnv.MAWWW_DBDCameraConn
    if globalConnection and globalConnection ~= localConnection then
        pcall(function() globalConnection:Disconnect() end)
    end
    DBD_GlobalEnv.MAWWW_DBDCameraConn = nil
end

local function DBD_StartLoop()
    if DBD_Conn and DBD_Conn.Connected then return end
    DBD_Conn = MAWWW_Conn(RunService.RenderStepped, function()
        if not DBD_Config.Enabled then return end
        local camera = workspace.CurrentCamera
        if not camera then return end

        local targetFOV = math.clamp(tonumber(DBD_Config.FOV) or 70, 50, 120)
        if math.abs(camera.FieldOfView - targetFOV) > 0.1 then
            camera.FieldOfView = targetFOV
        end

        local distance = math.clamp(tonumber(DBD_Config.Distance) or 25, 1, 60)
        local targetMaxZoom = distance + 0.5
        local targetMinZoom = math.max(0.1, distance - 0.5)
        if math.abs(LocalPlayer.CameraMaxZoomDistance - targetMaxZoom) > 0.1 then
            LocalPlayer.CameraMaxZoomDistance = targetMaxZoom
        end
        if math.abs(LocalPlayer.CameraMinZoomDistance - targetMinZoom) > 0.1 then
            LocalPlayer.CameraMinZoomDistance = targetMinZoom
        end

        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            local targetOffset = Vector3.new(0, tonumber(DBD_Config.Height) or 0, 0)
            if (hum.CameraOffset - targetOffset).Magnitude > 0.01 then
                hum.CameraOffset = targetOffset
            end
        end
    end)
    DBD_GlobalEnv.MAWWW_DBDCameraConn = DBD_Conn
end

local function DBD_ResetAll()
    DBD_StopLoop()
    DBD_Config.Enabled = false
    DBD_RestoreCharacterState()

    local camera = workspace.CurrentCamera
    local savedCamera = DBD_OriginalCameraState
    if savedCamera then
        pcall(function()
            if camera then camera.FieldOfView = savedCamera.FieldOfView or 70 end
        end)
        pcall(function() LocalPlayer.CameraMinZoomDistance = savedCamera.MinZoom or 0.5 end)
        pcall(function() LocalPlayer.CameraMaxZoomDistance = savedCamera.MaxZoom or 128 end)
    end

    DBD_OriginalCameraState = nil
    DBD_CharacterSnapshot = nil
end

local function DBD_W424_SetEnabled(on)
    on = on == true
    VD.DBDCamera = on

    if on then
        if not DBD_Config.Enabled then
            DBD_CaptureCameraState()
        end
        DBD_Config.Enabled = true
        if DBD_Config.UseCharScale then DBD_ApplyCharScale() end
        DBD_StartLoop()
        print("[DBD Camera] ON | Dist:", DBD_Config.Distance, "FOV:", DBD_Config.FOV, "H:", DBD_Config.Height)
        return
    end

    -- A false callback during UI initialization must not reset or change the camera.
    if not DBD_Config.Enabled and not DBD_OriginalCameraState and not DBD_CharacterSnapshot then
        DBD_StopLoop()
        return
    end
    DBD_ResetAll()
    print("[DBD Camera] OFF")
end

local function DBD_W424_SyncFromVD()
    DBD_Config.Distance = math.clamp(tonumber(VD.DBDCameraDistance) or 25, 1, 60)
    DBD_Config.FOV = math.clamp(tonumber(VD.DBDCameraFOV) or 70, 50, 120)
    DBD_Config.Height = math.clamp(tonumber(VD.DBDCameraHeight) or 0, -5, 10)
    DBD_Config.CharScale = math.clamp(tonumber(VD.DBDCameraCharScale) or 1, 0.01, 1)
    DBD_Config.UseCharScale = VD.DBDCameraUseCharScale == true
end

function DBD_Start()
    DBD_W424_SyncFromVD()
    DBD_W424_SetEnabled(true)
end

function DBD_Restore()
    DBD_W424_SetEnabled(false)
end

DBD_CharacterConnection = MAWWW_Conn(LocalPlayer.CharacterAdded, function(char)
    task.wait(0.35)
    if not DBD_Config.Enabled then return end
    DBD_CaptureCharacterState(char)
    if DBD_Config.UseCharScale then DBD_ApplyCharScale() end
    DBD_StartLoop()
end)
DBD_GlobalEnv.MAWWW_DBDCameraCharacterConnection = DBD_CharacterConnection
DBD_GlobalEnv.GANKZ_SetDBDCamera = DBD_W424_SetEnabled
DBD_GlobalEnv.MAWWW_DBDCameraRestore = DBD_ResetAll
DBD_W424_ConfigSync = DBD_W424_SyncFromVD

