--========================================================--
-- MAWWW HUB AUTO PARRY STATUS PANELS (V2-V5)
-- Visual style intentionally matches the original V1 status panel.
-- Parry engines remain independent; only the status-panel presentation is shared.
do
    local STATUS_GUI_NAME = "MawwwHubParryStatusVersions"
    local STATUS_ASSET_ID = "85621445423294"
    -- Keep this status panel outside PlayerGui so match/lobby transitions that rebuild PlayerGui do not remove it.
    local statusParent = MAWWW_GUI_PARENT or CoreGui or PlayerGui
    pcall(function()
        local old = statusParent and statusParent:FindFirstChild(STATUS_GUI_NAME)
        if old then old:Destroy() end
    end)

    local screen = Instance.new("ScreenGui")
    screen.Name = STATUS_GUI_NAME
    screen.ResetOnSpawn = false
    screen.IgnoreGuiInset = true
    pcall(function() screen.ScreenInsets = Enum.ScreenInsets.None end)
    screen.DisplayOrder = 16000
    screen.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    screen.Enabled = true
    screen.Parent = statusParent

    -- Match V1 exactly: 260x100 black/red card, 26px title bar, traffic lights,
    -- image background, red glow, killer-distance row, and cooldown/status row.
    local WIDTH, HEIGHT, GAP = 260, 100, 10
    local palette = {
        bg = Color3.fromRGB(8, 8, 10),
        bg2 = Color3.fromRGB(13, 13, 16),
        red = Color3.fromRGB(255, 30, 50),
        green = Color3.fromRGB(40, 200, 64),
        yellow = Color3.fromRGB(254, 188, 46),
        muted = Color3.fromRGB(75, 75, 83),
        white = Color3.fromRGB(245, 245, 247),
    }
    local stableRanges = getgenv().MAWWW_ParryPanelStableRanges or {}
    getgenv().MAWWW_ParryPanelStableRanges = stableRanges
    local rangeDefaults = {[2] = 6, [3] = 10, [4] = 10, [5] = 15}
    local rangeBounds = {[2] = {4, 25}, [3] = {4, 30}, [4] = {4, 20}, [5] = {5, 30}}
    for version = 2, 5 do
        local cached = tonumber(stableRanges[version]) or rangeDefaults[version]
        stableRanges[version] = math.clamp(cached, rangeBounds[version][1], rangeBounds[version][2])
    end

    local statusCards = {}
    local panelConnections = {}
    local panelBackgrounds = {}
    local function trackConnection(connection)
        if connection then table.insert(panelConnections, connection) end
        return connection
    end

    local function getViewportSize()
        local camera = Workspace.CurrentCamera
        if camera then
            local viewport = camera.ViewportSize
            if viewport and viewport.X > 0 and viewport.Y > 0 then return viewport end
        end
        local guiSize = screen.AbsoluteSize
        if guiSize and guiSize.X > 0 and guiSize.Y > 0 then return guiSize end
        return nil
    end

    local function attachDrag(cardInfo, handle)
        local card = cardInfo.Root
        local dragging, pointerType, activeInput, activeTouchId = false, nil, nil, nil
        local dragStartPoint, dragStartPosition, moved = nil, nil, false
        local DRAG_THRESHOLD = 3
        card.Active = true
        handle.Active = true
        handle.Selectable = false
        pcall(function() handle.AutoButtonColor = false end)

        local function point(input)
            return Vector2.new(input.Position.X, input.Position.Y)
        end
        local function touchId(input)
            local id = nil
            pcall(function() id = input.TouchId end)
            return id
        end
        local function sameTouch(input)
            if not input or input.UserInputType ~= Enum.UserInputType.Touch then return false end
            if input == activeInput then return true end
            local currentId = touchId(input)
            if activeTouchId ~= nil and currentId ~= nil then return currentId == activeTouchId end
            return true
        end
        local function beginDrag(input)
            local inputType = input.UserInputType
            if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then return end
            if dragging or not card.Visible then return end
            if not getViewportSize() then return end
            dragging = true
            cardInfo.Dragging = true
            pointerType = inputType
            activeInput = input
            activeTouchId = inputType == Enum.UserInputType.Touch and touchId(input) or nil
            dragStartPoint = point(input)
            dragStartPosition = card.Position
            moved = false
        end
        local function moveDrag(newPoint, sourceType, input)
            if not dragging or not dragStartPoint or not dragStartPosition then return end
            if pointerType == Enum.UserInputType.MouseButton1 then
                if sourceType ~= Enum.UserInputType.MouseMovement then return end
            elseif pointerType == Enum.UserInputType.Touch then
                if sourceType ~= Enum.UserInputType.Touch or not sameTouch(input) then return end
            else
                return
            end
            local totalDelta = newPoint - dragStartPoint
            if not moved and totalDelta.Magnitude < DRAG_THRESHOLD then return end
            moved = true
            cardInfo.UserMoved = true
            local viewport = getViewportSize()
            if not viewport then return end
            local canvas = screen.AbsoluteSize
            if not canvas or canvas.X <= 0 or canvas.Y <= 0 then canvas = viewport end
            local width = math.max(1, card.AbsoluteSize.X)
            local height = math.max(1, card.AbsoluteSize.Y)
            local maxX = math.max(2, canvas.X - width - 2)
            local maxY = math.max(2, canvas.Y - height - 2)
            local startPos = dragStartPosition
            local startAbsX = startPos.X.Scale * canvas.X + startPos.X.Offset
            local startAbsY = startPos.Y.Scale * canvas.Y + startPos.Y.Offset
            local x = math.clamp(startAbsX + totalDelta.X, 2, maxX)
            local y = math.clamp(startAbsY + totalDelta.Y, 2, maxY)
            card.Position = UDim2.new(startPos.X.Scale, x - startPos.X.Scale * canvas.X,
                startPos.Y.Scale, y - startPos.Y.Scale * canvas.Y)
        end
        local function endDrag(input)
            if not dragging or not input then return end
            if pointerType == Enum.UserInputType.MouseButton1 then
                if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
            elseif pointerType == Enum.UserInputType.Touch then
                if not sameTouch(input) then return end
            else
                return
            end
            dragging = false
            cardInfo.Dragging = false
            pointerType, activeInput, activeTouchId = nil, nil, nil
            dragStartPoint, dragStartPosition, moved = nil, nil, false
        end
        trackConnection(handle.InputBegan:Connect(beginDrag))
        trackConnection(card.InputBegan:Connect(beginDrag))
        trackConnection(MAWWW_Conn(UserInputService.InputChanged, function(input)
            if not dragging then return end
            if pointerType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement then
                moveDrag(point(input), Enum.UserInputType.MouseMovement, input)
            elseif pointerType == Enum.UserInputType.Touch and input.UserInputType == Enum.UserInputType.Touch then
                moveDrag(point(input), Enum.UserInputType.Touch, input)
            end
        end))
        trackConnection(UserInputService.TouchMoved:Connect(function(input)
            if dragging and pointerType == Enum.UserInputType.Touch then moveDrag(point(input), Enum.UserInputType.Touch, input) end
        end))
        trackConnection(MAWWW_Conn(UserInputService.InputEnded, endDrag))
        trackConnection(UserInputService.TouchEnded:Connect(endDrag))
    end

    local function createStatusCard(version, slot)
        local card = Instance.new("Frame")
        card.Name = "AutoParryV" .. tostring(version) .. "Status"
        card.Size = UDim2.fromOffset(WIDTH, HEIGHT)
        card.AnchorPoint = Vector2.new(0, 0)
        card.Position = UDim2.new(1, -(WIDTH + 14), 1, -(HEIGHT + 14 + (slot - 1) * (HEIGHT + GAP)))
        card.BackgroundColor3 = palette.bg
        card.BackgroundTransparency = 0.08
        card.BorderSizePixel = 0
        card.Visible = false
        card.ClipsDescendants = true
        card.ZIndex = 1
        card.Parent = screen
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 12)
        corner.Parent = card
        local stroke = Instance.new("UIStroke")
        stroke.Color = palette.red
        stroke.Thickness = 1.5
        stroke.Transparency = 0.2
        stroke.Parent = card
        local glow = Instance.new("UIStroke")
        glow.Name = "RedGlow"
        glow.Color = palette.red
        glow.Thickness = 6
        glow.Transparency = 0.8
        glow.Parent = card

        local background = Instance.new("ImageLabel")
        background.Name = "MawwwHubBackground"
        background.BackgroundTransparency = 1
        background.BorderSizePixel = 0
        background.Position = UDim2.fromScale(0, 0)
        background.Size = UDim2.fromScale(1, 1)
        background.Image = "rbxassetid://" .. STATUS_ASSET_ID
        background.ImageTransparency = 0.16
        background.ScaleType = Enum.ScaleType.Crop
        background.Active = false
        background.Selectable = false
        background.ZIndex = 1
        background.Parent = card
        local bgCorner = Instance.new("UICorner")
        bgCorner.CornerRadius = UDim.new(0, 12)
        bgCorner.Parent = background
        table.insert(panelBackgrounds, background)

        local topBar = Instance.new("Frame")
        topBar.Name = "TopBar"
        topBar.Size = UDim2.new(1, -2, 0, 26)
        topBar.Position = UDim2.fromOffset(1, 1)
        topBar.BackgroundColor3 = palette.bg2
        topBar.BorderSizePixel = 0
        topBar.ZIndex = 3
        topBar.Parent = card
        local topCorner = Instance.new("UICorner")
        topCorner.CornerRadius = UDim.new(0, 11)
        topCorner.Parent = topBar
        local topStroke = Instance.new("UIStroke")
        topStroke.Color = palette.red
        topStroke.Thickness = 1
        topStroke.Transparency = 0.8
        topStroke.Parent = topBar

        local traffic = Instance.new("Frame")
        traffic.Name = "TrafficLights"
        traffic.Size = UDim2.fromOffset(45, 10)
        traffic.Position = UDim2.fromOffset(10, 8)
        traffic.BackgroundTransparency = 1
        traffic.ZIndex = 4
        traffic.Parent = topBar
        local trafficColors = {
            Color3.fromRGB(255, 95, 87),
            Color3.fromRGB(254, 188, 46),
            Color3.fromRGB(40, 200, 64),
        }
        for i, color in ipairs(trafficColors) do
            local dot = Instance.new("Frame")
            dot.Name = "TrafficLight" .. tostring(i)
            dot.Size = UDim2.fromOffset(7, 7)
            dot.Position = UDim2.fromOffset((i - 1) * 14, 0)
            dot.BackgroundColor3 = color
            dot.BorderSizePixel = 0
            dot.ZIndex = 4
            dot.Parent = traffic
            local dotCorner = Instance.new("UICorner")
            dotCorner.CornerRadius = UDim.new(1, 0)
            dotCorner.Parent = dot
        end

        local header = Instance.new("TextLabel")
        header.Name = "Header"
        header.BackgroundTransparency = 1
        header.Size = UDim2.new(1, -60, 1, 0)
        header.Position = UDim2.fromOffset(55, 0)
        header.Font = Enum.Font.GothamBold
        header.Text = "MAWWW HUB"
        header.TextColor3 = palette.white
        header.TextTransparency = 0.02
        header.TextSize = 11
        header.TextXAlignment = Enum.TextXAlignment.Left
        header.ZIndex = 5
        header.Parent = topBar

        local indicator = Instance.new("Frame")
        indicator.Name = "Indicator"
        indicator.Size = UDim2.fromOffset(6, 6)
        indicator.Position = UDim2.fromOffset(5, 11)
        indicator.BackgroundColor3 = palette.muted
        indicator.BorderSizePixel = 0
        indicator.ZIndex = 4
        indicator.Parent = card
        local indicatorCorner = Instance.new("UICorner")
        indicatorCorner.CornerRadius = UDim.new(1, 0)
        indicatorCorner.Parent = indicator
        local indicatorGlow = Instance.new("UIStroke")
        indicatorGlow.Thickness = 3
        indicatorGlow.Color = palette.muted
        indicatorGlow.Transparency = 0.5
        indicatorGlow.Parent = indicator

        local distanceLabel = Instance.new("TextLabel")
        distanceLabel.Name = "Distance"
        distanceLabel.BackgroundTransparency = 1
        distanceLabel.Position = UDim2.fromOffset(20, 40)
        distanceLabel.Size = UDim2.new(1, -25, 0, 15)
        distanceLabel.Font = Enum.Font.GothamBold
        distanceLabel.Text = "Killer Distance : N/A"
        distanceLabel.TextColor3 = palette.white
        distanceLabel.TextSize = 12
        distanceLabel.TextXAlignment = Enum.TextXAlignment.Left
        distanceLabel.ZIndex = 4
        distanceLabel.Parent = card

        local statusLabel = Instance.new("TextLabel")
        statusLabel.Name = "Status"
        statusLabel.BackgroundTransparency = 1
        statusLabel.Position = UDim2.fromOffset(20, 58)
        statusLabel.Size = UDim2.new(1, -25, 0, 15)
        statusLabel.Font = Enum.Font.GothamBold
        statusLabel.Text = "Status : OFF"
        statusLabel.TextColor3 = palette.muted
        statusLabel.TextSize = 12
        statusLabel.TextXAlignment = Enum.TextXAlignment.Left
        statusLabel.ZIndex = 4
        statusLabel.Parent = card

        local info = {
            Root = card, Stroke = stroke, Glow = glow, Indicator = indicator,
            IndicatorGlow = indicatorGlow, Status = statusLabel, Distance = distanceLabel,
            Version = version, Slot = slot, UserMoved = false,
        }
        attachDrag(info, topBar)
        return info
    end

    statusCards[2] = createStatusCard(2, 1)
    statusCards[3] = createStatusCard(3, 2)
    statusCards[4] = createStatusCard(4, 3)
    statusCards[5] = createStatusCard(5, 4)

    -- The same image is used by V1 and all four cards. Preload the duplicate
    -- asset instances together, rather than starting one task per panel.
    task.spawn(function()
        local contentProvider = game:GetService("ContentProvider")
        pcall(function() contentProvider:PreloadAsync(panelBackgrounds) end)
        local first = panelBackgrounds[1]
        if first and first.Parent and not first.IsLoaded then
            local thumb = "rbxthumb://type=Asset&id=" .. STATUS_ASSET_ID .. "&w=420&h=420"
            for _, background in ipairs(panelBackgrounds) do
                if background and background.Parent then background.Image = thumb end
            end
            pcall(function() contentProvider:PreloadAsync(panelBackgrounds) end)
        end
    end)

    local function isStatusKiller(candidate)
        if not candidate or candidate == Player then return false end
        local okDetected, detected = pcall(function()
            return type(VD_IsKillerPlayer) == "function" and VD_IsKillerPlayer(candidate) == true
        end)
        if okDetected and detected then return true end

        local teamName = string.lower((candidate.Team and candidate.Team.Name) or "")
        if teamName:find("killer", 1, true)
            or teamName:find("murder", 1, true)
            or teamName:find("beast", 1, true) then
            return true
        end
        if candidate:GetAttribute("IsKiller") == true
            or candidate:GetAttribute("IsKillerRole") == true
            or tostring(candidate:GetAttribute("Role") or ""):lower() == "killer" then
            return true
        end
        local char = candidate.Character
        if char and (char:GetAttribute("IsKiller") == true
            or char:GetAttribute("IsKillerRole") == true
            or tostring(char:GetAttribute("Role") or ""):lower() == "killer"
            or char:GetAttribute("KillerType") ~= nil
            or char:GetAttribute("KillerWeapon") ~= nil
            or char:FindFirstChild("Killer") ~= nil) then
            return true
        end
        return false
    end

    local function getNearestKillerDistance()
        local myChar = Player and Player.Character
        local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar.PrimaryPart)
        if not myRoot then return nil end

        -- Match V1: only display a distance for a survivor in an active round.
        local myTeam = string.lower((Player.Team and Player.Team.Name) or "")
        local survivorRole = myTeam:find("survivor", 1, true)
            or myTeam:find("innocent", 1, true)
            or myTeam:find("human", 1, true)
            or (Player:GetAttribute("IsSurvivor") == true)
            or (myChar:GetAttribute("IsSurvivor") == true)
        if not survivorRole then return nil end

        local closest = math.huge
        local okPlayers, playerList = pcall(MawwwGetPlayers)
        if not okPlayers or type(playerList) ~= "table" then return nil end
        for _, candidate in ipairs(playerList) do
            if isStatusKiller(candidate) then
                local kChar = candidate.Character
                local kRoot = kChar and (kChar:FindFirstChild("HumanoidRootPart") or kChar.PrimaryPart)
                if kRoot then
                    local dist = (myRoot.Position - kRoot.Position).Magnitude
                    if dist < closest then closest = dist end
                end
            end
        end
        if closest == math.huge or closest >= 999 then return nil end
        return closest
    end

    local function getVersionState(version, now)
        local enabled, cooldown, waiting, remaining = false, false, false, 0
        if version == 2 then
            enabled = VD.Wisnu_AutoParry == true
            local state = ParryV2 and ParryV2.State
            if state then
                cooldown = state.Cooldown == true
                waiting = state.WaitingForResult == true
                remaining = math.max(0, (tonumber(state.CooldownEnd) or 0) - now)
            end
        elseif version == 3 then
            enabled = VD.SURV_AutoParryV3 == true
            local cd = AutoParryV3Module and AutoParryV3Module.Cooldown
            if cd then
                cooldown = cd.OnCooldown == true
                waiting = cd.WaitingForResult == true
                remaining = math.max(0, (tonumber(cd.CooldownEnd) or 0) - now)
            end
        elseif version == 4 then
            enabled = VD.PARRY_V4_Enabled == true
            local cd = ParryV4 and ParryV4.Cooldown
            if cd then
                cooldown = cd.OnCooldown == true
                waiting = cd.WaitingForResult == true
                remaining = math.max(0, (tonumber(cd.CooldownEnd) or 0) - now)
            end
        elseif version == 5 then
            enabled = VD.SURV_AutoParryV5 == true
            local state = AutoParryV5Module and AutoParryV5Module.State
            if state then
                cooldown = state.ParryCooldown == true
                remaining = math.max(0, (tonumber(state.ParryCooldownEnd) or 0) - now)
            end
        end
        return enabled, cooldown, waiting, remaining
    end

    local lastLayout = 0
    local lastDistanceRefresh = 0
    local cachedKillerDistance = nil
    trackConnection(MAWWW_Conn(RunService.RenderStepped, function()
        local now = os.clock()
        if now - lastLayout < 0.15 then return end
        lastLayout = now
        -- Keep the panel alive across lobby/match transitions: re-attach it if its
        -- container was cleared. (A destroyed panel needs a re-execute.)
        if screen and not screen.Parent then
            pcall(function() screen.Parent = MAWWW_GUI_PARENT or CoreGui or PlayerGui end)
        end

        -- Avoid scanning player/killer positions when every status panel is hidden.
        local anyPanelVisible = false
        for version = 2, 5 do
            local key = "PARRY_SHOW_STATUS_V" .. tostring(version)
            local show = VD[key] == true
            statusCards[version].Root.Visible = show
            if show then anyPanelVisible = true end
        end
        if not anyPanelVisible then return end

        if now - lastDistanceRefresh >= 0.15 then
            lastDistanceRefresh = now
            cachedKillerDistance = getNearestKillerDistance()
        end
        local distanceText = cachedKillerDistance and string.format("Killer Distance : %.1f", cachedKillerDistance)
            or "Killer Distance : N/A"
        local selectedCount = 0
        for version = 2, 5 do
            local key = "PARRY_SHOW_STATUS_V" .. tostring(version)
            local info = statusCards[version]
            local show = VD[key] == true
            if show then
                selectedCount += 1
                if not info.UserMoved and not info.Dragging then
                    info.Root.Position = UDim2.new(1, -(WIDTH + 14), 1, -(HEIGHT + 14 + (selectedCount - 1) * (HEIGHT + GAP)))
                end
                local enabled, cooldown, waiting, remaining = getVersionState(version, now)
                local statusText, color
                if cooldown then
                    if remaining > 0 then
                        statusText = string.format("Status : Parry CD (%.1fs)", remaining)
                    else
                        statusText = "Status : COOLDOWN"
                    end
                    color = palette.yellow
                elseif waiting then
                    statusText, color = "Status : WAITING", palette.yellow
                elseif enabled then
                    statusText, color = "Status : READY", palette.green
                else
                    statusText, color = "Status : OFF", palette.muted
                end
                info.Distance.Text = distanceText
                info.Status.Text = statusText
                info.Status.TextColor3 = color
                info.Indicator.BackgroundColor3 = color
                info.IndicatorGlow.Color = color
                info.Stroke.Color = palette.red
                info.Glow.Color = palette.red
            end
        end
    end))

    getgenv().MAWWW_ParryStatusPanelsShutdown = function()
        for _, connection in ipairs(panelConnections) do
            pcall(function() connection:Disconnect() end)
        end
        table.clear(panelConnections)
        pcall(function() if screen and screen.Parent then screen:Destroy() end end)
    end
end

-- Movement & Moonwalk

MoonwalkConn = nil
function startMoonwalk()
    if MoonwalkConn then MoonwalkConn:Disconnect(); MoonwalkConn = nil end
    MoonwalkConn = MAWWW_Conn(RunService.RenderStepped, function()
        local char = Player.Character
        local humanoid = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not VD.Moonwalk then
            -- Disabled (UI toggle or quick button): restore once, then stop the
            -- per-frame callback so it no longer fights Shift Lock / game camera.
            if humanoid then
                if humanoid.AutoRotate == false and VD.ShiftLock ~= true then humanoid.AutoRotate = true end
                if humanoid.WalkSpeed == 13 then humanoid.WalkSpeed = 16 end
            end
            local selfConnection = MoonwalkConn
            MoonwalkConn = nil
            if selfConnection then pcall(function() selfConnection:Disconnect() end) end
            return
        end
        if (not humanoid) or humanoid.Health <= 0 then return end
        local cam = workspace.CurrentCamera
        if not (hrp and cam) then return end
        if humanoid.AutoRotate then humanoid.AutoRotate = false end
        local look = cam.CFrame.LookVector
        local flat = Vector3.new(look.X, 0, look.Z)
        if flat.Magnitude < 0.001 then return end
        flat = flat.Unit
        local spamSpeed = tonumber(VD.MoonwalkSpam) or 30
        local intensity = tonumber(VD.MoonwalkIntensity) or 35
        local angle = math.sin(tick() * spamSpeed) * intensity
        local baseCF = CFrame.new(hrp.Position, hrp.Position + flat)
        hrp.CFrame = baseCF * CFrame.Angles(0, math.rad(angle), 0)
    end)
end
getgenv().MAWWW_StartMoonwalk = startMoonwalk
RegToggle(Tabs.Player, "Moonwalk", "Enable moonwalk", false, "Moonwalk", function(v)
    if v then
        startMoonwalk()
    elseif MoonwalkConn then
        MoonwalkConn:Disconnect()
        MoonwalkConn = nil
        local h = getHum()
        if h then h.AutoRotate = true end
    end
end)
RegSlider(Tabs.Player, "Moonwalk Spam Speed", "Spam speed", 30, 1, 50, 1, "MoonwalkSpam")
RegSlider(Tabs.Player, "Moonwalk Intensity", "Rotation intensity", 35, 1, 50, 1, "MoonwalkIntensity")
RegToggle(Tabs.Player, "Show Moonwalk Icon", "Show quick toggle icon", false, "ShowMoonwalkIcon", function(v)
    if getgenv().MAWWW_QuickRefresh then pcall(getgenv().MAWWW_QuickRefresh) end
end)
