function MAWWW_GetSafeGuiParent()
    if gethui then
        local ok, gui = pcall(gethui)
        if ok and gui then return gui end
    end
    if CoreGui then return CoreGui end
    return LocalPlayer:FindFirstChild("PlayerGui")
end

-- Shared ToF floating selector manager. The implementation is assigned below,
-- after the V2 engine is initialized; V1/V3 callbacks resolve these same locals.
local MAWWW_FloatingToFTargetSelectorUIs = {}
