    if not parent then return end
    if MAWWW_ToFState.TargetGui and MAWWW_ToFState.TargetGui.Parent then return end

    local old = parent:FindFirstChild("ToFTargetSelector")
    if old then pcall(function() old:Destroy() end) end

    -- Prevent a stale drag connection from surviving a rebuilt selector.
    if MAWWW_ToFState.DragConnection then
        pcall(function() MAWWW_ToFState.DragConnection:Disconnect() end)
        MAWWW_ToFState.DragConnection = nil
    end

    local gui = Instance.new("ScreenGui")
