    targetModeBackground.Size = UDim2.fromScale(1, 1)
    targetModeBackground.Position = UDim2.fromScale(0, 0)
    targetModeBackground.BackgroundColor3 = Color3.fromRGB(16, 18, 24)
    targetModeBackground.BackgroundTransparency = 0.08
    targetModeBackground.Image = MAWWW_TOF_TARGET_MODE_THUMBNAIL_ID
    targetModeBackground.ImageTransparency = 0.06
    targetModeBackground.ScaleType = Enum.ScaleType.Crop
    targetModeBackground.ZIndex = 120
    targetModeBackground.Parent = frame
    Instance.new("UICorner", targetModeBackground).CornerRadius = UDim.new(0, 8)
    MAWWW_ApplyToFTargetImage(targetModeBackground, Enum.ScaleType.Crop, true)

    local stroke = Instance.new("UIStroke", frame)
    stroke.Color = Color3.fromRGB(96, 72, 160)
    stroke.Thickness = 1

    local header = Instance.new("Frame")
    header.Size = UDim2.new(1, 0, 0, 26)
    header.BackgroundColor3 = Color3.fromRGB(24, 26, 34)
    header.BorderSizePixel = 0
    header.ZIndex = 121
    header.Parent = frame
    Instance.new("UICorner", header).CornerRadius = UDim.new(0, 8)

    local headerFix = Instance.new("Frame")
    headerFix.Size = UDim2.new(1, 0, 0, 8)
    headerFix.Position = UDim2.new(0, 0, 1, -8)
    headerFix.BackgroundColor3 = Color3.fromRGB(24, 26, 34)
    headerFix.BorderSizePixel = 0
    headerFix.ZIndex = 121
    headerFix.Parent = header

    local headerDiv = Instance.new("Frame")
    headerDiv.Size = UDim2.new(1, 0, 0, 1)
    headerDiv.Position = UDim2.new(0, 0, 1, -1)
    headerDiv.BackgroundColor3 = Color3.fromRGB(48, 42, 72)
    headerDiv.BorderSizePixel = 0
    headerDiv.ZIndex = 122
    headerDiv.Parent = header

    local dragArea = Instance.new("Frame")
    dragArea.Size = UDim2.new(1, -30, 1, 0)
    dragArea.BackgroundTransparency = 1
    dragArea.Active = true
    dragArea.ZIndex = 123
    dragArea.Parent = header

    local minimizeBtn = Instance.new("TextButton")
    minimizeBtn.Size = UDim2.new(0, 26, 1, 0)
    minimizeBtn.Position = UDim2.new(1, -28, 0, 0)
    minimizeBtn.BackgroundTransparency = 1
    minimizeBtn.Text = "-"
    minimizeBtn.TextColor3 = Color3.fromRGB(185, 190, 205)
    minimizeBtn.Font = Enum.Font.GothamBold
    minimizeBtn.TextSize = 14
    minimizeBtn.AutoButtonColor = false
    minimizeBtn.ZIndex = 124
    minimizeBtn.Parent = header

    local headerLbl = Instance.new("TextLabel")
    headerLbl.Size = UDim2.new(1, -44, 1, 0)
    headerLbl.Position = UDim2.new(0, 10, 0, 0)
    headerLbl.BackgroundTransparency = 1
    headerLbl.Text = "TOF  •  TARGET SELECT"
    headerLbl.TextColor3 = Color3.fromRGB(210, 215, 230)
    headerLbl.Font = Enum.Font.GothamBold
    headerLbl.TextSize = 10
    headerLbl.TextXAlignment = Enum.TextXAlignment.Left
    headerLbl.ZIndex = 124
    headerLbl.Parent = header

    local btnContainer = Instance.new("Frame")
    btnContainer.Size = UDim2.new(1, -14, 0, 76)
    btnContainer.Position = UDim2.new(0, 7, 0, 31)
    btnContainer.BackgroundTransparency = 1
    btnContainer.ZIndex = 121
    btnContainer.Parent = frame

    local layout = Instance.new("UIListLayout", btnContainer)
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 4)

    local isMinimized = false
    minimizeBtn.Activated:Connect(function()
        isMinimized = not isMinimized
        minimizeBtn.Text = isMinimized and "+" or "-"
        btnContainer.Visible = not isMinimized
        frame.Size = isMinimized and UDim2.new(0, 168, 0, 26) or UDim2.new(0, 168, 0, 118)
    end)

    local modes = {
        { Internal = "Killer", Display = "KILLER", Key = "K", Asset = MAWWW_TARGET_MODE_ASSETS.Killer },
        { Internal = "Survivors", Display = "SURVIVOR", Key = "J", Asset = MAWWW_TARGET_MODE_ASSETS.Survivors },
        { Internal = "Zombie", Display = "ZOMBIE", Key = "L", Asset = MAWWW_TARGET_MODE_ASSETS.Zombie },
    }

    MAWWW_ToFModeButtons = {}
    for i, mode in ipairs(modes) do
        -- Capture each option locally so touch callbacks always apply the
        -- option the player tapped, not a reused loop variable.
        local selectedMode = mode.Internal
        local selectedDisplay = mode.Display
        local selectedKey = mode.Key
        local btn = Instance.new("TextButton")
        btn.Name = selectedMode
        btn.Size = UDim2.new(1, 0, 0, 22)
        btn.BorderSizePixel = 0
        btn.BackgroundColor3 = Color3.fromRGB(30, 32, 40)
        btn.Font = Enum.Font.GothamBold
        btn.TextSize = 10
        btn.Text = ""
        btn.AutoButtonColor = false
        btn.Active = true
        btn.Selectable = true
        pcall(function() btn.Interactable = true end)
        btn.LayoutOrder = i
        btn.ZIndex = 122
        btn.Parent = btnContainer
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)

        local btnStroke = Instance.new("UIStroke", btn)
        btnStroke.Color = Color3.fromRGB(58, 62, 78)
        btnStroke.Thickness = 1

        local img = Instance.new("ImageLabel")
        img.Name = "ModeImage"
        img.Size = UDim2.fromOffset(18, 18)
        img.Position = UDim2.fromOffset(3, 2)
        img.BackgroundTransparency = 1
        img.Active = false
        img.Selectable = false
        img.Image = MAWWW_TOF_TARGET_MODE_THUMBNAIL_ID
        img.ImageTransparency = 0.12
        img.ScaleType = Enum.ScaleType.Fit
        img.ZIndex = 123
        img.Parent = btn
        MAWWW_ApplyToFTargetImage(img, Enum.ScaleType.Fit, true)

        local label = Instance.new("TextLabel")
        label.Name = "ModeLabel"
        label.Size = UDim2.new(1, -56, 1, 0)
        label.Position = UDim2.fromOffset(28, 0)
        label.BackgroundTransparency = 1
        label.Active = false
        label.Selectable = false
        label.Text = selectedDisplay
        label.TextColor3 = Color3.fromRGB(155, 160, 175)
        label.Font = Enum.Font.GothamBold
        label.TextSize = 10
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.ZIndex = 123
        label.Parent = btn

        local keyLabel = Instance.new("TextLabel")
        keyLabel.Name = "ModeKey"
        keyLabel.Size = UDim2.new(0, 22, 1, 0)
        keyLabel.Position = UDim2.new(1, -25, 0, 0)
        keyLabel.BackgroundTransparency = 1
        keyLabel.Active = false
        keyLabel.Selectable = false
        keyLabel.Text = selectedKey
        keyLabel.TextColor3 = Color3.fromRGB(125, 130, 145)
        keyLabel.Font = Enum.Font.GothamBold
        keyLabel.TextSize = 10
        keyLabel.TextXAlignment = Enum.TextXAlignment.Center
        keyLabel.ZIndex = 123
        keyLabel.Parent = btn

        btn.Activated:Connect(function()
            MAWWW_ToFSetTargetMode(selectedMode, false)
        end)

        MAWWW_ToFModeButtons[selectedMode] = btn
    end
    MAWWW_ToFRefreshTargetButtons()

    local dragging = false
    local dragStart, startPos

    dragArea.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragStart = input.Position
            startPos = frame.Position
            dragging = true
        end
    end)

    dragArea.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)

    MAWWW_ToFState.DragConnection = MAWWW_Conn(UserInputService.InputChanged, function(input)
        if not dragging or not frame.Parent then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then
            local delta = input.Position - dragStart
            local newPos = UDim2.new(
                startPos.X.Scale,
                startPos.X.Offset + delta.X,
                startPos.Y.Scale,
                startPos.Y.Offset + delta.Y
            )
            frame.Position = newPos
            MAWWW_ToFState.SavedUIPos = newPos
        end
    end)

    MAWWW_ToFState.TargetGui = gui
end

function MAWWW_ToFDestroyTargetSelectorUI()
    if MAWWW_ToFState.DragConnection then
        pcall(function() MAWWW_ToFState.DragConnection:Disconnect() end)
        MAWWW_ToFState.DragConnection = nil
    end

    if MAWWW_ToFState.TargetGui then
        pcall(function() MAWWW_ToFState.TargetGui:Destroy() end)
        MAWWW_ToFState.TargetGui = nil
    end
    MAWWW_ToFModeButtons = {}
end

function MAWWW_ToFStartConnection()
    if MAWWW_ToFState.Connection then return end
    MAWWW_ToFState.Connection = MAWWW_Conn(RunService.Heartbeat, function()
        if not VD.TOF_SilentAim or not MAWWW_ToFState.IsAiming then
            if MAWWW_ToFState.LaserBeam then MAWWW_ToFState.LaserBeam.Transparency = 1 end
            return
        end

        local _, _, originPos, targetPos = MAWWW_ToFGetTargetPosition()
        if originPos and targetPos then
            pcall(function()
                local char = LocalPlayer.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp and not char:GetAttribute("IsCarried") then
                    hrp.CFrame = CFrame.new(hrp.Position, Vector3.new(targetPos.X, hrp.Position.Y, targetPos.Z))
                end
            end)

            if VD.TOF_Laser then
                MAWWW_ToFUpdateLaser(originPos, targetPos)
            elseif MAWWW_ToFState.LaserBeam then
                MAWWW_ToFState.LaserBeam.Transparency = 1
            end
        elseif MAWWW_ToFState.LaserBeam then
            MAWWW_ToFState.LaserBeam.Transparency = 1
        end
    end)
end

function MAWWW_ToFStopConnection()
    if MAWWW_ToFState.Connection then
        pcall(function() MAWWW_ToFState.Connection:Disconnect() end)
        MAWWW_ToFState.Connection = nil
    end
    MAWWW_ToFState.IsAiming = false
    MAWWW_ToFClearLaser()
end

function MAWWW_ToFDisconnectInputs()
    if MAWWW_ToFState.InputBegan then pcall(function() MAWWW_ToFState.InputBegan:Disconnect() end) end
    if MAWWW_ToFState.InputEnded then pcall(function() MAWWW_ToFState.InputEnded:Disconnect() end) end
    MAWWW_ToFState.InputBegan = nil
    MAWWW_ToFState.InputEnded = nil
end

MAWWW_SetToFSilentAim = nil

function MAWWW_ToFEnsureInputs()
    if not MAWWW_ToFState.InputBegan then
        MAWWW_ToFState.InputBegan = MAWWW_Conn(UserInputService.InputBegan, function(input, gameProcessed)
            if gameProcessed then return end

            local keyCode = MAWWW_ToFKeyCodes[VD.TOF_Key or "None"]
            if keyCode and input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == keyCode then
                MAWWW_SetToFSilentAim(not VD.TOF_SilentAim)
                return
            end

            if not VD.TOF_SilentAim then return end
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or (input.UserInputType == Enum.UserInputType.Touch and MAWWW_ToFIsTouchOnShootButton(input)) then
                MAWWW_ToFState.IsAiming = true
                if input.UserInputType == Enum.UserInputType.Touch then
                    MAWWW_ToFState.TouchInput = input
                end
                MAWWW_ToFDoShoot()
                return
            end

            if input.UserInputType == Enum.UserInputType.Keyboard then
                if input.KeyCode == Enum.KeyCode.K then
                    MAWWW_ToFSetTargetMode("Killer", true)
                elseif input.KeyCode == Enum.KeyCode.J then
                    MAWWW_ToFSetTargetMode("Survivors", true)
                elseif input.KeyCode == Enum.KeyCode.L then
                    MAWWW_ToFSetTargetMode("Zombie", true)
                end
            end
        end)
    end
    if not MAWWW_ToFState.InputEnded then
        MAWWW_ToFState.InputEnded = MAWWW_Conn(UserInputService.InputEnded, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
            or (input.UserInputType == Enum.UserInputType.Touch and input == MAWWW_ToFState.TouchInput) then
                MAWWW_ToFState.IsAiming = false
                if input == MAWWW_ToFState.TouchInput then MAWWW_ToFState.TouchInput = nil end
                if MAWWW_ToFState.LaserBeam then MAWWW_ToFState.LaserBeam.Transparency = 1 end
            end
        end)
    end
end

MAWWW_SetToFSilentAim = function(enabled)
    if MAWWW_PREMIUM_FEATURES_LOCKED and enabled == true then
        VD.TOF_SilentAim = false
        pcall(MAWWW_ToFDestroyTargetSelectorUI)
        pcall(function() if type(MAWWW_DestroyFloatingToFTargetSelector) == "function" then MAWWW_DestroyFloatingToFTargetSelector("V1") end end)
        pcall(MAWWW_ToFStopConnection)
        notify("Khusus Premium", "Silent Pistol hanya tersedia di Mawww Hub Premium.", 3)
        return false
    end
    VD.TOF_SilentAim = false
    MAWWW_ToFEnsureInputs()
    if VD.TOF_SilentAim then
        -- Do not create the old embedded panel as well; the shared floating panel
        -- is the only visible target selector for this ToF version.
        MAWWW_ToFDestroyTargetSelectorUI()
        if type(MAWWW_CreateFloatingToFTargetSelector) == "function" then
            MAWWW_CreateFloatingToFTargetSelector("V1", "TOF V1", {
                {Value = "Killer", Label = "KILLER"},
                {Value = "Survivors", Label = "SURVIVOR"},
                {Value = "Zombie", Label = "ZOMBIE"},
            }, function() return VD.TOF_TargetMode or "Killer" end, function(mode)
                VD.TOF_TargetMode = mode
                MAWWW_ToFSetTargetMode(mode, false)
            end, 1)
        else
            -- Safe fallback if a partial script execution interrupted setup.
            MAWWW_ToFCreateTargetSelectorUI()
        end
        MAWWW_ToFStartConnection()
    else
        MAWWW_ToFDestroyTargetSelectorUI()
        if type(MAWWW_DestroyFloatingToFTargetSelector) == "function" then
            MAWWW_DestroyFloatingToFTargetSelector("V1")
        end
        MAWWW_ToFStopConnection()
    end
end

MAWWW_ToFEnsureInputs()
getgenv().MAWWW_SetToFSilentAim = MAWWW_SetToFSilentAim
getgenv().MAWWW_ToFClearLaser = MAWWW_ToFClearLaser
getgenv().MAWWW_ToFSetTargetMode = MAWWW_ToFSetTargetMode
end)();


