RegDropdown(Tabs.AimTOFV1, "Silent Aim Key", "Toggle key for Silent Pistol / TOF V1.", {"None", "Q", "E", "R", "T", "F", "G", "H", "J", "K", "L", "X", "Z"}, "None", false, "TOF_Key")

-- SILENT PISTOL / TOF V2 — Imported from VD-MAWWW-UPDATE
--========================================================--

ToFV2 = (function()
    -- Keep the prior TOF V2 hook dormant if an older copy of the hub was already executed.
    VD.TOF2_Enabled = false
    VD.TOF2_SourceEnabled = VD.TOF2_SourceEnabled == true
    VD.TOF2_TargetMode = VD.TOF2_TargetMode or "Killer"
    VD.TOF2_Key = VD.TOF2_Key or "None"
    VD.TOF2_ShowLaser = VD.TOF2_ShowLaser ~= false
    VD.TOF2_WallCheck = VD.TOF2_WallCheck == true
    VD.TOF2_BlockKnocked = VD.TOF2_BlockKnocked ~= false
        local ToFState = {
            Connection = nil, LaserBeam = nil, TargetGui = nil,
            InputBegan = nil, InputEnded = nil, TouchInput = nil,
            IsAiming = false, SavedUIPos = UDim2.new(0.5, -100, 0, 110),
            SCPCache = {}, SCPCacheTimer = 0
        }
        local ToFKeyCodes = { None=nil, Q=Enum.KeyCode.Q, E=Enum.KeyCode.E, R=Enum.KeyCode.R, T=Enum.KeyCode.T, F=Enum.KeyCode.F, G=Enum.KeyCode.G, H=Enum.KeyCode.H, J=Enum.KeyCode.J, K=Enum.KeyCode.K, L=Enum.KeyCode.L, X=Enum.KeyCode.X, Z=Enum.KeyCode.Z }
        local function TeamIs(player, role)
            if not player or not player.Team or type(player.Team.Name) ~= "string" then
                return false
            end
            local teamName = string.lower(player.Team.Name)
            local expected = string.lower(tostring(role or ""))
            if expected == "survivors" then expected = "survivor" end
            return string.find(teamName, expected, 1, true) ~= nil
        end
        local function ToF_IsDowned(c)
            if not c then return true end
            local hrp = c:FindFirstChild("HumanoidRootPart"); if not hrp then return true end
            local h = c:FindFirstChildOfClass("Humanoid"); if h and h.Health<=0 then return true end
            if c:GetAttribute("Knocked")==true then return true end
            if c:GetAttribute("IsHooked")==true then return true end
            if c:GetAttribute("IsCarried")==true then return true end
            return false
        end
        local function ToF_IsBlocked()
            if VD.TOF2_BlockKnocked == false then return false end
            local c = LocalPlayer.Character
            if not c then return true end
            return ToF_IsDowned(c)
        end
        local function ToF_GetEvent()
            local r = ReplicatedStorage:FindFirstChild("Remotes")
            local i = r and r:FindFirstChild("Items")
            local t = i and i:FindFirstChild("Twist of Fate")
            local f = t and t:FindFirstChild("Fire")
            if f and f:IsA("RemoteEvent") then return f end
            return nil
        end
        local function ToF_GetGun()
            local c = LocalPlayer.Character
            if not c then return nil end
            local b = c:FindFirstChild("Twist of Fate", true)
            if not b then return nil end
            local ra = b:FindFirstChild("Right Arm")
            if ra then local g = ra:FindFirstChild("gun"); if g then return g end
                local e = ra:FindFirstChild("EmperorGun"); if e then return e end end
            return b
        end
        local function ToF_IsVisible(op, tp, tc)
            local d = tp - op; local dist = d.Magnitude
            if dist < 0.1 then return true end
            local rp = RaycastParams.new(); rp.FilterType = Enum.RaycastFilterType.Exclude
            local ex = {}
            local lc = LocalPlayer.Character
            if lc then table.insert(ex, lc) end
            if tc and tc ~= lc then table.insert(ex, tc) end
            if ToFState.LaserBeam then table.insert(ex, ToFState.LaserBeam) end
            rp.FilterDescendantsInstances = ex
            return workspace:Raycast(op, d.Unit * dist, rp) == nil
        end
        local function ToF_GetSCPs()
            if tick() - ToFState.SCPCacheTimer < 0.5 then return ToFState.SCPCache end
            local nt = {}
            local mf = workspace:FindFirstChild("Map")
            if mf then
                for _, c in pairs(mf:GetDescendants()) do
                    if c:IsA("Model") then
                        local a = c:GetAttributes()
                        if c:GetAttribute("CorpseCreated0492") or next(a) ~= nil then
                            local r = c:FindFirstChild("HumanoidRootPart"); if r then table.insert(nt, r) end
                        end
                    end
                end
            end
            ToFState.SCPCache = nt; ToFState.SCPCacheTimer = tick()
            return nt
        end
        local function ToF_GetTarget()
            local g = ToF_GetGun(); local c = LocalPlayer.Character
            if not (g and c) then return nil,nil,nil,nil end
            local hrp = c:FindFirstChild("HumanoidRootPart")
            if not hrp then return nil,nil,nil,nil end
            local mp = hrp.Position
            local op
            if c:GetAttribute("IsCarried") then op = hrp.Position + (hrp.CFrame.LookVector * 2)
            else
                pcall(function() op = g:IsA("BasePart") and g.Position or (g:FindFirstChildOfClass("BasePart") and g:FindFirstChildOfClass("BasePart").Position) end)
                op = op or Vector3.new(mp.X, mp.Y + 1.5, mp.Z)
            end
            local function predict(t, tc)
                local tp = t.Position
                if VD.TOF2_WallCheck and not ToF_IsVisible(op, tp, tc) then return nil,nil,nil,nil end
                local tv = Vector3.new(0,0,0)
                local rp = tc and (tc:FindFirstChild("HumanoidRootPart") or t)
                if rp then tv = rp.Velocity end
                local dr = tp - op; local d = dr.Magnitude
                if d < 0.1 then return nil,nil,nil,nil end
                if d < 5 then return dr.Unit, g, op, tp end
                local tt = d/400
                local pp = tp + (tv*tt)
                for _=1,2 do local nd = (pp-op).Magnitude; tt = nd/400; pp = tp + (tv*tt) end
                local fd = pp - op
                if fd.Magnitude < 0.1 then return nil,nil,nil,nil end
                return fd.Unit, g, op, pp
            end
            local mode = VD.TOF2_TargetMode or "Killer"
            if mode=="Killer" then
                local bt, bc, bs = nil, nil, math.huge
                for _,p in ipairs(MawwwGetPlayers()) do
                    if p ~= LocalPlayer and TeamIs(p, "Killer") and p.Character then
                        local t = p.Character:FindFirstChild("Torso") or p.Character:FindFirstChild("UpperTorso") or p.Character:FindFirstChild("HumanoidRootPart")
                        if t then local d = (mp-t.Position).Magnitude; if d < bs then bs=d; bt=t; bc=p.Character end end
                    end
                end
                if not bt then return nil,nil,nil,nil end
                return predict(bt, bc)
            elseif mode=="Survivors" then
                local bt, bc, bd = nil, nil, -math.huge
                local cam = workspace.CurrentCamera
                if not cam then return nil,nil,nil,nil end
                local cl = cam.CFrame.LookVector
                for _,p in ipairs(MawwwGetPlayers()) do
                    if p ~= LocalPlayer and TeamIs(p, "Survivor") and p.Character then
                        local t = p.Character:FindFirstChild("Torso") or p.Character:FindFirstChild("UpperTorso") or p.Character:FindFirstChild("HumanoidRootPart")
                        if t then local dt = t.Position - cam.CFrame.Position
                            if dt.Magnitude>0.1 then local dot = cl:Dot(dt.Unit); if dot>0.5 and dot>bd then bd=dot; bt=t; bc=p.Character end end end
                    end
                end
                if not bt then return nil,nil,nil,nil end
                return predict(bt, bc)
            elseif mode=="Zombie" then
                local bp, bd = nil, -math.huge
                local cam = workspace.CurrentCamera
                if not cam then return nil,nil,nil,nil end
                local cl = cam.CFrame.LookVector
                for _,r in ipairs(ToF_GetSCPs()) do
                    if r and r.Parent then local dt = r.Position - cam.CFrame.Position
                        if dt.Magnitude>0.1 then local dot = cl:Dot(dt.Unit); if dot>0.5 and dot>bd then bd=dot; bp=r end end end
                end
                if not bp then return nil,nil,nil,nil end
                return predict(bp, bp.Parent)
            end
            return nil,nil,nil,nil
        end
        local function ToF_UpdateLaser(op, tp)
            if not ToFState.LaserBeam then
                local l = Instance.new("Part"); l.Name="ToFLaser"; l.Anchored=true; l.CanCollide=false; l.CanTouch=false; l.CastShadow=false
                l.Material=Enum.Material.Neon; l.Color=Color3.fromRGB(255,255,255); l.Parent=workspace
                ToFState.LaserBeam = l
            end
            local d = (tp-op).Magnitude
            ToFState.LaserBeam.Size = Vector3.new(0.05,0.05,d)
            ToFState.LaserBeam.CFrame = CFrame.new((op+tp)/2, tp)
            ToFState.LaserBeam.Transparency = 0
        end
        local function ToF_ClearLaser()
            if ToFState.LaserBeam then pcall(function() ToFState.LaserBeam:Destroy() end); ToFState.LaserBeam=nil end
        end
        local function ToF_GetMobileBtn()
            local pg = LocalPlayer:FindFirstChild("PlayerGui")
            local sm = pg and pg:FindFirstChild("Survivor-mob")
            local ct = sm and sm:FindFirstChild("Controls")
            local gm = ct and ct:FindFirstChild("Gui-mob")
            if not gm then return nil end
            for _,n in ipairs({"attack","Attack","shoot","Shoot","fire","Fire"}) do local b = gm:FindFirstChild(n,true); if b and b:IsA("GuiObject") then return b end end
            for _,o in ipairs(gm:GetDescendants()) do if o:IsA("GuiButton") and o.Visible then return o end end
            return gm:IsA("GuiObject") and gm or nil
        end
        local function ToF_IsTouchShoot(input)
            local sb = ToF_GetMobileBtn()
            if not (sb and sb.Visible) then return false end
            local p = input.Position; local ap = sb.AbsolutePosition; local az = sb.AbsoluteSize
            return p.X>=ap.X and p.X<=ap.X+az.X and p.Y>=ap.Y and p.Y<=ap.Y+az.Y
        end
        local function ToF_Shoot()
            if not VD.TOF2_SourceEnabled then return end
            if ToF_IsBlocked() then return end
            local td, g, op, tp = ToF_GetTarget()
            if not (td and g and tp and op) then return end
            local e = ToF_GetEvent()
            if not e then return end
            local fd = tp - op
            if fd.Magnitude < 0.1 then return end
            pcall(function() e:FireServer(g, fd.Unit) end)
        end
        local ToF_ModeButtons = {}
        local ToF_BgColor = Color3.fromRGB(18, 18, 22)
        local ToF_HoverColor = Color3.fromRGB(38, 38, 46)
        local ToF_ModeConfig = { Killer={Color=Color3.fromRGB(255,90,90),Label="KILLER",Hint="K"}, Survivors={Color=Color3.fromRGB(120,200,255),Label="SURVIVOR",Hint="J"}, Zombie={Color=Color3.fromRGB(120,255,150),Label="ZOMBIE",Hint="L"} }
        local function ToF_RefreshButtons()
            for n, b in pairs(ToF_ModeButtons) do
                if b and b.Parent then
                    local isActive = n == (VD.TOF2_TargetMode or "Killer")
                    local cfg = ToF_ModeConfig[n]
                    local ind = b:FindFirstChild("Indicator"); local lb = b:FindFirstChild("ModeLabel"); local hn = b:FindFirstChild("HintLabel"); local st = b:FindFirstChildOfClass("UIStroke")
                    if isActive then
                        TweenService:Create(b, TweenInfo.new(0.25), { BackgroundColor3 = Color3.fromRGB(32, 32, 40) }):Play()
                        if ind then TweenService:Create(ind, TweenInfo.new(0.25), { Size = UDim2.new(0, 3, 0.6, 0), BackgroundColor3 = cfg.Color, BackgroundTransparency = 0 }):Play() end
                        if lb then TweenService:Create(lb, TweenInfo.new(0.25), { TextColor3 = Color3.fromRGB(255, 255, 255) }):Play() end
                        if hn then TweenService:Create(hn, TweenInfo.new(0.25), { TextColor3 = cfg.Color, TextTransparency = 0 }):Play() end
                        if st then TweenService:Create(st, TweenInfo.new(0.25), { Color = Color3.fromRGB(80, 80, 92), Transparency = 0.2 }):Play() end
                    else
                        TweenService:Create(b, TweenInfo.new(0.25), { BackgroundColor3 = Color3.fromRGB(24, 24, 30) }):Play()
                        if ind then TweenService:Create(ind, TweenInfo.new(0.25), { Size = UDim2.new(0, 3, 0, 0), BackgroundTransparency = 1 }):Play() end
                        if lb then TweenService:Create(lb, TweenInfo.new(0.25), { TextColor3 = Color3.fromRGB(140, 140, 152) }):Play() end
                        if hn then TweenService:Create(hn, TweenInfo.new(0.25), { TextColor3 = Color3.fromRGB(90, 90, 100), TextTransparency = 0.3 }):Play() end
                        if st then TweenService:Create(st, TweenInfo.new(0.25), { Color = Color3.fromRGB(45, 45, 55), Transparency = 0.5 }):Play() end
                    end
                end
            end
        end
        local function ToF_SetTargetMode(mode, shouldNotify)
            if mode ~= "Killer" and mode ~= "Survivors" and mode ~= "Zombie" then return end
            VD.TOF2_TargetMode = mode
            ToF_RefreshButtons()
            if shouldNotify then pcall(function() notify("ToF Target", mode, 1) end) end
        end
        local function ToF_DestroyUI()
            if ToFState.TargetGui then pcall(function() ToFState.TargetGui:Destroy() end); ToFState.TargetGui = nil end
            ToF_ModeButtons = {}
        end
        local function ToF_CreateUI() end
        local function ToF_StartConn()
            if ToFState.Connection then return end
            ToFState.Connection = MAWWW_Conn(RunService.Heartbeat, function()
                if ToF_IsBlocked() then ToFState.IsAiming = false; if ToFState.TouchInput then ToFState.TouchInput = nil end; if ToFState.LaserBeam then ToFState.LaserBeam.Transparency = 1 end; return end
                if not VD.TOF2_SourceEnabled or not ToFState.IsAiming then if ToFState.LaserBeam then ToFState.LaserBeam.Transparency = 1 end; return end
                local _, _, op, tp = ToF_GetTarget()
                if op and tp then
                    pcall(function()
                        local c = LocalPlayer.Character
                        local hrp = c and c:FindFirstChild("HumanoidRootPart")
                        if hrp and not c:GetAttribute("IsCarried") then hrp.CFrame = CFrame.new(hrp.Position, Vector3.new(tp.X, hrp.Position.Y, tp.Z)) end
                    end)
                    if VD.TOF2_ShowLaser then ToF_UpdateLaser(op, tp)
                    elseif ToFState.LaserBeam then ToFState.LaserBeam.Transparency = 1 end
                elseif ToFState.LaserBeam then ToFState.LaserBeam.Transparency = 1 end
            end)
        end
        local function ToF_StopConn()
            if ToFState.Connection then pcall(function() ToFState.Connection:Disconnect() end); ToFState.Connection = nil end
            ToFState.IsAiming = false; ToF_ClearLaser()
        end
        local SetToFSilentAim
        local function ToF_EnsureInputs()
            if not ToFState.InputBegan then
                ToFState.InputBegan = MAWWW_Conn(UserInputService.InputBegan, function(inp, gp)
                    if gp then return end
                    local k = ToFKeyCodes[VD.TOF2_Key or "None"]
                    if k and inp.UserInputType == Enum.UserInputType.Keyboard and inp.KeyCode == k then SetToFSilentAim(not VD.TOF2_SourceEnabled); return end
                    if not VD.TOF2_SourceEnabled then return end
                    if inp.UserInputType == Enum.UserInputType.MouseButton1 or (inp.UserInputType == Enum.UserInputType.Touch and ToF_IsTouchShoot(inp)) then
                        if ToF_IsBlocked() then ToFState.IsAiming = false; return end
                        ToFState.IsAiming = true
                        if inp.UserInputType == Enum.UserInputType.Touch then ToFState.TouchInput = inp end
                        return
                    end
                    if inp.UserInputType == Enum.UserInputType.Keyboard then
                        if inp.KeyCode == Enum.KeyCode.K then ToF_SetTargetMode("Killer", true)
                        elseif inp.KeyCode == Enum.KeyCode.J then ToF_SetTargetMode("Survivors", true)
                        elseif inp.KeyCode == Enum.KeyCode.L then ToF_SetTargetMode("Zombie", true) end
                    end
                end)
            end
            if not ToFState.InputEnded then
                ToFState.InputEnded = MAWWW_Conn(UserInputService.InputEnded, function(inp)
                    if inp.UserInputType == Enum.UserInputType.MouseButton1 or (inp.UserInputType == Enum.UserInputType.Touch and inp == ToFState.TouchInput) then
                        local wa = ToFState.IsAiming
                        ToFState.IsAiming = false
                        if inp == ToFState.TouchInput then ToFState.TouchInput = nil end
                        if ToFState.LaserBeam then ToFState.LaserBeam.Transparency = 1 end
                        if wa then if ToF_IsBlocked() then return end; ToF_Shoot() end
                    end
                end)
            end
        end
        SetToFSilentAim = function(en)
            if MAWWW_PREMIUM_FEATURES_LOCKED and en == true then
                VD.TOF2_SourceEnabled = false
                ToF_DestroyUI()
                ToF_StopConn()
                notify("Khusus Premium", "Silent Pistol hanya tersedia di Mawww Hub Premium.", 3)
                return false
            end
            VD.TOF2_SourceEnabled = false
            ToF_EnsureInputs()
            if VD.TOF2_SourceEnabled then ToF_CreateUI(); ToF_StartConn()
            else ToF_DestroyUI(); ToF_StopConn() end
        end
        ToF_EnsureInputs()
        return {
            State = ToFState,
            SetEnabled = SetToFSilentAim,
            SetTargetMode = ToF_SetTargetMode,
            Stop = function() SetToFSilentAim(false) end,
            ClearLaser = ToF_ClearLaser,
        }
end)()

-- One shared floating target selector for ToF V1-V5. Only one panel is shown at a
-- time so panels cannot overlap or hide the version that was just enabled.
local function MAWWW_NormalizeFloatingToFMode(value)
    local mode = string.upper(tostring(value or "KILLER")):gsub("%s+", "")
    if mode == "SURVIVOR" or mode == "SURVIVORS" then return "SURVIVOR" end
    if mode == "ZOMBIE" or mode == "ZOMBIES" then return "ZOMBIE" end
    if mode == "KILLER" or mode == "SLASHER" then return "KILLER" end
    return mode
end

MAWWW_RefreshFloatingToFTargetSelector = function(key)
    local data = MAWWW_FloatingToFTargetSelectorUIs[key]
    if not data or not data.Gui or not data.Gui.Parent then return end

    -- Re-apply the image to the PANEL background (not just the small row icons).
    -- Doing this on refresh also repairs UI instances whose image was overwritten.
    if data.Background and data.Background.Parent then
        pcall(function()
            data.Background.Visible = true
            data.Background.BackgroundTransparency = 1
            data.Background.Size = UDim2.fromScale(1, 1)
            data.Background.Position = UDim2.fromScale(0, 0)
            data.Background.ZIndex = (data.Frame and data.Frame.ZIndex or 150) + 1
        end)
        if data.Background.Image ~= MAWWW_TOF_TARGET_MODE_IMAGE_ID
            and data.Background.Image ~= MAWWW_TOF_TARGET_MODE_THUMBNAIL_ID then
            MAWWW_ApplyToFTargetImage(data.Background, Enum.ScaleType.Crop, true)
        end
    end
    if data.Tint and data.Tint.Parent then
        pcall(function()
            data.Tint.BackgroundColor3 = (Theme and Theme.Background) or Color3.fromRGB(10, 10, 16)
            data.Tint.BackgroundTransparency = 0.84
            data.Tint.ZIndex = (data.Frame and data.Frame.ZIndex or 150) + 2
        end)
    end
    if data.TitleLabel and data.TitleLabel.Parent then
        pcall(function() data.TitleLabel.Text = "SILENT AIM" end)
    end
    if data.SubtitleLabel and data.SubtitleLabel.Parent then
        pcall(function() data.SubtitleLabel.Text = "Twist of Fate" end)
    end

    local ok, current = pcall(data.GetMode)
    if not ok then current = nil end
    local normalizedCurrent = MAWWW_NormalizeFloatingToFMode(current)
    if data.SelectedMode ~= nil then
        local selected = MAWWW_NormalizeFloatingToFMode(data.SelectedMode)
        if selected == normalizedCurrent then
            data.SelectedMode = nil
        elseif data.SelectedModeExpires and os.clock() >= data.SelectedModeExpires then
            data.SelectedMode = nil
        else
            normalizedCurrent = selected
        end
    end
    for value, button in pairs(data.ModeButtons) do
        if button and button.Parent then
            local active = MAWWW_NormalizeFloatingToFMode(value) == normalizedCurrent
            local modeKey = MAWWW_NormalizeFloatingToFMode(value)
            local accent = modeKey == "KILLER" and Color3.fromRGB(255, 92, 104)
                or modeKey == "SURVIVOR" and Color3.fromRGB(121, 197, 255)
                or modeKey == "ZOMBIE" and Color3.fromRGB(126, 255, 157)
                or Color3.fromRGB(155, 170, 255)
            button.BackgroundTransparency = active and 0.12 or 0.24
            button.BackgroundColor3 = active and Color3.fromRGB(27, 28, 37) or Color3.fromRGB(18, 19, 26)
            local label = button:FindFirstChild("ModeLabel")
            if label and label:IsA("TextLabel") then
                label.TextColor3 = active and Color3.fromRGB(255, 250, 255) or Color3.fromRGB(160, 162, 176)
            end
            local indicator = button:FindFirstChild("Indicator")
            if indicator then
                indicator.BackgroundColor3 = accent
                indicator.BackgroundTransparency = active and 0 or 1
                indicator.Size = active and UDim2.new(0, 3, 0, 24) or UDim2.new(0, 3, 0, 0)
            end
            local dot = button:FindFirstChild("ModeDot")
            if dot then dot.BackgroundColor3 = accent end
            local hint = button:FindFirstChild("KeyHint")
            if hint then
                hint.TextColor3 = active and accent or Color3.fromRGB(105, 107, 121)
                hint.BackgroundTransparency = active and 0.08 or 0.26
            end
        end
    end
end

MAWWW_DestroyFloatingToFTargetSelector = function(key)
    local data = MAWWW_FloatingToFTargetSelectorUIs[key]
    if not data then return end
    for _, connection in ipairs(data.Connections or {}) do
        pcall(function() connection:Disconnect() end)
    end
    if data.Gui then pcall(function() data.Gui:Destroy() end) end
    MAWWW_FloatingToFTargetSelectorUIs[key] = nil
end

MAWWW_CreateFloatingToFTargetSelector = function(key, title, modeOptions, getMode, setMode, slot)
    local current = MAWWW_FloatingToFTargetSelectorUIs[key]
    if current and current.Gui and current.Gui.Parent then
        current.Gui.Enabled = true
        if current.Frame then current.Frame.Visible = true end
        current.GetMode = getMode or current.GetMode
        current.SetMode = setMode or current.SetMode
        current.Title = title or current.Title
        if current.TitleLabel then current.TitleLabel.Text = "SILENT AIM" end
        if current.SubtitleLabel then current.SubtitleLabel.Text = "Twist of Fate" end
        if current.Background then
            current.Background.Visible = true
            if current.Background.Image ~= MAWWW_TOF_TARGET_MODE_IMAGE_ID
                and current.Background.Image ~= MAWWW_TOF_TARGET_MODE_THUMBNAIL_ID then
                MAWWW_ApplyToFTargetImage(current.Background, Enum.ScaleType.Crop, true)
            end
            current.Background.ImageTransparency = 0
        end
        MAWWW_RefreshFloatingToFTargetSelector(key)
        return
    end

    -- Exactly one active floating ToF selector prevents overlap and makes the
    -- visible panel always correspond to the feature most recently switched ON.
    local staleKeys = {}
    for otherKey, data in pairs(MAWWW_FloatingToFTargetSelectorUIs) do
        if otherKey ~= key and data then table.insert(staleKeys, otherKey) end
    end
    for _, otherKey in ipairs(staleKeys) do
        MAWWW_DestroyFloatingToFTargetSelector(otherKey)
    end

    local parent = nil
    pcall(function() parent = MAWWW_GetSafeGuiParent() end)
    if not parent then parent = PlayerGui end
    if not parent then return end

    local gui = Instance.new("ScreenGui")
    gui.Name = "ToFTargetSelector" .. tostring(key)
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    gui.DisplayOrder = 1000001
    gui.Parent = parent

    -- Compact dimensions: a little smaller for mobile while keeping buttons easy to tap.
    local headerHeight = 50
    local rowHeight = 39
    local rowGap = 5
    local footerHeight = 20
    local rowsHeight = (#modeOptions * rowHeight) + (math.max(0, #modeOptions - 1) * rowGap)
    local panelHeight = headerHeight + 6 + rowsHeight + footerHeight + 8
    local frame = Instance.new("Frame")
    frame.Name = "Main"
    frame.AnchorPoint = Vector2.new(0, 0)
    local camera = Workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize or Vector2.new(800, 600)
    local panelWidth = math.max(150, math.min(310, viewport.X - 16))
    frame.Size = UDim2.fromOffset(panelWidth, panelHeight)
    local initialX = math.clamp(math.floor((viewport.X - panelWidth) / 2), 4, math.max(4, viewport.X - panelWidth - 4))
    local initialY = math.clamp(math.floor(viewport.Y * 0.22), 4, math.max(4, viewport.Y - panelHeight - 4))
    frame.Position = UDim2.fromOffset(initialX, initialY)
    frame.BackgroundColor3 = Color3.fromRGB(13, 13, 18)
    frame.BackgroundTransparency = 1
    frame.BorderSizePixel = 0
    frame.Active = true
    frame.ClipsDescendants = true
    frame.ZIndex = 150
    frame.Parent = gui
    pcall(function() Corner(frame, 9) end)

    local bg = Instance.new("ImageLabel")
    bg.Name = "TargetModeBackground"
    bg.Size = UDim2.fromScale(1, 1)
    bg.Position = UDim2.fromScale(0, 0)
    bg.BackgroundTransparency = 1
    bg.Image = MAWWW_TOF_TARGET_MODE_THUMBNAIL_ID
    bg.ImageTransparency = 0
    bg.ScaleType = Enum.ScaleType.Crop
    bg.ZIndex = 151
    bg.Parent = frame
    pcall(function() Corner(bg, 9) end)
    MAWWW_ApplyToFTargetImage(bg, Enum.ScaleType.Crop, true)

    local tint = Instance.new("Frame")
    tint.Name = "Tint"
    tint.Size = UDim2.fromScale(1, 1)
    tint.BackgroundColor3 = Color3.fromRGB(151, 178, 226)
    tint.BackgroundTransparency = 0.64
    tint.BorderSizePixel = 0
    tint.ZIndex = 152
    tint.Parent = frame
    pcall(function() Corner(tint, 9) end)

    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(132, 166, 255)
    stroke.Thickness = 1.4
    stroke.Transparency = 0.12
    stroke.Parent = frame

    local header = Instance.new("Frame")
    header.Name = "Header"
    header.Size = UDim2.new(1, 0, 0, headerHeight)
    header.BackgroundColor3 = Color3.fromRGB(20, 24, 36)
    header.BackgroundTransparency = 0.22
    header.BorderSizePixel = 0
    header.Active = true
    header.ZIndex = 153
    header.Parent = frame

    -- Drag zone excludes both LIVE badge and minimize button.
    local dragArea = Instance.new("Frame")
    dragArea.Name = "DragArea"
    dragArea.Size = UDim2.new(1, -88, 1, 0)
    dragArea.BackgroundTransparency = 1
    dragArea.Active = true
    dragArea.ZIndex = 154
    dragArea.Parent = header

    local logo = Instance.new("ImageLabel")
    logo.Name = "Logo"
    logo.Size = UDim2.fromOffset(32, 32)
    logo.Position = UDim2.fromOffset(8, 9)
    logo.BackgroundTransparency = 1
    logo.Image = MAWWW_TOF_TARGET_MODE_THUMBNAIL_ID
    logo.ScaleType = Enum.ScaleType.Crop
    logo.ZIndex = 156
    logo.Parent = header
    pcall(function() Corner(logo, 18) end)
    MAWWW_ApplyToFTargetImage(logo, Enum.ScaleType.Crop, true)

    local headerLabel = Instance.new("TextLabel")
    headerLabel.Name = "Title"
    headerLabel.Size = UDim2.new(1, -150, 0, 20)
    headerLabel.Position = UDim2.fromOffset(46, 4)
    headerLabel.BackgroundTransparency = 1
    headerLabel.Text = "SILENT AIM"
    headerLabel.TextColor3 = Color3.fromRGB(250, 249, 255)
    headerLabel.Font = Enum.Font.GothamBold
    headerLabel.TextSize = 11
    headerLabel.TextXAlignment = Enum.TextXAlignment.Left
    headerLabel.ZIndex = 156
    headerLabel.Parent = header

    local subtitleLabel = Instance.new("TextLabel")
    subtitleLabel.Name = "Subtitle"
    subtitleLabel.Size = UDim2.new(1, -150, 0, 16)
    subtitleLabel.Position = UDim2.fromOffset(46, 24)
    subtitleLabel.BackgroundTransparency = 1
    subtitleLabel.Text = "Twist of Fate"
    subtitleLabel.TextColor3 = Color3.fromRGB(211, 216, 236)
    subtitleLabel.Font = Enum.Font.Gotham
    subtitleLabel.TextSize = 9
    subtitleLabel.TextXAlignment = Enum.TextXAlignment.Left
    subtitleLabel.ZIndex = 156
    subtitleLabel.Parent = header

    local livePill = Instance.new("Frame")
    livePill.Name = "LivePill"
    livePill.Size = UDim2.fromOffset(56, 22)
    livePill.Position = UDim2.new(1, -88, 0, 14)
    livePill.BackgroundColor3 = Color3.fromRGB(10, 12, 18)
    livePill.BackgroundTransparency = 0.14
    livePill.BorderSizePixel = 0
    livePill.ZIndex = 156
    livePill.Parent = header
    pcall(function() Corner(livePill, 13) end)

    local liveDot = Instance.new("Frame")
    liveDot.Name = "LiveDot"
    liveDot.Size = UDim2.fromOffset(7, 7)
    liveDot.Position = UDim2.fromOffset(7, 7)
    liveDot.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    liveDot.BorderSizePixel = 0
    liveDot.ZIndex = 157
    liveDot.Parent = livePill
    pcall(function() Corner(liveDot, 4) end)

    local liveLabel = Instance.new("TextLabel")
    liveLabel.Name = "LiveLabel"
    liveLabel.Size = UDim2.new(1, -20, 1, 0)
    liveLabel.Position = UDim2.fromOffset(17, 0)
    liveLabel.BackgroundTransparency = 1
    liveLabel.Text = "LIVE"
    liveLabel.TextColor3 = Color3.fromRGB(245, 246, 255)
    liveLabel.Font = Enum.Font.GothamBold
    liveLabel.TextSize = 9
    liveLabel.TextXAlignment = Enum.TextXAlignment.Left
    liveLabel.ZIndex = 157
    liveLabel.Parent = livePill

    local minimizeButton = Instance.new("TextButton")
    minimizeButton.Name = "MinimizeButton"
    minimizeButton.Size = UDim2.fromOffset(26, headerHeight)
    minimizeButton.Position = UDim2.new(1, -28, 0, 0)
    minimizeButton.BackgroundTransparency = 1
    minimizeButton.Text = "−"
    minimizeButton.TextColor3 = Color3.fromRGB(235, 235, 245)
    minimizeButton.Font = Enum.Font.GothamBold
    minimizeButton.TextSize = 16
    minimizeButton.AutoButtonColor = false
    minimizeButton.Active = true
    minimizeButton.Selectable = true
    minimizeButton.ZIndex = 158
    minimizeButton.Parent = header

    local container = Instance.new("Frame")
    container.Name = "ModeButtons"
    container.Size = UDim2.new(1, -12, 0, rowsHeight)
    container.Position = UDim2.fromOffset(6, headerHeight + 6)
    container.BackgroundTransparency = 1
    container.ZIndex = 153
    container.Parent = frame

    local list = Instance.new("UIListLayout")
    list.FillDirection = Enum.FillDirection.Vertical
    list.SortOrder = Enum.SortOrder.LayoutOrder
    list.Padding = UDim.new(0, rowGap)
    list.Parent = container

    local hintLabel = Instance.new("TextLabel")
    hintLabel.Name = "HotkeyHint"
    hintLabel.Size = UDim2.new(1, -10, 0, footerHeight)
    hintLabel.Position = UDim2.fromOffset(5, container.Position.Y.Offset + rowsHeight + 2)
    hintLabel.BackgroundTransparency = 1
    local hasZombie = false
    for _, option in ipairs(modeOptions) do
        if tostring(option.Value) == "Zombie" then hasZombie = true break end
    end
    hintLabel.Text = hasZombie and "Drag header · K / J / L to swap" or "Drag header · K / J to swap"
    hintLabel.TextColor3 = Color3.fromRGB(222, 225, 242)
    hintLabel.Font = Enum.Font.Gotham
    hintLabel.TextSize = 9
    hintLabel.TextXAlignment = Enum.TextXAlignment.Center
    hintLabel.ZIndex = 156
    hintLabel.Parent = frame

    local data = {
        Gui = gui,
        Frame = frame,
        Background = bg,
        Tint = tint,
        TitleLabel = headerLabel,
        SubtitleLabel = subtitleLabel,
        LivePill = livePill,
        MinimizeButton = minimizeButton,
        ModeContainer = container,
        Title = title,
        ExpandedHeight = panelHeight,
        Minimized = false,
        ModeOptions = modeOptions,
        ModeButtons = {},
        Connections = {},
        GetMode = getMode,
        SetMode = setMode,
        SelectedMode = nil,
        Key = tostring(key),
    }
    MAWWW_FloatingToFTargetSelectorUIs[key] = data

    -- MAWWW_ApplyToFTargetImage already preloads the thumbnail/direct URI and
    -- keeps the chosen working source instead of forcing the direct URI every frame.

    local function clampFloatingPanel()
        if not frame.Parent then return end
        local cameraNow = Workspace.CurrentCamera
        local vp = cameraNow and cameraNow.ViewportSize or Vector2.new(800, 600)
        local width = math.min(frame.AbsoluteSize.X > 0 and frame.AbsoluteSize.X or panelWidth, math.max(150, vp.X - 8))
        local height = data.Minimized and headerHeight or panelHeight
        local x = math.clamp(frame.Position.X.Offset, 4, math.max(4, vp.X - width - 4))
        local y = math.clamp(frame.Position.Y.Offset, 4, math.max(4, vp.Y - height - 4))
        if frame.Size.X.Offset ~= width or frame.Size.Y.Offset ~= height then
            frame.Size = UDim2.fromOffset(width, height)
        end
        if frame.Position.X.Offset ~= x or frame.Position.Y.Offset ~= y then
            frame.Position = UDim2.fromOffset(math.floor(x), math.floor(y))
        end
    end
    table.insert(data.Connections, frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
        task.defer(clampFloatingPanel)
    end))
    table.insert(data.Connections, minimizeButton.Activated:Connect(function()
        data.Minimized = not data.Minimized
        minimizeButton.Text = data.Minimized and "+" or "-"
        container.Visible = not data.Minimized
        if hintLabel then hintLabel.Visible = not data.Minimized end
        clampFloatingPanel()
        task.defer(clampFloatingPanel)
    end))
    table.insert(data.Connections, MAWWW_Conn(RunService.RenderStepped, function()
        -- Lightweight recovery guard: preserve the requested background image if another UI patch overwrites it.
        if data.Background and data.Background.Parent then
            local backgroundImage = data.Background.Image
            if (backgroundImage ~= MAWWW_TOF_TARGET_MODE_IMAGE_ID
                and backgroundImage ~= MAWWW_TOF_TARGET_MODE_THUMBNAIL_ID)
                or not data.Background.Visible then
                MAWWW_ApplyToFTargetImage(data.Background, Enum.ScaleType.Crop, true)
            end
            data.Background.ImageTransparency = 0
        end
        local cameraNow = Workspace.CurrentCamera
        if cameraNow and data.LastViewport ~= cameraNow.ViewportSize then
            data.LastViewport = cameraNow.ViewportSize
            clampFloatingPanel()
        end
    end))

    local modeAccentColors = {
        Killer = Color3.fromRGB(255, 92, 104),
        Survivors = Color3.fromRGB(121, 197, 255),
        Zombie = Color3.fromRGB(126, 255, 157),
    }
    local modeHotkeys = { Killer = "K", Survivors = "J", Zombie = "L" }

    for index, option in ipairs(modeOptions) do
        local value = tostring(option.Value)
        local normalizedValue = MAWWW_NormalizeFloatingToFMode(value)
        local accent = modeAccentColors[normalizedValue] or Color3.fromRGB(155, 170, 255)
        local button = Instance.new("TextButton")
        button.Name = "TargetMode_" .. value:gsub("[^%w]", "")
        button.Size = UDim2.new(1, 0, 0, rowHeight)
        button.BackgroundColor3 = Color3.fromRGB(18, 19, 26)
        button.BackgroundTransparency = 0.18
        button.BorderSizePixel = 0
        button.AutoButtonColor = false
        button.Text = ""
        button.LayoutOrder = index
        button.ZIndex = 153
        button.Parent = container
        button.Active = true
        button.Selectable = true
        pcall(function() button.Interactable = true end)
        pcall(function() Corner(button, 12) end)

        local indicator = Instance.new("Frame")
        indicator.Name = "Indicator"
        indicator.Size = UDim2.new(0, 3, 0, 0)
        indicator.Position = UDim2.fromOffset(6, 6)
        indicator.BackgroundColor3 = accent
        indicator.BackgroundTransparency = 1
        indicator.BorderSizePixel = 0
        indicator.ZIndex = 154
        indicator.Parent = button
        pcall(function() Corner(indicator, 2) end)

        local dot = Instance.new("Frame")
        dot.Name = "ModeDot"
        dot.Size = UDim2.fromOffset(9, 9)
        dot.Position = UDim2.new(0, 18, 0.5, -4)
        dot.BackgroundColor3 = accent
        dot.BackgroundTransparency = 0
        dot.BorderSizePixel = 0
        dot.ZIndex = 155
        dot.Parent = button
        pcall(function() Corner(dot, 6) end)

        local label = Instance.new("TextLabel")
        label.Name = "ModeLabel"
        label.Size = UDim2.new(1, -82, 1, 0)
        label.Position = UDim2.fromOffset(34, 0)
        label.BackgroundTransparency = 1
        label.Active = false
        label.Selectable = false
        label.Text = tostring(option.Label or value)
        label.TextColor3 = Color3.fromRGB(220, 220, 230)
        label.Font = Enum.Font.GothamBold
        label.TextSize = 12
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.ZIndex = 156
        label.Parent = button

        local keyHint = Instance.new("TextLabel")
        keyHint.Name = "KeyHint"
        keyHint.Size = UDim2.fromOffset(28, 25)
        keyHint.Position = UDim2.new(1, -34, 0.5, -12.5)
        keyHint.BackgroundColor3 = Color3.fromRGB(37, 38, 48)
        keyHint.BackgroundTransparency = 0.22
        keyHint.BorderSizePixel = 0
        keyHint.Text = tostring(option.Hotkey or modeHotkeys[normalizedValue] or "")
        keyHint.TextColor3 = Color3.fromRGB(165, 167, 181)
        keyHint.Font = Enum.Font.GothamBold
        keyHint.TextSize = 10
        keyHint.ZIndex = 156
        keyHint.Parent = button
        pcall(function() Corner(keyHint, 7) end)

        local activatedConnection = button.Activated:Connect(function()
            local modeToApply = value
            data.SelectedMode = modeToApply
            data.SelectedModeExpires = os.clock() + 0.8
            local ok, err = pcall(function()
                if type(data.SetMode) == "function" then
                    data.SetMode(modeToApply)
                end
            end)
            if not ok then
                warn("[Mawww Hub] ToF " .. tostring(key) .. " target selector:", err)
            end

            -- Keep the UI flag and the active targeting engine in sync even if a
            -- source-specific setter only updates an internal config object.
            pcall(function()
                if key == "V2" then
                    VD.TOF2_TargetMode = modeToApply
                elseif key == "V4" then
                    local canonical = MAWWW_NormalizeFloatingToFMode(modeToApply)
                    VD.PistolTargetMode = canonical == "SURVIVOR" and "SURVIVOR" or "KILLER"
                elseif key == "V5" then
                    VD.PistolV5TargetMode = modeToApply
                end
            end)

            MAWWW_RefreshFloatingToFTargetSelector(key)
            task.defer(function() MAWWW_RefreshFloatingToFTargetSelector(key) end)
            task.delay(0.08, function() MAWWW_RefreshFloatingToFTargetSelector(key) end)
            task.delay(0.25, function() MAWWW_RefreshFloatingToFTargetSelector(key) end)
            task.delay(0.85, function()
                if MAWWW_FloatingToFTargetSelectorUIs[key] == data then
                    MAWWW_RefreshFloatingToFTargetSelector(key)
                end
            end)
        end)
        table.insert(data.Connections, activatedConnection)
        data.ModeButtons[value] = button
    end

    -- K/J/L shortcuts match the on-screen key hints; unsupported modes are ignored for V4.
    table.insert(data.Connections, MAWWW_Conn(UserInputService.InputBegan, function(input, gameProcessed)
        if gameProcessed or input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        local keyToMode = { K = "Killer", J = "Survivors", L = "Zombie" }
        local modeToApply = keyToMode[input.KeyCode.Name]
        if not modeToApply or not data.ModeButtons[modeToApply] then return end
        local ok, err = pcall(function()
            if type(data.SetMode) == "function" then data.SetMode(modeToApply) end
        end)
        if not ok then warn("[Mawww Hub] ToF " .. tostring(key) .. " target hotkey:", err) end
        data.SelectedMode = modeToApply
        data.SelectedModeExpires = os.clock() + 0.8
        pcall(function()
            if key == "V2" then
                VD.TOF2_TargetMode = modeToApply
            elseif key == "V4" then
                local canonical = MAWWW_NormalizeFloatingToFMode(modeToApply)
                VD.PistolTargetMode = canonical == "SURVIVOR" and "SURVIVOR" or "KILLER"
            elseif key == "V5" then
                VD.PistolV5TargetMode = modeToApply
            end
        end)
        MAWWW_RefreshFloatingToFTargetSelector(key)
    end))

    -- Drag from the title strip only; use the same screen-space coordinate system throughout.
    local drag = { Active = false, Mode = nil, Input = nil, Start = nil, StartPos = nil }
    table.insert(data.Connections, dragArea.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            drag.Active, drag.Mode, drag.Input = true, "Mouse", nil
            drag.Start = input.Position
            drag.StartPos = frame.Position
        elseif input.UserInputType == Enum.UserInputType.Touch then
            drag.Active, drag.Mode, drag.Input = true, "Touch", input
            drag.Start = input.Position
            drag.StartPos = frame.Position
        end
    end))
    table.insert(data.Connections, MAWWW_Conn(UserInputService.InputChanged, function(input)
        if not drag.Active or not frame.Parent then return end
        local shouldMove = (drag.Mode == "Mouse" and input.UserInputType == Enum.UserInputType.MouseMovement)
            or (drag.Mode == "Touch" and input == drag.Input)
        if not shouldMove then return end
        local delta = input.Position - drag.Start
        local camera = Workspace.CurrentCamera
        local vp = camera and camera.ViewportSize or Vector2.new(800, 600)
        local maxX = math.max(4, vp.X - frame.AbsoluteSize.X - 4)
        local maxY = math.max(4, vp.Y - frame.AbsoluteSize.Y - 4)
        local x = math.clamp(drag.StartPos.X.Offset + delta.X, 4, maxX)
        local y = math.clamp(drag.StartPos.Y.Offset + delta.Y, 4, maxY)
        frame.Position = UDim2.fromOffset(math.floor(x), math.floor(y))
    end))
    table.insert(data.Connections, MAWWW_Conn(UserInputService.InputEnded, function(input)
        if not drag.Active then return end
        if (drag.Mode == "Mouse" and input.UserInputType == Enum.UserInputType.MouseButton1)
            or (drag.Mode == "Touch" and input == drag.Input) then
            drag.Active, drag.Mode, drag.Input = false, nil, nil
        end
    end))

    MAWWW_RefreshFloatingToFTargetSelector(key)
end

