TOFV3Module = {}
do
    local okModule, moduleResult = pcall(function()
        return (function()
pcall(function()
    local oldState = MAWWW_ToFV3State
    if oldState then
        for _, key in ipairs({"Connection", "DragConnection", "InputBegan", "InputEnded"}) do
            local conn = oldState[key]
            if conn and type(conn.Disconnect) == "function" then
                pcall(function() conn:Disconnect() end)
            end
            oldState[key] = nil
        end
        if oldState.LaserBeam and oldState.LaserBeam.Parent then
            pcall(function() oldState.LaserBeam:Destroy() end)
        end
        if oldState.TargetGui and oldState.TargetGui.Parent then
            pcall(function() oldState.TargetGui:Destroy() end)
        end
    end
end)

