--========================================================--
-- SILENT PISTOL / TOF V4 — engine replaced from supplied "silent aim pistol.txt"
-- Existing Tabs.AimTOFV4 panel is retained; no second UI/window is created.
--========================================================--
do
    -- Disable a previous V4 instance before installing this source replacement.
    pcall(function()
        local env = getgenv()
        local oldConfig = env.MAWWW_SilentPistolV4Config
        if type(oldConfig) == "table" then
            oldConfig.Aim_Silent = false
            oldConfig.Flash_Silent = false
            oldConfig.LockAim = false
        end
        if type(env.MAWWW_SilentPistolV4SetEnabled) == "function" then
            env.MAWWW_SilentPistolV4SetEnabled(false)
        end
    end)
    local V4Players = game:GetService("Players")
    local V4LocalPlayer = V4Players.LocalPlayer
    local V4UserInputService = game:GetService("UserInputService")
    local V4RunService = game:GetService("RunService")
    local V4Workspace = game:GetService("Workspace")
    local V4Camera = V4Workspace.CurrentCamera
    local V4ReplicatedStorage = game:GetService("ReplicatedStorage")

    local function V4IsDowned(char)
        if not char then return false end
        return char:GetAttribute("Knocked") == true
            or char:GetAttribute("IsHooked") == true
            or char:GetAttribute("IsCarried") == true
            or char:GetAttribute("HookProgressDepleting") == true
    end

    local function V4HasRole(player, role)
        if not player or player == V4LocalPlayer then return false end
        local teamName = string.lower(tostring(player.Team and player.Team.Name or ""))
        local roleAttr = string.lower(tostring(player:GetAttribute("Role") or (player.Character and player.Character:GetAttribute("Role")) or ""))
        local isKillerAttr = player:GetAttribute("IsKiller")
        if role == "Killer" then
            return string.find(teamName, "killer", 1, true) ~= nil or roleAttr == "killer" or isKillerAttr == true
        end
        if role == "Survivor" then
            return string.find(teamName, "survivor", 1, true) ~= nil or roleAttr == "survivor" or isKillerAttr == false
        end
        return false
    end

    local targetMode = tostring(VD.PistolTargetMode or "KILLER"):upper()
    if targetMode ~= "KILLER" and targetMode ~= "SURVIVOR" then targetMode = "KILLER" end
    VD.PistolTargetMode = targetMode

    local AimConfig = {
        Aim_Silent = VD.PistolEnabled == true,
        Pistol_BlockKnocked = VD.PistolBlockKnocked ~= false,
        Flash_Silent = VD.PistolV4FlashSilentAim == true,
        Flash_YOffset = tonumber(VD.FlashAimYOffset) or 8,
        LockAim = VD.PistolLockAim == true,
        Pistol_Target = targetMode == "SURVIVOR" and "Survivor" or "Killer",
        Pistol_FOVMode = VD.PistolFOVMode == true,
        Pistol_ShowFOV = VD.PistolShowFOV == true,
        Pistol_FOV = tonumber(VD.PistolFOV) or 180,
        AIM_TargetPart = tostring(VD.PistolAimPart or "Torso"),
        HideSilentLaser = VD.PistolLaser == false,
    }

    local isChargingPistol = false
    local lockedPistolTarget = nil
    local currentTouchPistolInput = nil
    local pistolLaser = nil
    local pistolFOVCircle = nil
    local isAimingFlash = false

    local function V4GetTargetPart(character)
        if not character then return nil end
        local part = AimConfig.AIM_TargetPart
        if part == "Head" then return character:FindFirstChild("Head") end
        if part == "Root" or part == "HumanoidRootPart" then
            return character:FindFirstChild("HumanoidRootPart")
        end
        return character:FindFirstChild("Torso")
            or character:FindFirstChild("UpperTorso")
            or character:FindFirstChild("HumanoidRootPart")
    end

    local function V4GetPistolTarget()
        local myChar = V4LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then return nil end
        if AimConfig.Pistol_BlockKnocked and V4IsDowned(myChar) then return nil end

        local camera = V4Workspace.CurrentCamera or V4Camera
        if not camera then return nil end
        local mouseLocation = V4UserInputService:GetMouseLocation()
        local bestScore = AimConfig.Pistol_FOVMode and (tonumber(AimConfig.Pistol_FOV) or 180) or math.huge
        local bestTarget = nil
        local targetRole = tostring(AimConfig.Pistol_Target or "Killer")
        for _, player in ipairs(V4Players:GetPlayers()) do
            if player ~= V4LocalPlayer and V4HasRole(player, targetRole) and player.Character then
                local char = player.Character
                local humanoid = char:FindFirstChildOfClass("Humanoid")
                local targetPart = V4GetTargetPart(char)
                if targetPart and (not humanoid or humanoid.Health > 0) and not V4IsDowned(char) then
                    local screenPos, onScreen = camera:WorldToViewportPoint(targetPart.Position)
                    if (onScreen and screenPos.Z > 0) or not AimConfig.Pistol_FOVMode then
                        local score
                        if AimConfig.Pistol_FOVMode then
                            score = (Vector2.new(screenPos.X, screenPos.Y) - mouseLocation).Magnitude
                        else
                            score = (targetPart.Position - myRoot.Position).Magnitude
                        end
                        if score < bestScore then
                            bestScore = score
                            bestTarget = targetPart
                        end
                    end
                end
            end
        end
        return bestTarget
    end

    local function V4GetKillerTargetForFlash()
        local myChar = V4LocalPlayer.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then return nil end
        local bestTarget, closestDistance = nil, math.huge
        for _, player in ipairs(V4Players:GetPlayers()) do
            if player ~= V4LocalPlayer and V4HasRole(player, "Killer") and player.Character then
                local char = player.Character
                local hum = char:FindFirstChildOfClass("Humanoid")
                local root = char:FindFirstChild("HumanoidRootPart")
                if root and (not hum or hum.Health > 0) and not V4IsDowned(char) then
                    local distance = (root.Position - myRoot.Position).Magnitude
                    if distance < closestDistance then
                        closestDistance, bestTarget = distance, root
                    end
                end
            end
        end
        return bestTarget
    end

    local function V4CreatePistolLaser()
        if pistolLaser and pistolLaser.Parent then return pistolLaser end
        if not pistolLaser then
            pistolLaser = Instance.new("Part")
            pistolLaser.Name = "VD_PistolLaser_V4"
            pistolLaser.Material = Enum.Material.Neon
            pistolLaser.Color = Color3.fromRGB(255, 0, 0)
            pistolLaser.CanCollide = false
            pistolLaser.CanTouch = false
            pistolLaser.CanQuery = false
            pistolLaser.Anchored = true
            pistolLaser.CastShadow = false
            pistolLaser.Size = Vector3.new(0.05, 0.05, 1)
            pistolLaser.Transparency = 1
        end
        return pistolLaser
    end

    pcall(function()
        if typeof(Drawing) == "table" and type(Drawing.new) == "function" then
            pistolFOVCircle = Drawing.new("Circle")
            pistolFOVCircle.Color = Color3.fromRGB(255, 255, 255)
            pistolFOVCircle.Thickness = 1.5
            pistolFOVCircle.Filled = false
            pistolFOVCircle.Visible = false
        end
    end)

    local function V4ExecuteSilentAimFire()
        local targetPart = V4GetPistolTarget()
        local myChar = V4LocalPlayer.Character
        if AimConfig.Pistol_BlockKnocked and V4IsDowned(myChar) then return end
        if not targetPart or not myChar then return end
        local myRoot = myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then return end

        local weapon = myChar:FindFirstChild("Twist of Fate")
        if not weapon then return end
        local weaponArg = weapon
        local rightArm = weapon:FindFirstChild("Right Arm")
        if rightArm then
            weaponArg = rightArm:FindFirstChild("EmperorGun")
                or rightArm:FindFirstChild("gun")
                or rightArm
        end

        local origin = myRoot.Position
        local targetPos = targetPart.Position
        local targetVelocity = targetPart.AssemblyLinearVelocity
        targetVelocity = Vector3.new(targetVelocity.X, 0, targetVelocity.Z)
        local distance = (targetPos - origin).Magnitude
        if distance <= 0.001 then return end
        local bulletSpeed = 400
        local timeToHit = distance / bulletSpeed
        local predictedPos = targetPos + targetVelocity * timeToHit
        local directionDelta = (predictedPos + Vector3.new(0, -2, 0)) - origin
        if directionDelta.Magnitude <= 0.001 then return end
        local aimDirection = directionDelta.Unit

        local remotes = V4ReplicatedStorage:FindFirstChild("Remotes")
        local items = remotes and remotes:FindFirstChild("Items")
        local twistItem = items and items:FindFirstChild("Twist of Fate")
        local fireRemote = twistItem and twistItem:FindFirstChild("Fire")
        if fireRemote and fireRemote:IsA("RemoteEvent") then
            pcall(function() fireRemote:FireServer(weaponArg, aimDirection) end)
        end
    end

    MAWWW_Conn(V4UserInputService.InputBegan, function(input, gameProcessed)
        local isTouch = input.UserInputType == Enum.UserInputType.Touch
        if gameProcessed and not isTouch then return end

        if input.UserInputType == Enum.UserInputType.MouseButton2 then
            if AimConfig.Aim_Silent then
                isChargingPistol = true
                lockedPistolTarget = V4GetPistolTarget()
            end
            if AimConfig.Flash_Silent then isAimingFlash = true end
        elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
            if AimConfig.Aim_Silent and isChargingPistol then V4ExecuteSilentAimFire() end
        end

        if isTouch and (AimConfig.Aim_Silent or AimConfig.Flash_Silent) then
            local playerGui = V4LocalPlayer:FindFirstChildOfClass("PlayerGui")
            local survivorMob = playerGui and playerGui:FindFirstChild("Survivor-mob")
            local controls = survivorMob and survivorMob:FindFirstChild("Controls")
            local targetButton = controls and controls:FindFirstChild("Gui-mob")
            if targetButton and targetButton.Visible then
                local pos, absPos, absSize = input.Position, targetButton.AbsolutePosition, targetButton.AbsoluteSize
                if pos.X >= absPos.X and pos.X <= absPos.X + absSize.X
                    and pos.Y >= absPos.Y and pos.Y <= absPos.Y + absSize.Y then
                    if AimConfig.Aim_Silent then
                        isChargingPistol = true
                        currentTouchPistolInput = input
                        lockedPistolTarget = V4GetPistolTarget()
                    end
                    if AimConfig.Flash_Silent then
                        isAimingFlash = true
                        currentTouchPistolInput = input
                    end
                end
            end
        end
    end)

    MAWWW_Conn(V4UserInputService.InputEnded, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton2 then
            isChargingPistol = false
            lockedPistolTarget = nil
            isAimingFlash = false
        end
        if input.UserInputType == Enum.UserInputType.Touch and input == currentTouchPistolInput then
            if isChargingPistol then
                isChargingPistol = false
                currentTouchPistolInput = nil
                V4ExecuteSilentAimFire()
                lockedPistolTarget = nil
            end
            isAimingFlash = false
            currentTouchPistolInput = nil
        end
    end)

    -- Source-file target shortcuts are retained for the two modes exposed by this panel.
    MAWWW_Conn(V4UserInputService.InputBegan, function(input, gameProcessed)
        if gameProcessed or input.UserInputType ~= Enum.UserInputType.Keyboard then return end
        if input.KeyCode == Enum.KeyCode.K then
            AimConfig.Pistol_Target = "Killer"
        elseif input.KeyCode == Enum.KeyCode.J then
            AimConfig.Pistol_Target = "Survivor"
        else
            return
        end
        VD.PistolTargetMode = AimConfig.Pistol_Target:upper()
        if type(getgenv().MAWWW_SilentPistolV4SetTargetMode) == "function" then
            pcall(getgenv().MAWWW_SilentPistolV4SetTargetMode, VD.PistolTargetMode)
        end
    end)

    MAWWW_Conn(V4RunService.RenderStepped, function()
        local camera = V4Workspace.CurrentCamera or V4Camera
        if camera then V4Camera = camera end

        if isAimingFlash and AimConfig.Flash_Silent and V4Camera then
            local targetPart = V4GetKillerTargetForFlash()
            if targetPart then
                local myChar = V4LocalPlayer.Character
                local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
                local targetPos = targetPart.Position + Vector3.new(0, tonumber(AimConfig.Flash_YOffset) or 8, 0)
                V4Camera.CFrame = V4Camera.CFrame:Lerp(CFrame.lookAt(V4Camera.CFrame.Position, targetPos), 0.5)
                if myRoot then
                    local targetFlat = Vector3.new(targetPos.X, myRoot.Position.Y, targetPos.Z)
                    myRoot.CFrame = myRoot.CFrame:Lerp(CFrame.lookAt(myRoot.Position, targetFlat), 0.5)
                end
            end
        end

        if isChargingPistol and V4Camera then
            if lockedPistolTarget and AimConfig.LockAim and lockedPistolTarget.Parent then
                local targetCharacter = lockedPistolTarget.Parent
                local humanoid = targetCharacter:FindFirstChildOfClass("Humanoid")
                if humanoid and humanoid.Health > 0 then
                    V4Camera.CFrame = V4Camera.CFrame:Lerp(CFrame.lookAt(V4Camera.CFrame.Position, lockedPistolTarget.Position), 0.15)
                else
                    lockedPistolTarget = V4GetPistolTarget()
                end
            else
                lockedPistolTarget = V4GetPistolTarget()
            end
        end

        if isChargingPistol and AimConfig.Aim_Silent then
            local targetPart = V4GetPistolTarget()
            if targetPart then
                local myChar = V4LocalPlayer.Character
                local leftArm = myChar and (myChar:FindFirstChild("Left Arm") or myChar:FindFirstChild("LeftHand"))
                local startPos = leftArm and leftArm.Position or (myChar and myChar:GetPivot().Position)
                if startPos then
                    local targetPos = targetPart.Position
                    local velocity = targetPart.AssemblyLinearVelocity
                    velocity = Vector3.new(velocity.X, 0, velocity.Z)
                    local distance = (targetPos - startPos).Magnitude
                    local predictedPos = targetPos + velocity * (distance / 400)
                    local endPos = predictedPos + Vector3.new(0, -1.2, 0)
                    local laser = V4CreatePistolLaser()
                    laser.Parent = V4Workspace
                    laser.Transparency = AimConfig.HideSilentLaser and 1 or 0
                    local laserDistance = (endPos - startPos).Magnitude
                    if laserDistance > 0.001 then
                        laser.Size = Vector3.new(0.05, 0.05, laserDistance)
                        laser.CFrame = CFrame.new(startPos, endPos) * CFrame.new(0, 0, -laserDistance / 2)
                    end
                end
            elseif pistolLaser and pistolLaser.Parent then
                pistolLaser.Parent = nil
            end
        elseif pistolLaser and pistolLaser.Parent then
            pistolLaser.Parent = nil
        end

        if pistolFOVCircle then
            local showCircle = AimConfig.Aim_Silent and AimConfig.Pistol_ShowFOV and AimConfig.Pistol_FOVMode and V4Camera ~= nil
            pistolFOVCircle.Visible = showCircle
            if showCircle then
                pistolFOVCircle.Radius = tonumber(AimConfig.Pistol_FOV) or 180
                pistolFOVCircle.Position = Vector2.new(V4Camera.ViewportSize.X / 2, V4Camera.ViewportSize.Y / 2)
                pistolFOVCircle.Color = V4GetPistolTarget() and Color3.fromRGB(255, 0, 0) or Color3.fromRGB(0, 255, 100)
            end
        end
    end)

    getgenv().MAWWW_SilentPistolV4Config = AimConfig
    getgenv().MAWWW_SilentPistolV4SetEnabled = function(enabled)
        AimConfig.Aim_Silent = enabled == true
        VD.PistolEnabled = AimConfig.Aim_Silent
        if not AimConfig.Aim_Silent then
            isChargingPistol = false
            lockedPistolTarget = nil
            if pistolLaser then pistolLaser.Parent = nil end
        end
    end
    getgenv().MAWWW_SilentPistolV4SetTargetMode = function(mode)
        local normalized = tostring(mode or "KILLER"):upper()
        if normalized ~= "KILLER" and normalized ~= "SURVIVOR" then normalized = "KILLER" end
        VD.PistolTargetMode = normalized
        AimConfig.Pistol_Target = normalized == "SURVIVOR" and "Survivor" or "Killer"
    end

    RegToggle(Tabs.AimTOFV4, "Silent Pistol V4", "Use the supplied Silent Aim / Twist of Fate engine.", AimConfig.Aim_Silent, "PistolEnabled", function(value)
        if type(getgenv().MAWWW_SilentPistolV4SetEnabled) == "function" then
            pcall(getgenv().MAWWW_SilentPistolV4SetEnabled, value)
        end
        if value then
            MAWWW_CreateFloatingToFTargetSelector("V4", "TOF V4", {
                {Value = "KILLER", Label = "KILLER"},
                {Value = "SURVIVOR", Label = "SURVIVOR"},
            }, function() return tostring(VD.PistolTargetMode or "KILLER"):upper() end, function(mode)
                VD.PistolTargetMode = mode
                local setter = getgenv().MAWWW_SilentPistolV4SetTargetMode
                if type(setter) == "function" then pcall(setter, mode) end
            end, 4)
        else
            MAWWW_DestroyFloatingToFTargetSelector("V4")
        end
    end)
    RegDropdown(Tabs.AimTOFV4, "Target Mode", "Choose Killer or Survivor targeting. K = Killer, J = Survivor.", {"KILLER", "SURVIVOR"}, targetMode, false, "PistolTargetMode", function(value)
        targetMode = tostring(value or "KILLER"):upper()
        if type(getgenv().MAWWW_SilentPistolV4SetTargetMode) == "function" then
            pcall(getgenv().MAWWW_SilentPistolV4SetTargetMode, targetMode)
        end
        MAWWW_RefreshFloatingToFTargetSelector("V4")
    end)
    RegDivider(Tabs.AimTOFV4)
    RegLabel(Tabs.AimTOFV4, "Silent Aim Options")
    RegToggle(Tabs.AimTOFV4, "Block Aim While Downed", "Do not aim when your character is knocked, hooked, or carried.", AimConfig.Pistol_BlockKnocked, "PistolBlockKnocked", function(value)
        AimConfig.Pistol_BlockKnocked = value == true
    end)
    RegToggle(Tabs.AimTOFV4, "Silent Flashlight Aim", "Aim flashlight toward the nearest Killer.", AimConfig.Flash_Silent, "PistolV4FlashSilentAim", function(value)
        AimConfig.Flash_Silent = value == true
    end)
    RegSlider(Tabs.AimTOFV4, "Flashlight Aim Height", "Vertical offset for flashlight target point.", AimConfig.Flash_YOffset, 1, 15, 0.5, "FlashAimYOffset", function(value)
        AimConfig.Flash_YOffset = tonumber(value) or 8
    end)
    RegToggle(Tabs.AimTOFV4, "Lock Aim", "Keep the camera aligned to the selected target while charging.", AimConfig.LockAim, "PistolLockAim", function(value)
        AimConfig.LockAim = value == true
    end)
    RegToggle(Tabs.AimTOFV4, "FOV Targeting", "Limit target selection to the FOV radius around the cursor.", AimConfig.Pistol_FOVMode, "PistolFOVMode", function(value)
        AimConfig.Pistol_FOVMode = value == true
    end)
    RegToggle(Tabs.AimTOFV4, "Show FOV Circle", "Display the pistol FOV circle when FOV targeting is enabled.", AimConfig.Pistol_ShowFOV, "PistolShowFOV", function(value)
        AimConfig.Pistol_ShowFOV = value == true
    end)
    RegSlider(Tabs.AimTOFV4, "Pistol FOV Radius", "Targeting radius in screen pixels.", AimConfig.Pistol_FOV, 50, 500, 5, "PistolFOV", function(value)
        AimConfig.Pistol_FOV = tonumber(value) or 180
    end)
    RegDropdown(Tabs.AimTOFV4, "Target Part", "Body part used for aiming.", {"Head", "Torso", "Root", "HumanoidRootPart"}, AimConfig.AIM_TargetPart, false, "PistolAimPart", function(value)
        AimConfig.AIM_TargetPart = tostring(value or "Torso")
    end)
    RegToggle(Tabs.AimTOFV4, "Show Aim Laser", "Show or hide the red silent-aim laser.", not AimConfig.HideSilentLaser, "PistolLaser", function(value)
        AimConfig.HideSilentLaser = not (value == true)
        if pistolLaser then pistolLaser.Transparency = AimConfig.HideSilentLaser and 1 or 0 end
    end)
end


