RegLabel(Tabs.VisualCamera, "Camera")
CameraZoom = { DefaultFOV = 70 }
local CameraEnv = (getgenv and getgenv()) or _G
local FOVConnection = nil
pcall(function()
    local oldFOV = CameraEnv.MAWWW_CameraFOVConnection
    if oldFOV then oldFOV:Disconnect() end
    CameraEnv.MAWWW_CameraFOVConnection = nil
end)

function applyUnlimitedZoom()
    if VD.DBDCamera then return end
    if VD.UnlimitedZoom then
        Player.CameraMaxZoomDistance = VD.MaxZoomDistance
        Player.CameraMinZoomDistance = 0
    else
        Player.CameraMaxZoomDistance = 128
        Player.CameraMinZoomDistance = 0.5
    end
end

function applyCameraFOV()
    if VD.DBDCamera then return end
    local cam = workspace.CurrentCamera
    if not cam then return end
    if VD.FOVEnabled then
        cam.FieldOfView = tonumber(VD.FOV) or 90
    else
        cam.FieldOfView = CameraZoom.DefaultFOV
    end
end

function FOV_SetEnabled(enabled)
    VD.FOVEnabled = enabled == true
    if VD.FOVEnabled then
        VD.FOV = 90
        applyCameraFOV()
        if not FOVConnection then
            FOVConnection = MAWWW_Conn(RunService.RenderStepped, function()
                if (VD.Destroyed or MAWWW_RUN.dead) or not VD.FOVEnabled or VD.DBDCamera then return end
                local cam = workspace.CurrentCamera
                local target = tonumber(VD.FOV) or 90
                if cam and math.abs(cam.FieldOfView - target) > 0.1 then
                    cam.FieldOfView = target
                end
            end)
            CameraEnv.MAWWW_CameraFOVConnection = FOVConnection
        end
    else
        if FOVConnection then
            pcall(function() FOVConnection:Disconnect() end)
            FOVConnection = nil
        end
        CameraEnv.MAWWW_CameraFOVConnection = nil
        applyCameraFOV()
    end
end

MAWWW_Conn(Player.CharacterAdded, function()
    task.wait(0.5)
    if not VD.DBDCamera then
        applyUnlimitedZoom()
        applyCameraFOV()
    end
end)

RegToggle(Tabs.VisualCamera, "Unlimited Zoom", "Remove zoom limit", false, "UnlimitedZoom", function(v)
    applyUnlimitedZoom()
end)
RegSlider(Tabs.VisualCamera, "Max Zoom Distance", "Max camera distance", 1000, 100, 5000, 50, "MaxZoomDistance", function(v)
    if VD.UnlimitedZoom then applyUnlimitedZoom() end
end)
RegToggle(Tabs.VisualCamera, "Fixed FOV • 90", "Enable fixed 90 FOV only when needed.", false, "FOVEnabled", function(v)
    FOV_SetEnabled(v)
end)
RegSlider(Tabs.VisualCamera, "Camera FOV", "Source fixed at 90.", 90, 90, 90, 1, "FOV", function(v)
    VD.FOV = 90
    if VD.FOVEnabled then applyCameraFOV() end
end)
