local shiftLockWasActive = false
local thirdPersonWasActive = false
local CameraControlConnection = nil
local CameraControlEnv = (getgenv and getgenv()) or _G
local thirdPersonSnapshot = nil
local shiftLockSnapshot = nil
-- Let a newer execution restore the camera snapshots held by this execution
-- before the old RenderStepped connection is disconnected.
pcall(function()
    local previousShutdown = CameraControlEnv.MAWWW_CameraControlShutdown
    if type(previousShutdown) == "function" then previousShutdown() end
end)
pcall(function()
    local previous = CameraControlEnv.MAWWW_CameraControlConnection
    if previous then previous:Disconnect() end
    CameraControlEnv.MAWWW_CameraControlConnection = nil
end)

function restoreThirdPerson()
    local snapshot = thirdPersonSnapshot
    if snapshot then
        pcall(function()
            if snapshot.Humanoid and snapshot.Humanoid.Parent then
                snapshot.Humanoid.CameraOffset = snapshot.CameraOffset or Vector3.zero
            end
        end)
    end
    thirdPersonSnapshot = nil
    thirdPersonWasActive = false
end

function restoreShiftLock()
    local snapshot = shiftLockSnapshot
    if snapshot then
        pcall(function()
            if snapshot.Humanoid and snapshot.Humanoid.Parent then
                snapshot.Humanoid.AutoRotate = snapshot.AutoRotate
            end
        end)
    end
    shiftLockSnapshot = nil
    shiftLockWasActive = false
end

local cameraControlWasInMatch = false
local cameraTeamCacheTeam, cameraTeamCacheName, cameraTeamCacheLobby = nil, nil, false

local function cameraControlResetView()
    local cam = workspace.CurrentCamera
    if not cam then return end
    local character = Player.Character
    local hum = character and character:FindFirstChildOfClass("Humanoid")
    pcall(function()
        -- Return to Roblox's normal character camera rather than leaving a forced
        -- Custom/Scriptable camera state behind after a round ends.
        cam.CameraType = Enum.CameraType.Custom
        if hum and hum.Health > 0 then
            cam.CameraSubject = hum
        end
    end)
end

function CameraControlUpdate()
    local cam = workspace.CurrentCamera
    if not cam then return end
    local char = Player.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local role = GetRole()
    -- Team name classification is cached per team (this runs every frame while
    -- Third Person / Shift Lock is on; string work only happens on a team change).
    local currentTeam = Player.Team
    if currentTeam ~= cameraTeamCacheTeam or cameraTeamCacheName ~= (currentTeam and currentTeam.Name) then
        cameraTeamCacheTeam = currentTeam
        cameraTeamCacheName = currentTeam and currentTeam.Name
        local teamName = string.lower(cameraTeamCacheName or "")
        cameraTeamCacheLobby = (teamName:find("lobby", 1, true)
            or teamName:find("spectat", 1, true)
            or teamName:find("wait", 1, true)
            or teamName:find("menu", 1, true)) ~= nil
    end
    local explicitlyInLobby = cameraTeamCacheLobby
    -- Team/role attributes can briefly remain stale at round-end; an explicit
    -- Lobby/Spectator/Waiting team takes precedence over those stale attributes.
    local roleInMatch = (role == "Killer" or role == "Survivor") and not explicitlyInLobby
    local characterAlive = hum ~= nil and hum.Health > 0 and root ~= nil

    -- The previous version kept applying Shift Lock in the lobby and could
    -- override the game's post-round camera. Restore saved character properties
    -- immediately once the player leaves a live role or their character dies.
    if not roleInMatch or not characterAlive then
        local wasControlling = cameraControlWasInMatch
        restoreThirdPerson()
        restoreShiftLock()
        if wasControlling then
            cameraControlResetView()
            cameraControlWasInMatch = false
        end
        return
    end

    if (VD.ThirdPerson and role == "Killer") or VD.ShiftLock then
        cameraControlWasInMatch = true
    end

    if VD.ThirdPerson and role == "Killer" then
        if not thirdPersonSnapshot or thirdPersonSnapshot.Humanoid ~= hum then
            restoreThirdPerson()
            thirdPersonSnapshot = { Humanoid = hum, CameraOffset = hum.CameraOffset }
            -- Switch to the normal character camera once when Third Person engages.
            -- It is no longer forced every frame, so camera changes made by the game
            -- (cutscenes, spectate, lobby camera) are respected.
            if cam.CameraType ~= Enum.CameraType.Custom then
                cam.CameraType = Enum.CameraType.Custom
            end
        end
        local targetOffset = Vector3.new(2, 1, 8)
        if (hum.CameraOffset - targetOffset).Magnitude > 0.01 then
            hum.CameraOffset = targetOffset
        end
        thirdPersonWasActive = true
    else
        restoreThirdPerson()
    end

    if VD.ShiftLock then
        if not shiftLockSnapshot or shiftLockSnapshot.Humanoid ~= hum then
            restoreShiftLock()
            shiftLockSnapshot = { Humanoid = hum, AutoRotate = hum.AutoRotate }
        end
        if hum.AutoRotate then hum.AutoRotate = false end
        local look = cam.CFrame.LookVector
        local flat = Vector3.new(look.X, 0, look.Z)
        if flat.Magnitude > 0.001 then
            root.CFrame = CFrame.new(root.Position, root.Position + flat.Unit)
        end
        shiftLockWasActive = true
    else
        restoreShiftLock()
    end
end

function CameraControl_SetEnabled()
    local shouldRun = VD.ThirdPerson == true or VD.ShiftLock == true
    if shouldRun then
        if not CameraControlConnection then
            CameraControlConnection = MAWWW_Conn(RunService.RenderStepped, function()
                if (VD.Destroyed or MAWWW_RUN.dead) then return end
                pcall(CameraControlUpdate)
            end)
            CameraControlEnv.MAWWW_CameraControlConnection = CameraControlConnection
        end
    else
        local wasControlling = cameraControlWasInMatch
        if CameraControlConnection then
            pcall(function() CameraControlConnection:Disconnect() end)
            CameraControlConnection = nil
        end
        CameraControlEnv.MAWWW_CameraControlConnection = nil
        restoreThirdPerson()
        restoreShiftLock()
        if wasControlling then
            cameraControlResetView()
            cameraControlWasInMatch = false
        end
    end
end

-- Restore character/camera state before the old character is removed. This
-- prevents stale CameraOffset/AutoRotate snapshots from leaking into the next
-- round or leaving the camera pointed at a removed Humanoid.
pcall(function()
    local previous = CameraControlEnv.MAWWW_CameraCharacterRemovingConnection
    if previous then previous:Disconnect() end
end)
CameraControlEnv.MAWWW_CameraCharacterRemovingConnection = MAWWW_Conn(Player.CharacterRemoving, function()
    local wasControlling = cameraControlWasInMatch
    restoreThirdPerson()
    restoreShiftLock()
    if wasControlling then
        local cam = workspace.CurrentCamera
        if cam then pcall(function() cam.CameraType = Enum.CameraType.Custom end) end
        cameraControlWasInMatch = false
    end
end)

pcall(function()
    local previous = CameraControlEnv.MAWWW_CameraCharacterAddedConnection
    if previous then previous:Disconnect() end
end)
CameraControlEnv.MAWWW_CameraCharacterAddedConnection = MAWWW_Conn(Player.CharacterAdded, function(character)
    task.defer(function()
        if Player.Character ~= character then return end
        local hum = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 5)
        if not hum or Player.Character ~= character then return end
        -- Only touch the camera when this feature set is actually in use; with
        -- Third Person / Shift Lock off the game keeps full control of its camera.
        if VD.ThirdPerson == true or VD.ShiftLock == true then
            if not cameraControlWasInMatch then
                local cam = workspace.CurrentCamera
                if cam and cam.CameraType ~= Enum.CameraType.Custom then
                    pcall(function() cam.CameraType = Enum.CameraType.Custom end)
                end
                if cam and cam.CameraSubject ~= hum then
                    pcall(function() cam.CameraSubject = hum end)
                end
            end
            CameraControl_SetEnabled()
        end
    end)
end)

CameraControlEnv.MAWWW_CameraControlShutdown = function()
    local wasControlling = cameraControlWasInMatch
    if CameraControlConnection then
        pcall(function() CameraControlConnection:Disconnect() end)
        CameraControlConnection = nil
    end
    CameraControlEnv.MAWWW_CameraControlConnection = nil
    pcall(restoreThirdPerson)
    pcall(restoreShiftLock)
    if wasControlling then pcall(cameraControlResetView) end
    cameraControlWasInMatch = false
    local removing = CameraControlEnv.MAWWW_CameraCharacterRemovingConnection
    local added = CameraControlEnv.MAWWW_CameraCharacterAddedConnection
    if removing then pcall(function() removing:Disconnect() end) end
    if added then pcall(function() added:Disconnect() end) end
    CameraControlEnv.MAWWW_CameraCharacterRemovingConnection = nil
    CameraControlEnv.MAWWW_CameraCharacterAddedConnection = nil
    CameraControlEnv.MAWWW_CameraControlShutdown = nil
end

