InfoOverlayGui, InfoOverlayFrame, InfoOverlayLabel = nil, nil, nil
function EnsureInfoOverlay()
    if InfoOverlayGui and InfoOverlayGui.Parent then return end
    InfoOverlayGui = Instance.new("ScreenGui")
    InfoOverlayGui.Name = "MWD_InfoOverlay"; InfoOverlayGui.ResetOnSpawn = false; InfoOverlayGui.IgnoreGuiInset = true
    InfoOverlayGui.Parent = PlayerGui
    InfoOverlayFrame = Instance.new("Frame")
    InfoOverlayFrame.Size = UDim2.new(0, 230, 0, 0); InfoOverlayFrame.AutomaticSize = Enum.AutomaticSize.Y
    InfoOverlayFrame.Position = UDim2.new(0, 12, 0, 180)
    InfoOverlayFrame.BackgroundColor3 = Color3.fromRGB(16, 18, 24); InfoOverlayFrame.BackgroundTransparency = 0.1
    InfoOverlayFrame.BorderSizePixel = 0; InfoOverlayFrame.Parent = InfoOverlayGui
    Instance.new("UICorner", InfoOverlayFrame).CornerRadius = UDim.new(0, 8)
    local stroke = Instance.new("UIStroke", InfoOverlayFrame); stroke.Color = Color3.fromRGB(96, 72, 160); stroke.Thickness = 1
    local pad = Instance.new("UIPadding", InfoOverlayFrame)
    pad.PaddingTop = UDim.new(0, 6); pad.PaddingBottom = UDim.new(0, 6); pad.PaddingLeft = UDim.new(0, 8); pad.PaddingRight = UDim.new(0, 8)
    InfoOverlayLabel = Instance.new("TextLabel")
    InfoOverlayLabel.Size = UDim2.new(1, 0, 0, 0); InfoOverlayLabel.AutomaticSize = Enum.AutomaticSize.Y
    InfoOverlayLabel.BackgroundTransparency = 1; InfoOverlayLabel.Font = Enum.Font.GothamBold
    InfoOverlayLabel.TextSize = 12; InfoOverlayLabel.TextColor3 = Color3.fromRGB(230, 235, 245)
    InfoOverlayLabel.TextXAlignment = Enum.TextXAlignment.Left; InfoOverlayLabel.TextYAlignment = Enum.TextYAlignment.Top
    InfoOverlayLabel.TextWrapped = true; InfoOverlayLabel.Text = ""; InfoOverlayLabel.Parent = InfoOverlayFrame
end
function UpdateInfoOverlay()
    local anyOn = VD.MawwwtKiller or VD.SpectatorCounter or VD.KillerPerks
    if not anyOn then if InfoOverlayFrame then InfoOverlayFrame.Visible = false end; return end
    if not InfoOverlayFrame then EnsureInfoOverlay() end
    InfoOverlayFrame.Visible = true
    local lines = {}
    if VD.MawwwtKiller then
        local list = MawwwGetPlayers()
        table.sort(list, function(a, b)
            local aA = a:GetAttribute("AllowKiller") or false
            local bB = b:GetAttribute("AllowKiller") or false
            if aA ~= bB then return aA == true end
            return (a:GetAttribute("KillerChance") or 0) > (b:GetAttribute("KillerChance") or 0)
        end)
        local nk = list[1]
        local nkName = nk and (nk == Player and "YOU" or (nk.DisplayName or nk.Name)) or "Unknown"
        local nkScore = nk and (nk:GetAttribute("KillerChance") or 0) or 0
        table.insert(lines, string.format("[Killer Chance] %s (%d)", nkName, nkScore))
    end
    if VD.SpectatorCounter then
        local count = 0
        for _, p in ipairs(MawwwGetPlayers()) do if p.Team and p.Team.Name == "Spectator" then count = count + 1 end end
        table.insert(lines, string.format("[Spectators] %d", count))
    end
    if VD.KillerPerks then
        local k = nil
        for _, p in ipairs(MawwwGetPlayers()) do if p ~= Player and IsKiller(p) then k = p; break end end
        if k then table.insert(lines, string.format("[Killer] %s", k.DisplayName or k.Name))
        else table.insert(lines, "[Killer] None") end
    end
    InfoOverlayLabel.Text = table.concat(lines, "\n")
end
task.spawn(function()
    while not (VD.Destroyed or MAWWW_RUN.dead) do task.wait(1); pcall(UpdateInfoOverlay) end
end)


--========================================================--
-- STUN INDICATOR
-- Detects stunned killers in range and optionally plays a selected sound.
--========================================================--
do
    local StunIndicator = {
        Enabled = false,
        Range = 500,
        SoundEnabled = true,
        SoundVolume = 1.5,
        SoundRange = 500,
        SelectedSound = "an anime",
        Connection = nil,
        DaggerConnection = nil,
        DaggerStunUntil = {},
        Cache = {},
        LastScan = 0,
        ScanInterval = 0.12,
    }

    local StunSounds = {
        ["an anime"] = "128090092396552",
        ["Default"] = "18843924331",
        ["Clash Royale"] = "114072050006157",
        ["Blash"] = "89068385567682",
        ["Coin"] = "75510526696824",
        ["Kururin Kuru"] = "119896940405402",
        ["Spongebob"] = "6835794541",
        ["Fahhhh"] = "123562480982353",
        ["Cave"] = "3173566193",
        ["Aughhh"] = "9095205664",
        ["iPhone"] = "4203251375",
        ["Siren"] = "130677853589923",
    }

    local SoundOptions = {
        "an anime",
        "Default",
        "Clash Royale",
        "Blash",
        "Coin",
        "Kururin Kuru",
        "Spongebob",
        "Fahhhh",
        "Cave",
        "Aughhh",
        "iPhone",
        "Siren",
    }

    local function GetSoundId()
        return StunSounds[StunIndicator.SelectedSound] or StunSounds["Default"]
    end

    local function MAWWW_IsTruthyStunFlag(value)
        if value == true then return true end
        if type(value) == "number" then return value > 0 end
        if type(value) == "string" then
            local text = string.lower(value):gsub("^%s+", ""):gsub("%s+$", "")
            return text == "true" or text == "yes" or text == "active"
                or text == "stun" or text == "stunned" or text == "1"
        end
        return false
    end

    local function IsStunned(character)
        if not character then return false end

        -- Dagger parries are confirmed by the game's parryResult RemoteEvent.
        -- Some game builds do not replicate a human-readable stun attribute or
        -- animation name, so honor the short-lived confirmed-parry marker first.
        local daggerStunUntil = StunIndicator.DaggerStunUntil[character]
        if daggerStunUntil then
            if daggerStunUntil > os.clock() then
                return true
            end
            StunIndicator.DaggerStunUntil[character] = nil
        end

        -- Different game builds expose stun state on the model, player, Humanoid,
        -- root part, or the interaction-state object. Check all common locations.
        local attrs = {
            "IsStunned", "isStunned", "Stunned", "stunned",
            "IsStun", "Stun", "StunActive", "StunState", "StunDuration",
        }
        local targets = { character }
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local root = character:FindFirstChild("HumanoidRootPart")
        local check = character:FindFirstChild("CheckInterractable", true)
        if humanoid then table.insert(targets, humanoid) end
        if root then table.insert(targets, root) end
        if check then
            table.insert(targets, check)
            local action = nil
            pcall(function() action = check:GetAttribute("action") or check:GetAttribute("Action") end)
            if type(action) == "string" then
                local actionName = string.lower(action)
                if actionName:find("stun", 1, true) or actionName:find("stagger", 1, true) then
                    return true
                end
            end
        end
        local owner = Players:GetPlayerFromCharacter(character)
        if owner then table.insert(targets, owner) end

        for _, target in ipairs(targets) do
            for _, name in ipairs(attrs) do
                local ok, value = pcall(function() return target:GetAttribute(name) end)
                if ok and MAWWW_IsTruthyStunFlag(value) then return true end
            end
        end

        -- Some versions replicate state as BoolValue/NumberValue/StringValue instead
        -- of attributes. Only inspect objects whose names actually refer to stun.
        local descendants = character:GetDescendants()
        for _, object in ipairs(descendants) do
            local objectName = string.lower(tostring(object.Name or ""))
            if objectName:find("stun", 1, true) then
                local ok, value = pcall(function()
                    if object:IsA("BoolValue") or object:IsA("NumberValue")
                        or object:IsA("IntValue") or object:IsA("StringValue") then
                        return object.Value
                    end
                    return nil
                end)
                if ok and MAWWW_IsTruthyStunFlag(value) then return true end
            end
        end

        -- Animation state is an additional fallback for games that name stun tracks.
        if humanoid then
            local ok, animator = pcall(function() return humanoid:FindFirstChildOfClass("Animator") end)
            if ok and animator then
                local tracksOK, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
                if tracksOK then
                    for _, track in ipairs(tracks) do
                        local trackName = string.lower(tostring(track.Name or ""))
                        local animationName = ""
                        pcall(function() animationName = string.lower(tostring(track.Animation.Name or "")) end)
                        if trackName:find("stun", 1, true) or trackName:find("stagger", 1, true)
                            or animationName:find("stun", 1, true) or animationName:find("stagger", 1, true) then
                            return true
                        end
                    end
                end
            end
        end

        return false
    end

    local function PlayStunSound(character)
        if not StunIndicator.SoundEnabled then return end
        if StunIndicator.SoundVolume <= 0 then return end

        local attach = character and (
            character:FindFirstChild("Head")
            or character:FindFirstChild("HumanoidRootPart")
        )

        if not attach then return end

        local sound = Instance.new("Sound")
        sound.Name = "MawwwHub_StunSound"
        sound.SoundId = "rbxassetid://" .. tostring(GetSoundId())
        sound.Volume = math.clamp(tonumber(StunIndicator.SoundVolume) or 1.5, 0, 5)
        sound.RollOffMode = Enum.RollOffMode.InverseTapered
        sound.RollOffMinDistance = 10
        sound.RollOffMaxDistance = math.max(10, tonumber(StunIndicator.SoundRange) or 500)
        sound.Parent = attach

        local ok = pcall(function()
            sound:Play()
        end)

        if not ok then
            pcall(function() sound:Destroy() end)
            return
        end

        sound.Ended:Connect(function()
            if sound and sound.Parent then
                pcall(function() sound:Destroy() end)
            end
        end)

        task.delay(8, function()
            if sound and sound.Parent then
                pcall(function() sound:Destroy() end)
            end
        end)
    end

    local function RemoveIndicator(character)
        local data = StunIndicator.Cache[character]
        if not data then return end

        if data.Gui then
            pcall(function()
                data.Gui:Destroy()
            end)
        end

        StunIndicator.Cache[character] = nil
    end

    local function CreateIndicator(character)
        if StunIndicator.Cache[character] then
            local cached = StunIndicator.Cache[character]
            if cached.Gui and cached.Gui.Parent then
                return cached
            end
            StunIndicator.Cache[character] = nil
        end

        local head = character and (character:FindFirstChild("Head") or character:FindFirstChild("HumanoidRootPart"))
        if not head then return nil end

        local gui = Instance.new("BillboardGui")
        gui.Name = "MawwwHub_StunIndicator"
        gui.Adornee = head
        gui.AlwaysOnTop = true
        gui.LightInfluence = 0
        gui.MaxDistance = math.max(0, tonumber(StunIndicator.Range) or 500)
        gui.Size = UDim2.fromOffset(140, 40)
        gui.StudsOffset = Vector3.new(0, 3, 0)
        gui.Parent = head

        local frame = Instance.new("Frame")
        frame.Name = "Container"
        frame.Size = UDim2.fromScale(1, 1)
        frame.BackgroundColor3 = Color3.fromRGB(15, 15, 20)
        frame.BackgroundTransparency = 0.05
        frame.BorderSizePixel = 0
        frame.Parent = gui

        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 9)
        corner.Parent = frame

        local stroke = Instance.new("UIStroke")
        stroke.Thickness = 1.5
        stroke.Color = Color3.fromRGB(255, 255, 255)
        stroke.Transparency = 0.15
        stroke.Parent = frame

        local title = Instance.new("TextLabel")
        title.Name = "Title"
        title.BackgroundTransparency = 1
        title.Position = UDim2.fromOffset(10, 5)
        title.Size = UDim2.new(1, -20, 0, 15)
        title.Font = Enum.Font.GothamBlack
        title.Text = "STUNNED"
        title.TextColor3 = Color3.fromRGB(255, 255, 255)
        title.TextSize = 12
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.Parent = frame

        local sub = Instance.new("TextLabel")
        sub.Name = "Subtitle"
        sub.BackgroundTransparency = 1
        sub.Position = UDim2.fromOffset(10, 20)
        sub.Size = UDim2.new(1, -20, 0, 12)
        sub.Font = Enum.Font.GothamBold
        sub.Text = "STUN INDICATOR"
        sub.TextColor3 = Color3.fromRGB(175, 175, 185)
        sub.TextSize = 8
        sub.TextXAlignment = Enum.TextXAlignment.Left
        sub.Parent = frame

        local data = {
            Gui = gui,
            Stroke = stroke,
        }
        StunIndicator.Cache[character] = data

        -- Static stroke avoids a separate animation coroutine per stunned character.

        return data
    end

    -- Dagger fallback: the game confirms a successful parry through
    -- Remotes.Items["Parrying Dagger"].parryResult(success, cooldown). When that
    -- result is successful, mark the closest Killer for the game's short stun
    -- window even if the character exposes no stun attribute/track name locally.
    local function MAWWW_MarkNearestDaggerStun()
        if not StunIndicator.Enabled then return false end
        local myCharacter = LocalPlayer and LocalPlayer.Character
        local myRoot = myCharacter and myCharacter:FindFirstChild("HumanoidRootPart")
        if not myRoot then return false end

        local nearestCharacter = nil
        local nearestDistance = math.huge
        local parryRadius = 55
        for _, candidate in ipairs(MawwwGetPlayers()) do
            if candidate ~= LocalPlayer and candidate.Parent and IsKiller(candidate) then
                local candidateCharacter = candidate.Character
                local candidateRoot = candidateCharacter and candidateCharacter:FindFirstChild("HumanoidRootPart")
                local candidateHumanoid = candidateCharacter and candidateCharacter:FindFirstChildOfClass("Humanoid")
                if candidateRoot and candidateHumanoid and candidateHumanoid.Health > 0 then
                    local distance = (candidateRoot.Position - myRoot.Position).Magnitude
                    if distance <= parryRadius and distance < nearestDistance then
                        nearestDistance = distance
                        nearestCharacter = candidateCharacter
                    end
                end
            end
        end

        if nearestCharacter then
            -- Violence District's Parrying Dagger stun is about four seconds.
            StunIndicator.DaggerStunUntil[nearestCharacter] = os.clock() + 4.25
            return true
        end
        return false
    end

    local function MAWWW_BindDaggerStunRemote()
        task.spawn(function()
            local remoteStorage = game:GetService("ReplicatedStorage")
            local remotes = remoteStorage:WaitForChild("Remotes", 15)
            local items = remotes and remotes:WaitForChild("Items", 15)
            local dagger = items and items:WaitForChild("Parrying Dagger", 15)
            local resultRemote = dagger and dagger:WaitForChild("parryResult", 15)
            if not resultRemote or not resultRemote:IsA("RemoteEvent") then return end

            if StunIndicator.DaggerConnection then
                pcall(function() StunIndicator.DaggerConnection:Disconnect() end)
                StunIndicator.DaggerConnection = nil
            end

            StunIndicator.DaggerConnection = resultRemote.OnClientEvent:Connect(function(success)
                local confirmed = success == true
                if type(success) == "number" then confirmed = success ~= 0 end
                if type(success) == "string" then
                    local normalized = string.lower(success)
                    confirmed = normalized == "true" or normalized == "success" or normalized == "1"
                end
                if not confirmed or not StunIndicator.Enabled then return end

                -- Try immediately and briefly afterward, allowing replicated
                -- character positions/role metadata to settle after the parry.
                MAWWW_MarkNearestDaggerStun()
                task.delay(0.08, MAWWW_MarkNearestDaggerStun)
                task.delay(0.20, MAWWW_MarkNearestDaggerStun)
            end)
        end)
    end
    MAWWW_BindDaggerStunRemote()

    local function CleanupStale()
        local now = os.clock()
        for character in pairs(StunIndicator.Cache) do
            if not character or not character.Parent then
                RemoveIndicator(character)
            end
        end
        for character, expiresAt in pairs(StunIndicator.DaggerStunUntil) do
            if not character or not character.Parent or expiresAt <= now then
                StunIndicator.DaggerStunUntil[character] = nil
            end
        end
    end

    function StunIndicatorSetEnabled(enabled)
        StunIndicator.Enabled = enabled == true

        if StunIndicator.Connection then
            pcall(function()
                StunIndicator.Connection:Disconnect()
            end)
            StunIndicator.Connection = nil
        end

        if not StunIndicator.Enabled then
            for character in pairs(StunIndicator.Cache) do
                RemoveIndicator(character)
            end
            for character in pairs(StunIndicator.DaggerStunUntil) do
                StunIndicator.DaggerStunUntil[character] = nil
            end
            return
        end

        StunIndicator.LastScan = 0
        StunIndicator.Connection = MAWWW_Conn(RunService.Heartbeat, function()
            if not StunIndicator.Enabled or (VD and (VD.Destroyed or MAWWW_RUN.dead)) then
                return
            end

            local now = os.clock()
            if now - StunIndicator.LastScan < StunIndicator.ScanInterval then
                return
            end
            StunIndicator.LastScan = now

            local myCharacter = Player and Player.Character
            local myRoot = myCharacter and myCharacter:FindFirstChild("HumanoidRootPart")
            if not myRoot then
                CleanupStale()
                return
            end

            local maxRange = math.max(0, tonumber(StunIndicator.Range) or 500)
            local maxRangeSq = maxRange * maxRange
            local seen = {}

            for _, player in ipairs(MawwwGetPlayers()) do
                if player ~= Player and player.Character and IsKiller(player) then
                    local character = player.Character
                    local root = character:FindFirstChild("HumanoidRootPart")

                    if root then
                        local offset = root.Position - myRoot.Position
                        local distanceSq = offset.X * offset.X + offset.Y * offset.Y + offset.Z * offset.Z
                        local stunned = distanceSq <= maxRangeSq and IsStunned(character)
                        seen[character] = true

                        if stunned then
                            if not StunIndicator.Cache[character] then
                                PlayStunSound(character)
                                CreateIndicator(character)
                            elseif StunIndicator.Cache[character].Gui
                                and not StunIndicator.Cache[character].Gui.Parent then
                                RemoveIndicator(character)
                            end

                            local cached = StunIndicator.Cache[character]
                            if cached and cached.Gui then
                                pcall(function()
                                    cached.Gui.MaxDistance = maxRange
                                end)
                            end
                        elseif StunIndicator.Cache[character] then
                            RemoveIndicator(character)
                        end
                    elseif StunIndicator.Cache[character] then
                        RemoveIndicator(character)
                    end
                end
            end

            -- Remove indicators for players who are no longer eligible/current.
            for character in pairs(StunIndicator.Cache) do
                if not seen[character] then
                    RemoveIndicator(character)
                end
            end
        end)
    end

    function StunIndicatorPreviewSound()
        if not StunIndicator.SoundEnabled then return end

        local sound = Instance.new("Sound")
        sound.Name = "MawwwHub_StunPreview"
        sound.SoundId = "rbxassetid://" .. tostring(GetSoundId())
        sound.Volume = math.clamp(tonumber(StunIndicator.SoundVolume) or 1.5, 0, 5)
        sound.Parent = SoundService

        local ok = pcall(function()
            sound:Play()
        end)

        if not ok then
            pcall(function() sound:Destroy() end)
            return
        end

        sound.Ended:Connect(function()
            if sound and sound.Parent then
                pcall(function() sound:Destroy() end)
            end
        end)

        task.delay(8, function()
            if sound and sound.Parent then
                pcall(function() sound:Destroy() end)
            end
        end)
    end

    getgenv().MAWWW_StunIndicatorShutdown = function()
        pcall(function()
            StunIndicatorSetEnabled(false)
        end)
        pcall(function()
            if StunIndicator.DaggerConnection then
                StunIndicator.DaggerConnection:Disconnect()
                StunIndicator.DaggerConnection = nil
            end
        end)
        pcall(function()
            for character in pairs(StunIndicator.Cache) do
                RemoveIndicator(character)
            end
        end)
    end

    getgenv().MAWWW_StunIndicator = StunIndicator
    getgenv().MAWWW_StunSounds = StunSounds

    local function ApplyStunIndicatorConfig()
        StunIndicator.Range = math.max(0, tonumber(VD.StunIndicatorRange) or 500)
        StunIndicator.SoundRange = math.max(10, tonumber(VD.StunIndicatorSoundRange) or StunIndicator.Range)
        StunIndicator.SoundVolume = math.clamp(tonumber(VD.StunIndicatorSoundVolume) or 1.5, 0, 5)
        StunIndicator.SoundEnabled = VD.StunIndicatorSoundEnabled ~= false

        local selected = tostring(VD.StunIndicatorSelectedSound or "an anime")
        if not StunSounds[selected] then
            selected = "an anime"
        end
        StunIndicator.SelectedSound = selected

        StunIndicatorSetEnabled(VD.StunIndicatorEnabled == true)
    end

    -- Store the helper globally so loaded configs and other hub modules can reuse it.
    getgenv().MAWWW_ApplyStunIndicatorConfig = ApplyStunIndicatorConfig

    RegDivider(Tabs.VisualHUD, "Stun Indicator")
    RegToggle(
        Tabs.VisualHUD,
        "Stun Indicator",
        "Tampilkan indikator saat killer dalam keadaan stun.",
        false,
        "StunIndicatorEnabled",
        function(v)
            VD.StunIndicatorEnabled = v == true
            StunIndicatorSetEnabled(VD.StunIndicatorEnabled)
        end
    )
    RegSlider(
        Tabs.VisualHUD,
        "Detection Range",
        "Jarak maksimum untuk mendeteksi killer yang sedang stun.",
        500,
        25,
        500,
        5,
        "StunIndicatorRange",
        function(v)
            StunIndicator.Range = math.max(0, tonumber(v) or 500)
            StunIndicator.SoundRange = StunIndicator.Range
        end
    )
    RegToggle(
        Tabs.VisualHUD,
        "Stun Sound",
        "Putar suara ketika stun pertama kali terdeteksi.",
        true,
        "StunIndicatorSoundEnabled",
        function(v)
            StunIndicator.SoundEnabled = v == true
        end
    )
    RegSlider(
        Tabs.VisualHUD,
        "Sound Volume",
        "Atur volume suara indikator stun.",
        1.5,
        0,
        5,
        0.1,
        "StunIndicatorSoundVolume",
        function(v)
            StunIndicator.SoundVolume = math.clamp(tonumber(v) or 1.5, 0, 5)
        end
    )
    RegDropdown(
        Tabs.VisualHUD,
        "Stun Sound Effect",
        "Pilih suara yang diputar saat killer stun.",
        SoundOptions,
        "an anime",
        false,
        "StunIndicatorSelectedSound",
        function(v)
            local selected = tostring(v or "an anime")
            if StunSounds[selected] then
                StunIndicator.SelectedSound = selected
            end
        end
    )
    RegButton(
        Tabs.VisualHUD,
        "Preview Stun Sound",
        "Tes suara stun yang sedang dipilih.",
        function()
            StunIndicatorPreviewSound()
        end
    )

    ApplyStunIndicatorConfig()

    -- Dedicated, draggable in-game control panel. The tab controls remain available;
    -- this compact panel makes status and enable/sound/range controls directly visible.
    local stunPanelGui = Instance.new("ScreenGui")
    stunPanelGui.Name = "MawwwHubStunIndicatorPanel"
    stunPanelGui.ResetOnSpawn = false
    stunPanelGui.IgnoreGuiInset = true
    stunPanelGui.DisplayOrder = 1000020
    stunPanelGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    stunPanelGui.Enabled = VD.HideStunIndicatorPanel ~= true
    stunPanelGui.Parent = PlayerGui
    local setStunPanelHidden

    local camera = Workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize or Vector2.new(360, 640)
    local panelWidth, panelHeight = 260, 122
    local panelFrame = Instance.new("Frame")
    panelFrame.Name = "Panel"
    panelFrame.Size = UDim2.fromOffset(panelWidth, panelHeight)
    panelFrame.Position = UDim2.fromOffset(math.max(8, math.floor((viewport.X - panelWidth) / 2)), math.max(70, math.floor(viewport.Y * 0.66)))
    panelFrame.BackgroundColor3 = Color3.fromRGB(12, 16, 28)
    panelFrame.BackgroundTransparency = 0.06
    panelFrame.BorderSizePixel = 0
    panelFrame.Active = true
    panelFrame.Parent = stunPanelGui
    local panelCorner = Instance.new("UICorner")
    panelCorner.CornerRadius = UDim.new(0, 12)
    panelCorner.Parent = panelFrame
    local panelStroke = Instance.new("UIStroke")
    panelStroke.Color = Color3.fromRGB(93, 132, 255)
    panelStroke.Thickness = 1.5
    panelStroke.Transparency = 0.08
    panelStroke.Parent = panelFrame

    local panelHeader = Instance.new("TextButton")
    panelHeader.Name = "DragHeader"
    panelHeader.Size = UDim2.new(1, 0, 0, 30)
    panelHeader.BackgroundColor3 = Color3.fromRGB(25, 29, 48)
    panelHeader.BorderSizePixel = 0
    panelHeader.AutoButtonColor = false
    panelHeader.Text = "  STUN INDICATOR"
    panelHeader.TextColor3 = Color3.fromRGB(240, 245, 255)
    panelHeader.TextSize = 12
    panelHeader.Font = Enum.Font.GothamBold
    panelHeader.TextXAlignment = Enum.TextXAlignment.Left
    panelHeader.Parent = panelFrame
    local headerCorner = Instance.new("UICorner")
    headerCorner.CornerRadius = UDim.new(0, 10)
    headerCorner.Parent = panelHeader

    local closePanel = Instance.new("TextButton")
    closePanel.Name = "ClosePanel"
    closePanel.Size = UDim2.fromOffset(24, 22)
    closePanel.Position = UDim2.new(1, -28, 0, 4)
    closePanel.BackgroundColor3 = Color3.fromRGB(115, 45, 65)
    closePanel.BorderSizePixel = 0
    closePanel.Text = "×"
    closePanel.TextColor3 = Color3.new(1, 1, 1)
    closePanel.TextSize = 17
    closePanel.Font = Enum.Font.GothamBold
    closePanel.Parent = panelHeader
    closePanel.Activated:Connect(function()
        if setStunPanelHidden then
            setStunPanelHidden(true)
        else
            stunPanelGui.Enabled = false
        end
    end)

    local panelStatus = Instance.new("TextLabel")
    panelStatus.Name = "Status"
    panelStatus.Position = UDim2.fromOffset(10, 35)
    panelStatus.Size = UDim2.new(1, -20, 0, 18)
    panelStatus.BackgroundTransparency = 1
    panelStatus.Font = Enum.Font.GothamSemibold
    panelStatus.TextSize = 10
    panelStatus.TextXAlignment = Enum.TextXAlignment.Left
    panelStatus.TextColor3 = Color3.fromRGB(255, 207, 130)
    panelStatus.Text = "STATUS: OFF"
    panelStatus.Parent = panelFrame

    local function makeStunPanelButton(name, text, position, size)
        local button = Instance.new("TextButton")
        button.Name = name
        button.Position = position
        button.Size = size
        button.BackgroundColor3 = Color3.fromRGB(49, 66, 115)
        button.BorderSizePixel = 0
        button.AutoButtonColor = true
        button.Text = text
        button.TextColor3 = Color3.fromRGB(255, 255, 255)
        button.TextSize = 10
        button.Font = Enum.Font.GothamBold
        button.Parent = panelFrame
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 6)
        corner.Parent = button
        return button
    end

    local stunToggleButton = makeStunPanelButton("ToggleStun", "ENABLE", UDim2.fromOffset(10, 59), UDim2.fromOffset(82, 25))
    local stunSoundButton = makeStunPanelButton("ToggleSound", "SOUND: ON", UDim2.fromOffset(98, 59), UDim2.fromOffset(80, 25))
    local rangeDownButton = makeStunPanelButton("RangeDown", "−", UDim2.fromOffset(184, 59), UDim2.fromOffset(26, 25))
    local rangeValue = Instance.new("TextLabel")
    rangeValue.Name = "RangeValue"
    rangeValue.Position = UDim2.fromOffset(211, 59)
    rangeValue.Size = UDim2.fromOffset(27, 25)
    rangeValue.BackgroundTransparency = 1
    rangeValue.Font = Enum.Font.GothamBold
    rangeValue.TextColor3 = Color3.fromRGB(220, 231, 255)
    rangeValue.TextSize = 9
    rangeValue.Text = "500"
    rangeValue.Parent = panelFrame
    local rangeUpButton = makeStunPanelButton("RangeUp", "+", UDim2.fromOffset(238, 59), UDim2.fromOffset(15, 25))
    rangeUpButton.TextSize = 8
    rangeUpButton.BackgroundColor3 = Color3.fromRGB(44, 89, 125)

    local previewSoundButton = makeStunPanelButton("PreviewSound", "TEST SOUND", UDim2.fromOffset(10, 90), UDim2.new(1, -20, 0, 22))
    previewSoundButton.BackgroundColor3 = Color3.fromRGB(44, 89, 125)

    local function refreshStunPanel()
        local enabled = StunIndicator.Enabled == true
        stunToggleButton.Text = enabled and "DISABLE" or "ENABLE"
        stunToggleButton.BackgroundColor3 = enabled and Color3.fromRGB(44, 115, 91) or Color3.fromRGB(49, 66, 115)
        stunSoundButton.Text = StunIndicator.SoundEnabled and "SOUND: ON" or "SOUND: OFF"
        rangeValue.Text = tostring(math.floor(tonumber(StunIndicator.Range) or 500))
        local count = 0
        for character, data in pairs(StunIndicator.Cache) do
            if character and character.Parent and data and data.Gui and data.Gui.Parent then count += 1 end
        end
        if not enabled then
            panelStatus.Text = "STATUS: OFF"
            panelStatus.TextColor3 = Color3.fromRGB(255, 207, 130)
        elseif count > 0 then
            panelStatus.Text = "STUN DETECTED: " .. tostring(count)
            panelStatus.TextColor3 = Color3.fromRGB(135, 255, 190)
        else
            panelStatus.Text = "STATUS: SCANNING"
            panelStatus.TextColor3 = Color3.fromRGB(160, 203, 255)
        end
    end

    stunToggleButton.Activated:Connect(function()
        VD.StunIndicatorEnabled = not StunIndicator.Enabled
        StunIndicatorSetEnabled(VD.StunIndicatorEnabled)
        refreshStunPanel()
    end)
    stunSoundButton.Activated:Connect(function()
        VD.StunIndicatorSoundEnabled = not StunIndicator.SoundEnabled
        StunIndicator.SoundEnabled = VD.StunIndicatorSoundEnabled
        refreshStunPanel()
    end)
    rangeDownButton.Activated:Connect(function()
        VD.StunIndicatorRange = math.max(25, (tonumber(StunIndicator.Range) or 500) - 25)
        StunIndicator.Range = VD.StunIndicatorRange
        StunIndicator.SoundRange = VD.StunIndicatorRange
        refreshStunPanel()
    end)
    rangeUpButton.Activated:Connect(function()
        VD.StunIndicatorRange = math.min(500, (tonumber(StunIndicator.Range) or 500) + 25)
        StunIndicator.Range = VD.StunIndicatorRange
        StunIndicator.SoundRange = VD.StunIndicatorRange
        refreshStunPanel()
    end)
    previewSoundButton.Activated:Connect(function() pcall(StunIndicatorPreviewSound) end)

    -- Drag the panel by its header, on mouse or touch.
    local dragData = nil
    panelHeader.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            local pos = panelFrame.Position
            dragData = {Input = input, Start = Vector2.new(input.Position.X, input.Position.Y), X = pos.X.Offset, Y = pos.Y.Offset}
        end
    end)
    local stunPanelDragChangedConnection = MAWWW_Conn(UserInputService.InputChanged, function(input)
        if not dragData then return end
        local matches = (dragData.Input.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseMovement)
            or (dragData.Input.UserInputType == Enum.UserInputType.Touch and input == dragData.Input)
        if not matches then return end
        local delta = Vector2.new(input.Position.X, input.Position.Y) - dragData.Start
        local cameraNow = Workspace.CurrentCamera
        local vp = cameraNow and cameraNow.ViewportSize or Vector2.new(360, 640)
        panelFrame.Position = UDim2.fromOffset(
            math.clamp(dragData.X + delta.X, 4, math.max(4, vp.X - panelFrame.AbsoluteSize.X - 4)),
            math.clamp(dragData.Y + delta.Y, 4, math.max(4, vp.Y - panelFrame.AbsoluteSize.Y - 4))
        )
    end)
    local stunPanelDragEndedConnection = MAWWW_Conn(UserInputService.InputEnded, function(input)
        if dragData and (input == dragData.Input or input.UserInputType == Enum.UserInputType.MouseButton1) then dragData = nil end
    end)

    task.spawn(function()
        while stunPanelGui.Parent and not (VD and (VD.Destroyed or MAWWW_RUN.dead)) do
            refreshStunPanel()
            task.wait(0.4)
        end
    end)

    -- Hide toggle for the compact panel. The indicator logic can remain enabled
    -- while this control panel is hidden. Open/Close actions synchronize the toggle.
    setStunPanelHidden = function(hidden, syncToggle)
        hidden = hidden == true
        VD.HideStunIndicatorPanel = hidden
        if stunPanelGui and stunPanelGui.Parent then
            stunPanelGui.Enabled = not hidden
        end
        if syncToggle ~= false then
            local element = VD_Elements and VD_Elements["HideStunIndicatorPanel"]
            if element and type(element.SetValue) == "function" then
                pcall(function() element:SetValue(hidden) end)
            end
        end
    end

    RegToggle(
        Tabs.VisualHUD,
        "Hide Stun Indicator Panel",
        "Sembunyikan panel kontrol stun tanpa mematikan deteksi indikator.",
        true,
        "HideStunIndicatorPanel",
        function(v) setStunPanelHidden(v == true, false) end
    )

    -- Explicit entry point from the existing Visual > HUD tab.
    getgenv().MAWWW_StunIndicatorPanelShutdown = function()
        pcall(function() if stunPanelDragChangedConnection then stunPanelDragChangedConnection:Disconnect() end end)
        pcall(function() if stunPanelDragEndedConnection then stunPanelDragEndedConnection:Disconnect() end end)
        pcall(function() if stunPanelGui and stunPanelGui.Parent then stunPanelGui:Destroy() end end)
    end
    getgenv().MAWWW_StunIndicatorPanel = {
        Gui = stunPanelGui,
        Open = function()
            if setStunPanelHidden then setStunPanelHidden(false) else stunPanelGui.Enabled = true end
            refreshStunPanel()
        end,
        Close = function()
            if setStunPanelHidden then setStunPanelHidden(true) else stunPanelGui.Enabled = false end
        end,
        Refresh = refreshStunPanel,
    }
    pcall(function()
        RegButton(Tabs.VisualHUD, "Open Stun Indicator Panel", "Buka panel indikator stun yang bisa digeser.", function()
            if setStunPanelHidden then setStunPanelHidden(false) else stunPanelGui.Enabled = true end
            refreshStunPanel()
        end)
    end)
end

RegToggle(Tabs.VisualHUD, "Ping & FPS", "Display ping and FPS", false, "ShowPingFPS", function(v) VD.ShowPingFPS = v; VD_TogglePingFPS(v) end)
RegToggle(Tabs.VisualHUD, "Hide Survivor Icons", "Sembunyikan ikon survivor dan gunakan ikon tombol Mawww Hub.", false, "HideSurvIcon", function(v) VD_ToggleHideSurvIcon(v) end)
