W = getgenv().MAWWW or {}
getgenv().MAWWW = W

if not W.GenBypass then
    W.GenBypass = {
        Enabled = VD.GenBoost == true,
        Button = nil,
        LockButton = nil,
        UI = nil,
        Position = nil,
        Locked = false,
        _UIConnections = {},
        Cache = {},
        CacheTimer = 0,
        Processed = {},
        HotkeyCode = Enum.KeyCode.G,
        Destroy = nil,
    }
end

GenBypass = W.GenBypass
GenBypass.Enabled = VD.GenBoost == true
GenBypass.Position = GenBypass.Position or UDim2.new(0.88, 0, 0.55, 0)
GenBypass.Locked = false -- Start unlocked; drag handle is designed for touch screens.
-- Hide the Gen Bypass panel by default; the Survival tab toggle can show it.
-- The separate Invisible utility icon remains hidden by default.
GenBypass.Hidden = VD.HideGenBypass == true
VD.HideGenBypass = GenBypass.Hidden
VD.InvisibleHideIcon = true
VD.LockGenBossIcon = GenBypass.Locked
GenBypass._UIConnections = GenBypass._UIConnections or {}

function W.GB_GetAllGenerators()
    local now = tick()
    if now - (GenBypass.CacheTimer or 0) < 5 then
        return GenBypass.Cache or {}
    end

    GenBypass.Cache = {}
    GenBypass.CacheTimer = now

    local mapFolder = Workspace:FindFirstChild("Map")
    if not mapFolder then
        return GenBypass.Cache
    end

    pcall(function()
        for _, v in ipairs(mapFolder:GetDescendants()) do
            if v:IsA("Model") and v.Name == "Generator" then
                local isReal =
                    v:GetAttribute("RepairProgress") ~= nil
                    or v:GetAttribute("kickcount") ~= nil
                    or v:GetAttribute("ProgressRepair") ~= nil

                if isReal then
                    table.insert(GenBypass.Cache, v)
                end
            end
        end
    end)

    return GenBypass.Cache
end

function W.GB_GetPoints(genModel)
    local points = {}
    if not genModel then return points end

    pcall(function()
        for _, obj in ipairs(genModel:GetChildren()) do
            if obj.Name:find("GeneratorPoint", 1, true) and obj:IsA("BasePart") then
                table.insert(points, obj)
            end
        end
    end)

    return points
end

function W.GB_WaitRepairing(point, timeout)
    local startTime = tick()
    while point and point.Parent and tick() - startTime < (timeout or 1) do
        if point:GetAttribute("IsRepairing") == true then
            return true
        end
        task.wait(0.05)
    end
    return false
end

function W.GB_DoRepair(targetPoint)
    if MAWWW_PREMIUM_FEATURES_LOCKED then
        GenBypass.Enabled = false
        VD.GenBoost = false
        notify("Khusus Premium", "Generator Bypass hanya tersedia di Mawww Hub Premium.", 3)
        return false
    end
    if not targetPoint or not targetPoint.Parent or not GenBypass.Enabled then return false end

    local genModel = targetPoint.Parent
    if GenBypass.Processed[genModel] then return false end
    GenBypass.Processed[genModel] = true

    local character = Player.Character
    local hrp = character and character:FindFirstChild("HumanoidRootPart")
    if not hrp then
        GenBypass.Processed[genModel] = nil
        return false
    end

    local remotes = ReplicatedStorage:FindFirstChild("Remotes")
    local genFolder = remotes and remotes:FindFirstChild("Generator")
    local repairEvent = genFolder and genFolder:FindFirstChild("RepairEvent")

    if not repairEvent or not repairEvent:IsA("RemoteEvent") then
        GenBypass.Processed[genModel] = nil
        return false
    end

    local originalCFrame = hrp.CFrame

    pcall(function()
        for _, point in ipairs(W.GB_GetPoints(genModel)) do
            if point ~= targetPoint and point.Parent and GenBypass.Enabled then
                hrp.Anchored = true
                hrp.CFrame = point.CFrame
                task.wait(0.15)

                pcall(function()
                    repairEvent:FireServer(point, true)
                end)

                if not W.GB_WaitRepairing(point, 0.8) then
                    pcall(function()
                        repairEvent:FireServer(point, false)
                    end)
                    task.wait(0.1)

                    if point.Parent and hrp.Parent then
                        hrp.CFrame = point.CFrame
                    end

                    task.wait(0.15)

                    pcall(function()
                        repairEvent:FireServer(point, true)
                    end)
                    W.GB_WaitRepairing(point, 0.5)
                end

                hrp.Anchored = false
                task.wait(0.05)
            end
        end
    end)

    pcall(function()
        if hrp and hrp.Parent then
            hrp.Anchored = false
            hrp.CFrame = originalCFrame
        end
    end)

    task.wait(0.1)

    if targetPoint.Parent then
        pcall(function()
            repairEvent:FireServer(targetPoint, false)
        end)
    end

    GenBypass.Processed[genModel] = nil
    return true
end

function W.GB_GetNearestPoint()
    local character = Player.Character
    local hrp = character and character:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil, math.huge end

    local bestPoint, bestDist = nil, math.huge

    for _, genModel in ipairs(W.GB_GetAllGenerators()) do
        for _, point in ipairs(W.GB_GetPoints(genModel)) do
            local dist = (hrp.Position - point.Position).Magnitude
            if dist < bestDist then
                bestDist = dist
                bestPoint = point
            end
        end
    end

    return bestPoint, bestDist
end

function W.GB_IsPromptVisible()
    local ok, frame = pcall(function()
        return PlayerGui.pcprompts.Frame.GeneratorRepair
    end)
    return ok and frame and frame.Visible
end

function W.GB_UpdateButton()
    local button = GenBypass.Button
    if not (button and button.Parent) then return end

    -- Hide is controlled from the hub's Utility > Gen Bypass group; setting
    -- Enabled OFF never hides the panel, so it can still be moved or unlocked.
    button.Visible = not GenBypass.Hidden
    button.Image = MAWWW_GEN_BYPASS_IMAGE_ID
    button.ImageTransparency = GenBypass.Enabled and 0 or 0.18

    local stroke = button:FindFirstChild("GenBypassStroke")
    if stroke and stroke:IsA("UIStroke") then
        stroke.Color = GenBypass.Enabled and Color3.fromRGB(90, 255, 160) or Color3.fromRGB(255, 70, 90)
        stroke.Transparency = GenBypass.Enabled and 0 or 0.15
    end

    local status = button:FindFirstChild("GenBypassStatus")
    if status and status:IsA("TextLabel") then
        status.Text = MAWWW_PREMIUM_FEATURES_LOCKED and "🔒 PREMIUM" or (GenBypass.Enabled and "GEN ON" or "GEN OFF")
        status.BackgroundColor3 = MAWWW_PREMIUM_FEATURES_LOCKED and Color3.fromRGB(110, 75, 24) or (GenBypass.Enabled and Color3.fromRGB(22, 125, 75) or Color3.fromRGB(95, 35, 42))
    end

    local lockButton = GenBypass.LockButton
    if lockButton and lockButton.Parent then
        lockButton.Text = GenBypass.Locked and "L" or "D"
        lockButton.BackgroundColor3 = GenBypass.Locked and Color3.fromRGB(220, 70, 80) or Color3.fromRGB(35, 40, 52)
        lockButton.TextColor3 = Color3.fromRGB(255, 255, 255)
    end
end

