    status.ZIndex = 12
    status.Parent = button
    Instance.new("UICorner", status).CornerRadius = UDim.new(1, 0)

    -- In-panel lock control: L = locked, D = draggable/unlocked.
    local lockButton = Instance.new("TextButton")
    lockButton.Name = "GenBypassLock"
