    lockButton.Position = UDim2.new(1, -3, 0, 3)
    lockButton.Size = UDim2.fromOffset(23, 23)
    lockButton.BackgroundColor3 = GenBypass.Locked and Color3.fromRGB(220, 70, 80) or Color3.fromRGB(35, 40, 52)
    lockButton.BackgroundTransparency = 0.05
    lockButton.Text = GenBypass.Locked and "L" or "D"
    lockButton.TextColor3 = Color3.fromRGB(255, 255, 255)
    lockButton.TextSize = 12
    lockButton.Font = Enum.Font.GothamBlack
    lockButton.AutoButtonColor = true
    lockButton.Active = true
    lockButton.ZIndex = 15
    lockButton.Parent = button
    Instance.new("UICorner", lockButton).CornerRadius = UDim.new(1, 0)
    local lockStroke = Instance.new("UIStroke")
