    lockStroke.Color = Color3.fromRGB(255, 255, 255)
    lockStroke.Transparency = 0.45
    lockStroke.Parent = lockButton

    GenBypass.Button = button
    GenBypass.LockButton = lockButton

    -- Dedicated handle makes dragging much easier on phones and avoids accidentally
    -- activating the bypass while the user is trying to reposition the circular icon.
    local dragHandle = Instance.new("TextButton")
