    dragHandle.Size = UDim2.fromOffset(27, 30)
    dragHandle.BackgroundColor3 = Color3.fromRGB(19, 23, 34)
    dragHandle.BackgroundTransparency = 0.06
    dragHandle.Text = "↕"
