        W.GB_UpdateButton()
        notify("Gen Bypass Panel", GenBypass.Locked and "LOCKED — posisi dikunci" or "UNLOCKED — seret ikon atau handle ↕ untuk memindahkan", 2)
    end))

    local function toVector2(position)
        return Vector2.new(position.X, position.Y)
    end

    local function pointInside(guiObject, point)
        if not guiObject or not guiObject.Parent or not guiObject.Visible then return false end
        local topLeft = guiObject.AbsolutePosition
        local size = guiObject.AbsoluteSize
        return point.X >= topLeft.X and point.X <= topLeft.X + size.X
            and point.Y >= topLeft.Y and point.Y <= topLeft.Y + size.Y
    end

    local function beginDrag(input, fromHandle)
        local inputType = input.UserInputType
        if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then return end
        if GenBypass.Locked then return end
        if drag.active then
            if drag.input == input and fromHandle then
                drag.fromHandle = true
                drag.skipClick = true
            end
            return
        end
        local point = toVector2(input.Position)
        if not pointInside(button, point) then return end
        if pointInside(lockButton, point) then return end
        drag.active = true
        drag.mode = inputType == Enum.UserInputType.Touch and "Touch" or "Mouse"
        drag.input = input
        drag.startInput = point
        -- Preserve the current UDim2 scale/offset. Converting AbsolutePosition
        -- directly to UDim2.fromOffset() caused a vertical jump on mobile when
        -- ScreenGui.IgnoreGuiInset and touch coordinates used different origins.
        drag.startPosition = button.Position
        local camera = Workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
        drag.startCenter = Vector2.new(
            drag.startPosition.X.Scale * viewport.X + drag.startPosition.X.Offset,
            drag.startPosition.Y.Scale * viewport.Y + drag.startPosition.Y.Offset
        )
        drag.moved = false
        drag.fromHandle = fromHandle == true or pointInside(dragHandle, point)
        if drag.fromHandle then drag.skipClick = true end
    end

    local function updateDragFromPosition(position, sourceMode)
        if not drag.active or GenBypass.Locked or not drag.startInput or not drag.startCenter or not drag.startPosition then return end
        if sourceMode and sourceMode ~= drag.mode then return end
        local point = toVector2(position)
        local delta = point - drag.startInput
        if math.abs(delta.X) > DRAG_THRESHOLD or math.abs(delta.Y) > DRAG_THRESHOLD then
            drag.moved = true
            drag.skipClick = true
        end
        local camera = Workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
        local half = button.AbsoluteSize / 2
        local center = drag.startCenter + delta
        center = Vector2.new(
            math.clamp(center.X, half.X + 2, math.max(half.X + 2, viewport.X - half.X - 2)),
            math.clamp(center.Y, half.Y + 2, math.max(half.Y + 2, viewport.Y - half.Y - 2))
        )
        -- Apply only the movement delta to the saved position and preserve its
        -- original scale. On the first frame (delta == 0), this is a no-op.
        local scaleX, scaleY = drag.startPosition.X.Scale, drag.startPosition.Y.Scale
        local offsetX = center.X - scaleX * viewport.X
        local offsetY = center.Y - scaleY * viewport.Y
        button.Position = UDim2.new(scaleX, math.floor(offsetX), scaleY, math.floor(offsetY))
        GenBypass.Position = button.Position
    end

    local function finishDrag(input)
        if not drag.active or not drag.input then return end
        local inputType = input.UserInputType
        if drag.mode == "Mouse" and inputType ~= Enum.UserInputType.MouseButton1 then return end
        if drag.mode == "Touch" and (inputType ~= Enum.UserInputType.Touch or input ~= drag.input) then return end
        if drag.moved then
            GenBypass.Position = button.Position
            drag.skipClick = true
            task.delay(0.32, function()
                drag.skipClick = false
                drag.moved = false
                drag.fromHandle = false
            end)
        elseif drag.fromHandle then
            -- A tap on the handle is a drag affordance, never a repair command.
            drag.skipClick = true
            task.delay(0.32, function() drag.skipClick = false; drag.fromHandle = false end)
        end
        drag.active, drag.mode, drag.input = false, nil, nil
        drag.startInput, drag.startCenter, drag.startPosition = nil, nil, nil
    end

    track(MAWWW_Conn(UserInputService.InputBegan, function(input)
        local inputType = input.UserInputType
        if inputType ~= Enum.UserInputType.MouseButton1 and inputType ~= Enum.UserInputType.Touch then return end
        local point = toVector2(input.Position)
        if pointInside(button, point) then
            beginDrag(input, pointInside(dragHandle, point))
        end
    end))
    track(button.InputBegan:Connect(function(input)
        beginDrag(input, input.UserInputType == Enum.UserInputType.Touch and pointInside(dragHandle, toVector2(input.Position)))
    end))
    track(dragHandle.InputBegan:Connect(function(input)
        beginDrag(input, true)
    end))
    track(MAWWW_Conn(UserInputService.InputChanged, function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement then
            updateDragFromPosition(input.Position, "Mouse")
        end
    end))
    track(UserInputService.TouchMoved:Connect(function(input)
        if drag.active and drag.mode == "Touch" then
            updateDragFromPosition(input.Position, "Touch")
        end
    end))
    track(MAWWW_Conn(UserInputService.InputEnded, finishDrag))
    track(UserInputService.TouchEnded:Connect(finishDrag))

    track(button.Activated:Connect(function()
        if drag.skipClick or drag.moved then return end
        if MAWWW_PREMIUM_FEATURES_LOCKED then
            notify("Khusus Premium", "Generator Bypass hanya tersedia di Mawww Hub Premium.", 3)
            return
        end
        if not GenBypass.Enabled then
            notify("Gen Bypass", "Aktifkan Gen Bypass terlebih dahulu.", 2)
            return
        end
        local point, distance = W.GB_GetNearestPoint()
        if point and distance <= 8 then
            task.spawn(function()
                pcall(function() W.GB_DoRepair(point) end)
            end)
        elseif point then
            notify("Gen Bypass", string.format("Gen terlalu jauh (%.1f studs).", distance), 2)
        else
            notify("Gen Bypass", "Tidak ada generator ditemukan.", 2)
        end
    end))

    return ui
end

