--========================================================--
-- MAWWW HUB MUSIC PLAYER
-- Floating music panel skin uses the requested global Roblox image asset.
-- Audio is loaded by Roblox asset ID through SoundService (non-positional/local).
--========================================================--
local MAWWW_MusicInitOK, MAWWW_MusicInitError = pcall(function()
    pcall(function()
        local env = getgenv()
        local oldPanel = env and env.MAWWW_MusicPanel
        if oldPanel then
            if oldPanel.InputChangedConnection then oldPanel.InputChangedConnection:Disconnect() end
            if oldPanel.InputEndedConnection then oldPanel.InputEndedConnection:Disconnect() end
            if oldPanel.ViewportConnection then oldPanel.ViewportConnection:Disconnect() end
            if oldPanel.BeatVisualizerConnection then oldPanel.BeatVisualizerConnection:Disconnect() end
        end
    end)

    local musicGui = Instance.new("ScreenGui")
    musicGui.Name = "MawwwHubMusicPanel"
    musicGui.ResetOnSpawn = false
    musicGui.IgnoreGuiInset = true
    musicGui.DisplayOrder = 1000010
    musicGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    musicGui.Enabled = false

    -- Always attach the floating music panel to PlayerGui. Some executors expose
    -- gethui() containers that reject or silently hide a ScreenGui; the player GUI
    -- is more compatible on both mobile and desktop.
    local musicParent = PlayerGui
    local parentOk = pcall(function() musicGui.Parent = musicParent end)
    if not parentOk or musicGui.Parent == nil then
        error("Could not parent the Music Player ScreenGui to PlayerGui")
    end

    local viewport = Vector2.new(360, 640)
    pcall(function()
        local camera = Workspace.CurrentCamera
        if camera then viewport = camera.ViewportSize end
    end)
    local panelWidth = math.max(250, math.min(340, viewport.X - 16))
    local panelHeight = math.min(344, math.max(300, viewport.Y - 16))

    local frame = Instance.new("Frame")
    frame.Name = "MusicPanel"
    frame.Size = UDim2.fromOffset(panelWidth, panelHeight)
    frame.Position = UDim2.fromOffset(
        math.max(6, math.floor((viewport.X - panelWidth) / 2)),
        math.max(6, math.floor((viewport.Y - panelHeight) / 2))
    )
    frame.BackgroundColor3 = Color3.fromRGB(12, 16, 26)
    frame.BackgroundTransparency = 0.04
    frame.BorderSizePixel = 0
    frame.ClipsDescendants = true
    frame.Active = true
    frame.ZIndex = 1
    frame.Parent = musicGui

    local outerCorner = Instance.new("UICorner")
    outerCorner.CornerRadius = UDim.new(0, 14)
    outerCorner.Parent = frame

    local outerStroke = Instance.new("UIStroke")
    outerStroke.Color = Color3.fromRGB(91, 183, 255)
    outerStroke.Thickness = 1.4
    outerStroke.Transparency = 0.1
    outerStroke.Parent = frame

    local backgroundImage = Instance.new("ImageLabel")
    backgroundImage.Name = "MusicPanelBackground"
    backgroundImage.BackgroundTransparency = 1
    backgroundImage.BorderSizePixel = 0
    backgroundImage.Position = UDim2.fromScale(0, 0)
    backgroundImage.Size = UDim2.fromScale(1, 1)
    -- Start with Roblox's thumbnail resolver; some asset IDs refer to a decal/catalog
    -- asset and do not render reliably when assigned only as rbxassetid:// directly.
    backgroundImage.Image = MAWWW_TOF_TARGET_MODE_THUMBNAIL_ID
    backgroundImage.ImageTransparency = 0
    backgroundImage.ScaleType = Enum.ScaleType.Stretch
    backgroundImage.Visible = true
    backgroundImage.ZIndex = 1
    backgroundImage.Parent = frame
    local imageCorner = Instance.new("UICorner")
    imageCorner.CornerRadius = UDim.new(0, 14)
    imageCorner.Parent = backgroundImage

    -- Keep the image visible and fall back to the direct content URI only if the
    -- thumbnail did not load. This is asynchronous so the main UI never waits on it.
    task.spawn(function()
        local contentProvider = game:GetService("ContentProvider")
        pcall(function() contentProvider:PreloadAsync({backgroundImage}) end)
        if not backgroundImage.Parent then return end

        local loaded = false
        pcall(function() loaded = backgroundImage.IsLoaded end)
        if not loaded then
            pcall(function() backgroundImage.Image = MAWWW_MUSIC_PANEL_IMAGE_ID end)
            pcall(function() contentProvider:PreloadAsync({backgroundImage}) end)
        end

        if backgroundImage.Parent then
            pcall(function()
                backgroundImage.Visible = true
                backgroundImage.ImageTransparency = 0
                backgroundImage.ScaleType = Enum.ScaleType.Stretch
            end)
        end
    end)

    local dimmer = Instance.new("Frame")
    dimmer.Name = "ReadabilityOverlay"
    dimmer.Size = UDim2.fromScale(1, 1)
    dimmer.BackgroundColor3 = Color3.fromRGB(6, 10, 18)
    dimmer.BackgroundTransparency = 0.82 -- Keep the requested background art clearly visible
    dimmer.BorderSizePixel = 0
    dimmer.ZIndex = 2
    dimmer.Parent = frame
    local dimmerCorner = Instance.new("UICorner")
    dimmerCorner.CornerRadius = UDim.new(0, 14)
    dimmerCorner.Parent = dimmer

    local function makeLabel(name, text, position, size, fontSize, color, parent, zindex)
        local label = Instance.new("TextLabel")
        label.Name = name
        label.Text = text
        label.Position = position
        label.Size = size
        label.BackgroundTransparency = 1
        label.BorderSizePixel = 0
