            presetRow.TextColor3 = Color3.fromRGB(240, 247, 255)
            presetRow.TextXAlignment = Enum.TextXAlignment.Left
            presetRow.Text = "  " .. preset.Name .. "   ·   " .. preset.Id
            presetRow.LayoutOrder = index
            presetRow.ZIndex = 9
            presetRow.Parent = presetList
            local rowCorner = Instance.new("UICorner")
            rowCorner.CornerRadius = UDim.new(0, 6)
            rowCorner.Parent = presetRow
            presetRow.Activated:Connect(function()
                idBox.Text = preset.Id
                presetList.Visible = false
                presetButton.Text = "AUDIO PRESET LIBRARY  ▼"
                setStatus("Selected " .. preset.Name .. " · press Play", Color3.fromRGB(202, 220, 242))
            end)
        end
    end

    presetLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        presetList.CanvasSize = UDim2.fromOffset(0, presetLayout.AbsoluteContentSize.Y + 8)
    end)

    local hint = makeLabel(
        "Hint",
        "Hundreds of categorized presets · audio availability depends on Roblox permissions.",
        UDim2.new(0, 11, 0, 294),
        UDim2.new(1, -22, 0, 22),
        9,
        Color3.fromRGB(175, 195, 219),
        content,
        5
    )
    hint.TextYAlignment = Enum.TextYAlignment.Center

    local soundService = game:GetService("SoundService")
    local musicSound = Instance.new("Sound")
    musicSound.Name = "MawwwHub_MusicPlayer"
    musicSound.Volume = 0.5
    musicSound.Looped = true
    musicSound.Parent = soundService

    local loopEnabled = true
    -- PlaybackLoudness is Roblox's client-side loudness estimate. It is not a
    -- per-frequency spectrum, so the bars follow the track's loud/quiet beats
    -- and shape the center bars slightly higher for a bass-reactive visual.
    local beatElapsed = 0
    local smoothedLoudness = 0
    local previousLoudness = 0
    local beatVisualizerLastUpdate = 0
    local beatVisualizerWasActive = false
    local beatVisualizerConnection = MAWWW_Conn(game:GetService("RunService").RenderStepped, function(dt)
        if not musicSound.Parent then return end
        local isActive = musicGui.Enabled and musicSound.Playing
        if not isActive then
            if beatVisualizerWasActive then
                local barCount = #beatBars
                for _, bar in ipairs(beatBars) do
                    bar.Size = UDim2.new(1 / math.max(barCount, 1), -4, 0, 3)
                    bar.BackgroundTransparency = 0.34
                end
                beatVisualizerStroke.Transparency = 0.42
                beatVisualizerWasActive = false
                smoothedLoudness = 0
                previousLoudness = 0
            end
            return
        end

        local now = os.clock()
        if now - beatVisualizerLastUpdate < (1 / 15) then return end
        dt = math.min(math.max(now - (beatVisualizerLastUpdate > 0 and beatVisualizerLastUpdate or now), 0), 0.1)
        beatVisualizerLastUpdate = now
        beatVisualizerWasActive = true
        beatElapsed = beatElapsed + dt

        local loudness = 0
        pcall(function()
            loudness = tonumber(musicSound.PlaybackLoudness) or 0
        end)
        local rawLevel = math.clamp(loudness / 360, 0, 1)
        -- A fast transient boost makes strong drum/bass hits visibly punchier.
        local rise = math.max(0, rawLevel - previousLoudness)
        previousLoudness = rawLevel
        local targetLevel = math.clamp(rawLevel + math.min(0.22, rise * 1.5), 0, 1)
        if not isActive then targetLevel = 0 end
        local smoothingRate = targetLevel > smoothedLoudness and 16 or 5
        smoothedLoudness = smoothedLoudness
            + (targetLevel - smoothedLoudness) * math.clamp((dt or 0) * smoothingRate, 0, 1)

        local barCount = #beatBars
        for i, bar in ipairs(beatBars) do
            local centerBias = 1 - (math.abs((i - (barCount + 1) / 2) / ((barCount + 1) / 2)) * 0.22)
            local ripple = 0.62 + 0.38 * math.abs(math.sin(beatElapsed * (5.2 + i * 0.19) + i * 0.83))
            local height = 3
            if isActive and rawLevel > 0.012 then
                height = math.floor(3 + 16 * smoothedLoudness * ripple * centerBias)
            elseif isActive then
                -- Keep a subtle low-level idle when the audio is playing quietly.
                height = math.floor(3 + 2 * math.abs(math.sin(beatElapsed * 2.8 + i)) )
            end
            bar.Size = UDim2.new(1 / barCount, -4, 0, math.clamp(height, 3, 19))
            bar.BackgroundTransparency = isActive and 0.02 or 0.34
        end
        beatVisualizerStroke.Transparency = (isActive and rawLevel > 0.06) and 0.12 or 0.42
    end)

    setStatus = function(message, color)
        status.Text = tostring(message or "")
        if color then status.TextColor3 = color end
    end

    presetButton.Activated:Connect(function()
        presetList.Visible = not presetList.Visible
        presetButton.Text = presetList.Visible and "AUDIO PRESET LIBRARY  ▲" or "AUDIO PRESET LIBRARY  ▼"
        if presetList.Visible then
            setStatus("Choose a preset to load its audio ID", Color3.fromRGB(202, 220, 242))
        end
    end)

    local function clampPanel()
        pcall(function()
            local camera = Workspace.CurrentCamera
            if not camera then return end
            local vp = camera.ViewportSize
            local w = frame.AbsoluteSize.X
            local h = frame.AbsoluteSize.Y
            local px = frame.Position.X.Offset
            local py = frame.Position.Y.Offset
            local maxX = math.max(4, vp.X - w - 4)
            local maxY = math.max(4, vp.Y - h - 4)
            frame.Position = UDim2.fromOffset(
                math.clamp(px, 4, maxX),
                math.clamp(py, 4, maxY)
            )
        end)
    end

    local function extractAudioId(value)
        local raw = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
        local id = raw:match("^rbxassetid://(%d+)$")
            or raw:match("^(%d+)$")
            or raw:match("[?&]id=(%d+)")
            or raw:match("/asset/(%d+)")
        return id
    end

    local function playMusic()
        local id = extractAudioId(idBox.Text)
        if not id then
            setStatus("Invalid ID · use a numeric Roblox audio asset ID", Color3.fromRGB(255, 157, 157))
            return
        end

        local audioUri = "rbxassetid://" .. id
        getgenv().MAWWW_MusicAssetId = id
        pcall(function() musicSound:Stop() end)
        musicSound.SoundId = audioUri
        musicSound.Looped = loopEnabled
        pauseButton.Text = "Ⅱ PAUSE"
        pcall(function() musicSound.TimePosition = 0 end)
        setStatus("Loading audio " .. id .. "…", Color3.fromRGB(255, 224, 148))

        local ok, err = pcall(function()
            musicSound:Play()
        end)
        if not ok then
            setStatus("Playback failed · check this asset ID", Color3.fromRGB(255, 157, 157))
            warn("[Mawww Hub Music] Play failed:", err)
            return
        end

        task.delay(1.8, function()
            if not musicSound.Parent or musicSound.SoundId ~= audioUri then return end
            if musicSound.IsLoaded and musicSound.Playing then
                setStatus("Now playing · " .. id, Color3.fromRGB(148, 255, 193))
            elseif not musicSound.IsLoaded then
                setStatus("Still loading · check audio access if silent", Color3.fromRGB(255, 224, 148))
            elseif not musicSound.Playing then
                setStatus("Audio unavailable or permission denied", Color3.fromRGB(255, 157, 157))
            end
        end)
    end

    playButton.Activated:Connect(playMusic)
    idBox.FocusLost:Connect(function(enterPressed)
        if enterPressed then playMusic() end
    end)

    pauseButton.Activated:Connect(function()
        if musicSound.SoundId == "" then
            setStatus("Choose an audio ID first", Color3.fromRGB(255, 224, 148))
            return
        end
        if musicSound.Playing then
            pcall(function() musicSound:Pause() end)
            pauseButton.Text = "▶ RESUME"
            setStatus("Paused", Color3.fromRGB(202, 220, 242))
        else
            local ok = pcall(function() musicSound:Resume() end)
            if ok then
                pauseButton.Text = "Ⅱ PAUSE"
                setStatus("Resumed", Color3.fromRGB(148, 255, 193))
            else
                playMusic()
            end
        end
    end)

    stopButton.Activated:Connect(function()
        pcall(function() musicSound:Stop() end)
        pauseButton.Text = "Ⅱ PAUSE"
        setStatus("Stopped", Color3.fromRGB(202, 220, 242))
    end)

    local function updateVolume()
        musicSound.Volume = math.clamp(musicSound.Volume, 0, 1)
        volumeLabel.Text = "Volume " .. tostring(math.floor(musicSound.Volume * 100 + 0.5)) .. "%"
    end
    volumeDown.Activated:Connect(function()
        musicSound.Volume = math.max(0, musicSound.Volume - 0.1)
        updateVolume()
    end)
    volumeUp.Activated:Connect(function()
        musicSound.Volume = math.min(1, musicSound.Volume + 0.1)
        updateVolume()
    end)
    loopButton.Activated:Connect(function()
        loopEnabled = not loopEnabled
        musicSound.Looped = loopEnabled
        loopButton.Text = loopEnabled and "LOOP: ON" or "LOOP: OFF"
        loopButton.BackgroundColor3 = loopEnabled
            and Color3.fromRGB(35, 101, 98)
            or Color3.fromRGB(66, 73, 87)
    end)

    musicSound.Loaded:Connect(function()
        if musicSound.Parent and musicSound.Playing then
            local id = extractAudioId(musicSound.SoundId)
            setStatus("Now playing · " .. tostring(id or "audio"), Color3.fromRGB(148, 255, 193))
        end
    end)
    musicSound.Ended:Connect(function()
        if not musicSound.Looped then
            setStatus("Track ended", Color3.fromRGB(202, 220, 242))
            pauseButton.Text = "Ⅱ PAUSE"
        end
    end)

    closeButton.Activated:Connect(function()
        musicGui.Enabled = false
    end)

    local minimized = false
    minimizeButton.Activated:Connect(function()
        minimized = not minimized
        content.Visible = not minimized
        frame.Size = UDim2.fromOffset(panelWidth, minimized and 36 or panelHeight)
        minimizeButton.Text = minimized and "+" or "−"
        task.defer(clampPanel)
    end)

    -- Drag without the first-move snap: preserve the exact screen position at touch-down.
    -- Mouse drag follows MouseMovement; touch drag only follows the initiating touch.
    local dragState = nil
    local function beginDrag(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end
        local absolute = frame.AbsolutePosition
        local touchId = nil
        if input.UserInputType == Enum.UserInputType.Touch then
            pcall(function() touchId = input.TouchId end)
        end
        dragState = {
            Input = input,
            StartInput = input.Position,
            StartX = absolute.X,
            StartY = absolute.Y,
            TouchId = touchId,
            Moved = false,
        }
    end

    header.InputBegan:Connect(beginDrag)
    title.InputBegan:Connect(beginDrag)
    subtitle.InputBegan:Connect(beginDrag)

    local inputChangedConnection = MAWWW_Conn(UserInputService.InputChanged, function(input)
        local d = dragState
        if not d then return end
        local isMouseMove = d.Input.UserInputType == Enum.UserInputType.MouseButton1
            and input.UserInputType == Enum.UserInputType.MouseMovement
        local isSameTouch = d.Input.UserInputType == Enum.UserInputType.Touch
            and input.UserInputType == Enum.UserInputType.Touch
            and (input == d.Input or (d.TouchId ~= nil and input.TouchId == d.TouchId))
        if not isMouseMove and not isSameTouch then return end

        local delta = input.Position - d.StartInput
        if delta.Magnitude >= 2 then d.Moved = true end
        if d.Moved then
            local camera = Workspace.CurrentCamera
            local vp = camera and camera.ViewportSize or Vector2.new(360, 640)
            local maxX = math.max(4, vp.X - frame.AbsoluteSize.X - 4)
            local maxY = math.max(4, vp.Y - frame.AbsoluteSize.Y - 4)
            local newX = math.clamp(d.StartX + delta.X, 4, maxX)
            local newY = math.clamp(d.StartY + delta.Y, 4, maxY)
            frame.Position = UDim2.fromOffset(newX, newY)
        end
    end)

    local inputEndedConnection = MAWWW_Conn(UserInputService.InputEnded, function(input)
        local d = dragState
        if not d then return end
        local isMouseEnd = d.Input.UserInputType == Enum.UserInputType.MouseButton1
            and input.UserInputType == Enum.UserInputType.MouseButton1
        local isTouchEnd = d.Input.UserInputType == Enum.UserInputType.Touch
            and input.UserInputType == Enum.UserInputType.Touch
            and (input == d.Input or (d.TouchId ~= nil and input.TouchId == d.TouchId))
        if isMouseEnd or isTouchEnd then
            dragState = nil
        end
    end)

    local viewportConnection = nil
    pcall(function()
        local camera = Workspace.CurrentCamera
        if camera then
            viewportConnection = camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
                task.defer(clampPanel)
            end)
        end
    end)

    -- Expose a simple open/stop entry point, plus a button in Utilities.
    getgenv().MAWWW_MusicPanel = {
        Gui = musicGui,
        Sound = musicSound,
        InputChangedConnection = inputChangedConnection,
        InputEndedConnection = inputEndedConnection,
        ViewportConnection = viewportConnection,
        BeatVisualizerConnection = beatVisualizerConnection,
        BeatVisualizer = beatVisualizer,
        Open = function() musicGui.Enabled = true; task.defer(clampPanel) end,
        Close = function() musicGui.Enabled = false end,
        Play = playMusic,
        Stop = function() musicSound:Stop() end,
    }

    pcall(function()
        RegButton(
            Tabs.UtilityQuick,
            "Open Music Player",
            "Open the floating music panel using public Roblox audio asset IDs.",
            function()
                musicGui.Enabled = true
                task.defer(clampPanel)
            end
        )
        RegButton(
            Tabs.UtilityQuick,
            "Stop Music",
            "Stop the current background track.",
            function()
                pcall(function() musicSound:Stop() end)
                setStatus("Stopped", Color3.fromRGB(202, 220, 242))
            end
        )
    end)

    getgenv().MAWWW_OpenMusicPanel = function()
        musicGui.Enabled = true
        task.defer(clampPanel)
    end

    -- Also expose the player under HUD/Indicators in case the quick-action column
    -- is collapsed or not displayed by a specific UI-library build.
    pcall(function()
        RegButton(Tabs.VisualHUD, "Open Music Panel", "Buka panel musik Mawww Hub.", function()
            musicGui.Enabled = true
            task.defer(clampPanel)
        end)
    end)
end)
if not MAWWW_MusicInitOK then
    warn("[Mawww Hub Music] Panel setup failed; main hub was kept alive:", tostring(MAWWW_MusicInitError))
end


--========================================================--
-- FIX: dropdown/select lists must scroll to their final option (desktop + mobile)
-- Dropdown scrolling compatibility. Decorative popup artwork is disabled because
-- a backdrop could be parented to a groupbox and cover its feature controls.
-- Covers dynamically-created Fluent/Obsidian dropdown popup ScrollingFrames,
-- including Select Emote. Explicitly keeps the CanvasSize synchronized with
-- UIListLayout/UIGridLayout instead of relying on stale/undersized library values.
--========================================================--
do
    local ok, err = pcall(function()
        local env = getgenv()
        local previous = env.MAWWW_DropdownScrollFix
        if type(previous) == "table" then
            if type(previous.Connections) == "table" then
                for _, connection in ipairs(previous.Connections) do
                    pcall(function() connection:Disconnect() end)
                end
            end
            if type(previous.Backgrounds) == "table" then
                for _, background in pairs(previous.Backgrounds) do
                    pcall(function()
                        if background and background.Parent then background:Destroy() end
                    end)
                end
            end
        end

        local state = {
            Connections = {},
            Frames = setmetatable({}, { __mode = "k" }),
            Refreshers = setmetatable({}, { __mode = "k" }),
            Backgrounds = setmetatable({}, { __mode = "k" }),
        }
        env.MAWWW_DropdownScrollFix = state

        local function track(connection)
            if connection then
                table.insert(state.Connections, connection)
            end
            return connection
        end

        local function isCandidate(scroller)
            if not scroller or not scroller:IsA("ScrollingFrame") then
                return false
            end

            local node = scroller
            local depth = 0
            while node and depth < 7 do
                local name = string.lower(tostring(node.Name or ""))
                if name:find("dropdown", 1, true)
                    or name:find("drop_down", 1, true)
                    or name:find("option", 1, true)
                    or name:find("choice", 1, true)
                    or name:find("select", 1, true)
                    or name:find("emote", 1, true)
                    or name:find("popup", 1, true)
                    or name:find("itemlist", 1, true) then
                    return true
                end
                node = node.Parent
                depth += 1
            end

            -- Some library builds use a generic name for dropdown popup lists.
            -- Do not classify a whole tab page as a dropdown just because it has
            -- many sections: require multiple direct selectable option rows.
            local layout = scroller:FindFirstChildOfClass("UIListLayout")
                or scroller:FindFirstChildOfClass("UIGridLayout")
            if not layout then return false end
            local rows, selectableRows = 0, 0
            for _, child in ipairs(scroller:GetChildren()) do
                if child:IsA("GuiObject")
                    and not child:IsA("UIListLayout")
                    and not child:IsA("UIGridLayout")
                    and not child:IsA("UIPadding") then
                    rows += 1
                    local childName = string.lower(tostring(child.Name or ""))
                    if child:IsA("GuiButton")
                        or childName:find("option", 1, true)
                        or childName:find("choice", 1, true)
                        or childName:find("item", 1, true) then
                        selectableRows += 1
                    end
                end
            end
            return rows >= 3 and selectableRows >= 3
        end

        local function patchScroller(scroller)
            if not isCandidate(scroller) then return end
            if state.Frames[scroller] then
                local refresh = state.Refreshers[scroller]
                if refresh then task.defer(refresh) end
                return
            end
            state.Frames[scroller] = true

            pcall(function()
                scroller.Active = true
                scroller.ScrollingEnabled = true
                scroller.ScrollingDirection = Enum.ScrollingDirection.Y
                scroller.ElasticBehavior = Enum.ElasticBehavior.Always
                scroller.ScrollBarThickness = math.clamp(
                    tonumber(scroller.ScrollBarThickness) or 5, 4, 8
                )
                scroller.AutomaticCanvasSize = Enum.AutomaticSize.None
            end)

            local refreshing = false
            -- Identify the OUTER popup frame, not the ScrollingFrame itself.
            -- Earlier code often returned the ScrollingFrame immediately; the
            -- surrounding holder then remained tall and appeared as a large black
            -- rectangle even after the option viewport had been resized.
            local function isPopupNode(node)
                if not node or not node:IsA("GuiObject") then return false end
                local name = string.lower(tostring(node.Name or ""))
                return name:find("dropdown", 1, true) ~= nil
                    or name:find("drop_down", 1, true) ~= nil
                    or name:find("popup", 1, true) ~= nil
                    or name:find("optionlist", 1, true) ~= nil
                    or name:find("optionslist", 1, true) ~= nil
                    or name:find("choice_list", 1, true) ~= nil
                    or name:find("itemlist", 1, true) ~= nil
                    or name:find("combobox", 1, true) ~= nil
                    or name:find("listbox", 1, true) ~= nil
            end

            local function findPopupRoot()
                local node = scroller.Parent
                local depth = 0
                while node and node:IsA("GuiObject") and depth < 6 do
                    if isPopupNode(node) then return node end
                    local name = string.lower(tostring(node.Name or ""))
                    if name:find("window", 1, true) or name:find("tabcontent", 1, true)
                        or name:find("page", 1, true) or name == "content" or name == "main" then
                        break
                    end
                    node = node.Parent
                    depth += 1
                    if node and node:IsA("ScrollingFrame") then break end
                end

                -- Library variants without descriptive names usually put a compact
                -- holder directly around the option list. Accept it only when it
                -- is plausibly popup-sized, never when it is the entire hub window.
                local parent = scroller.Parent
                local camera = workspace.CurrentCamera
                local viewport = camera and camera.ViewportSize or Vector2.new(800, 600)
                if parent and parent:IsA("GuiObject") then
                    local parentSize = parent.AbsoluteSize
                    local scrollSize = scroller.AbsoluteSize
                    local parentName = string.lower(tostring(parent.Name or ""))
                    local looksLikeMain = parentName:find("window", 1, true)
                        or parentName:find("tabcontent", 1, true)
                        or parentName == "content" or parentName == "main"
                    if not looksLikeMain and parentSize.X > 0 and parentSize.Y > 0
                        and parentSize.X <= viewport.X * 0.92
                        and parentSize.Y <= viewport.Y * 0.92
                        and parentSize.Y >= scrollSize.Y * 0.82 then
                        return parent
                    end
                end
                return scroller
            end

            local popupRoot = findPopupRoot()

            -- Apply the requested Roblox image behind the visible dropdown viewport.
            -- When an outer popup holder is identifiable, fill that holder. Otherwise
            -- use a sibling backdrop exactly aligned to the ScrollingFrame viewport so
            -- the artwork never enters the scroll canvas or moves with the option rows.
            local function getClipBounds()
                local topBound, bottomBound = 8, math.huge
                local camera = workspace.CurrentCamera
                if camera then bottomBound = camera.ViewportSize.Y - 10 end

                -- Intersect all real clipping ancestors. This keeps the option list
                -- inside the visible tab/window viewport instead of requiring the
                -- user to drag the entire hub upward on a phone.
                local node = popupRoot and popupRoot.Parent or scroller.Parent
                while node and not node:IsA("ScreenGui") do
                    if node:IsA("GuiObject")
                        and node.ClipsDescendants
                        and not isPopupNode(node)
                        and node.AbsoluteSize.Y >= 100 then
                        topBound = math.max(topBound, node.AbsolutePosition.Y + 2)
                        bottomBound = math.min(
                            bottomBound,
                            node.AbsolutePosition.Y + node.AbsoluteSize.Y - 2
                        )
                    end
                    node = node.Parent
                end
                return topBound, bottomBound
            end

            local originalScrollHeight = nil

            local function refreshCanvas()
                if refreshing or not scroller.Parent then return end
                refreshing = true
                pcall(function()
                    local currentHeight = math.max(scroller.AbsoluteSize.Y, scroller.Size.Y.Offset, 1)
                    if not originalScrollHeight and currentHeight > 40 then
                        originalScrollHeight = currentHeight
                    end

                    -- Only alter geometry after the dropdown has a real, measurable
                    -- viewport. At creation some libraries start the popup at 0 px;
                    -- resizing that hidden frame would otherwise permanently shrink it.
                    if originalScrollHeight then
                        local intendedHeight = originalScrollHeight

                        -- Calculate the natural option-list content height first.
                        -- The previous implementation only fitted to the screen height,
                        -- which could leave a tall, empty black popup under the final item.
                        -- Prefer layout measurements (all rows, including off-screen rows)
                        -- and only use child geometry when no layout is available yet.
                        local contentHint = 0
                        local hintLayout = scroller:FindFirstChildOfClass("UIListLayout")
                            or scroller:FindFirstChildOfClass("UIGridLayout")
                        if hintLayout then
                            contentHint = hintLayout.AbsoluteContentSize.Y
                        end
                        if contentHint <= 0 then
                            local measureViewport = math.max(scroller.AbsoluteSize.Y, 1)
                            for _, child in ipairs(scroller:GetChildren()) do
                                if child:IsA("GuiObject")
                                    and not child:IsA("UIListLayout")
                                    and not child:IsA("UIGridLayout")
                                    and not child:IsA("UIPadding") then
                                    local y = child.Position.Y.Scale * measureViewport + child.Position.Y.Offset
                                    local h = child.Size.Y.Scale * measureViewport + child.Size.Y.Offset
                                    contentHint = math.max(contentHint, y + h)
                                end
                            end
                        end
                        local hintPadding = scroller:FindFirstChildOfClass("UIPadding")
                        if hintPadding then
                            contentHint += hintPadding.PaddingTop.Offset + hintPadding.PaddingBottom.Offset
                            contentHint += (hintPadding.PaddingTop.Scale + hintPadding.PaddingBottom.Scale)
                                * math.max(scroller.AbsoluteSize.Y, 1)
                        end

                        local topBound, bottomBound = getClipBounds()
                        local clipHeight = math.max(64, bottomBound - topBound - 12)
                        -- For short menus, size the popup to its rows instead of the full
                        -- viewport. For long menus, cap it to the visible area so mobile
                        -- users can scroll to the last option without moving the hub.
                        local naturalHeight = contentHint > 0
                            and math.min(intendedHeight, contentHint + 10)
                            or intendedHeight
                        local fittedHeight = math.min(naturalHeight, clipHeight)
                        local oldTop = scroller.AbsolutePosition.Y
                        local wantedTop = math.clamp(
                            oldTop,
                            topBound + 6,
                            math.max(topBound + 6, bottomBound - fittedHeight - 6)
                        )
                        if oldTop + fittedHeight > bottomBound - 6 then
                            wantedTop = math.max(topBound + 6, bottomBound - fittedHeight - 6)
                        end

                        local shiftY = wantedTop - oldTop
                        if math.abs(shiftY) > 1 then
                            local moveTarget = popupRoot or scroller
                            local parent = moveTarget.Parent
                            if parent and parent:IsA("GuiObject") then
                                local pos = moveTarget.Position
                                moveTarget.Position = UDim2.new(
                                    pos.X.Scale, pos.X.Offset,
                                    pos.Y.Scale, pos.Y.Offset + shiftY
                                )
                            end
                        end

                        -- Resize the scroll viewport (and popup holder when identifiable)
                        -- to the available window area; canvas remains full content height.
                        if fittedHeight > 0 then
                            local size = scroller.Size
                            if math.abs(scroller.AbsoluteSize.Y - fittedHeight) > 2 then
                                scroller.Size = UDim2.new(size.X.Scale, size.X.Offset, 0, fittedHeight)
                            end
                            if popupRoot and popupRoot ~= scroller and isPopupNode(popupRoot) then
                                pcall(function()
                                    local rootSize = popupRoot.Size
                                    local rootHeight = popupRoot.AbsoluteSize.Y
                                    local extra = math.max(0, rootHeight - math.max(currentHeight, 1))
                                    -- Only preserve a small header/padding allowance. Large
                                    -- residual space is the black empty area the user reported.
                                    extra = math.min(extra, 34)
                                    local desiredRootHeight = math.min(clipHeight, fittedHeight + extra)
                                    popupRoot.AutomaticSize = Enum.AutomaticSize.None
                                    if math.abs(rootHeight - desiredRootHeight) > 2 then
                                        popupRoot.Size = UDim2.new(
                                            rootSize.X.Scale, rootSize.X.Offset, 0, desiredRootHeight
                                        )
                                    end
                                end)
                            end
                        end
                    end

                    local viewportHeight = math.max(scroller.AbsoluteWindowSize.Y, scroller.AbsoluteSize.Y, 1)
                    local contentHeight = 0
                    local layout = scroller:FindFirstChildOfClass("UIListLayout")
                        or scroller:FindFirstChildOfClass("UIGridLayout")
                    if layout then
                        contentHeight = layout.AbsoluteContentSize.Y
                    else
                        for _, child in ipairs(scroller:GetChildren()) do
                            if child:IsA("GuiObject") and not child:IsA("UIListLayout")
                                and not child:IsA("UIGridLayout") and not child:IsA("UIPadding") then
                                local y = child.Position.Y.Scale * viewportHeight + child.Position.Y.Offset
                                local h = child.Size.Y.Scale * viewportHeight + child.Size.Y.Offset
                                contentHeight = math.max(contentHeight, y + h)
                            end
                        end
                    end

                    -- A nested layout may live one level deeper than the scroller.
                    -- CanvasPosition compensation converts descendant positions back
                    -- into the full, unscrolled content coordinate space.
                    local scrollTop = scroller.AbsolutePosition.Y
                    local scrollOffset = scroller.CanvasPosition.Y
                    for _, descendant in ipairs(scroller:GetDescendants()) do
                        if descendant:IsA("GuiObject") then
                            local relativeY = descendant.AbsolutePosition.Y - scrollTop + scrollOffset
                            contentHeight = math.max(contentHeight, relativeY + descendant.AbsoluteSize.Y)
                        end
                    end

                    local padding = scroller:FindFirstChildOfClass("UIPadding")
                    if padding then
                        contentHeight += padding.PaddingTop.Offset + padding.PaddingBottom.Offset
                        contentHeight += (padding.PaddingTop.Scale + padding.PaddingBottom.Scale) * viewportHeight
                    end

                    local wantedCanvasHeight = math.ceil(math.max(viewportHeight, contentHeight + 8))
                    local currentCanvas = scroller.CanvasSize
                    scroller.CanvasSize = UDim2.new(
                        currentCanvas.X.Scale, currentCanvas.X.Offset, 0, wantedCanvasHeight
                    )
                    scroller.ClipsDescendants = true
                    scroller.Active = true
                    scroller.ScrollingEnabled = true
                    scroller.ScrollingDirection = Enum.ScrollingDirection.Y

                    -- Keep CanvasPosition inside its new range after viewport resizing.
                    local maxCanvasY = math.max(0, wantedCanvasHeight - math.floor(viewportHeight))
                    local canvasPos = scroller.CanvasPosition
                    local clampedY = math.clamp(canvasPos.Y, 0, maxCanvasY)
                    if math.abs(canvasPos.Y - clampedY) > 1 then
                        scroller.CanvasPosition = Vector2.new(canvasPos.X, clampedY)
                    end
                end)
                refreshing = false
            end
            state.Refreshers[scroller] = refreshCanvas

            local layout = scroller:FindFirstChildOfClass("UIListLayout")
                or scroller:FindFirstChildOfClass("UIGridLayout")
            if layout then
                track(layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
                    task.defer(refreshCanvas)
                end))
            end
            track(scroller.ChildAdded:Connect(function(child)
                task.defer(refreshCanvas)
                if child:IsA("UIListLayout") or child:IsA("UIGridLayout") then
                    track(child:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
                        task.defer(refreshCanvas)
                    end))
                end
            end))
            track(scroller.ChildRemoved:Connect(function()
                task.defer(refreshCanvas)
            end))
            track(scroller:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                task.defer(refreshCanvas)
            end))
            -- Re-fit when the popup opens, the tab scrolls, or the hub is moved/resized.
            -- This is especially important on mobile where the dropdown can start near
            -- the bottom edge even though its own CanvasSize is correct.
            track(scroller:GetPropertyChangedSignal("Visible"):Connect(function()
                task.defer(refreshCanvas)
            end))
            track(scroller:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
                task.defer(refreshCanvas)
            end))
            track(scroller.AncestryChanged:Connect(function(_, parent)
                if not parent then
                    state.Frames[scroller] = nil
                    state.Refreshers[scroller] = nil
                end
            end))

            task.defer(refreshCanvas)
            task.delay(0.12, refreshCanvas)
            task.delay(0.45, refreshCanvas)
        end

        local function watchRoot(root)
            if not root then return end
            for _, instance in ipairs(root:GetDescendants()) do
                if instance:IsA("ScrollingFrame") then
                    patchScroller(instance)
                end
            end
            track(root.DescendantAdded:Connect(function(instance)
                if instance:IsA("ScrollingFrame") then
                    task.defer(patchScroller, instance)
                    return
                end
                local ancestor = instance.Parent
                while ancestor do
                    if ancestor:IsA("ScrollingFrame") then
                        local refresh = state.Refreshers[ancestor]
                        if refresh then task.defer(refresh) else task.defer(patchScroller, ancestor) end
                        break
                    end
                    ancestor = ancestor.Parent
                end
            end))
        end

        local players = game:GetService("Players")
        local localPlayer = players.LocalPlayer
        local playerGui = localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui")
        if playerGui then watchRoot(playerGui) end
        pcall(function() watchRoot(game:GetService("CoreGui")) end)

        -- Dropdown menus can be created on first click after startup. The
        -- DescendantAdded observers above catch the popup and each lazily-added
        -- option row; no permanent per-frame rescanning is needed.
    end)
    if not ok then
        warn("[Mawww Hub] Dropdown scroll compatibility patch failed:", tostring(err))
    end
end


-- Silent Veil survivor knock-status overlays (V1-V3) removed as requested.

-- Balance feature sections into left/right columns after the GUI has measured their content.
-- This is layout-only: groupbox instances and their feature callbacks are preserved.
local function MAWWW_RebalanceObsidianFeatureColumns()
    -- Obsidian lays out groupboxes natively in its left/right columns.
    return true
end

task.defer(function()
    task.wait(0.65)
    pcall(MAWWW_ApplyCompactFullHeightTabs)
end)

-- Let the initial UI and feature registration settle before displaying notices.
task.delay(5, function()
    MAWWW_StartupNotificationsMuted = false
end)


--========================================================--
-- FINAL OBSIDIAN UI CLEANUP + RELIABLE COLUMN SCROLLING
-- Remove Obsidian UI/legacy dropdown wallpaper; preserve feature artwork.
-- Separate feature GUIs (status artwork, target selectors, music panel,
-- and the floating logo) are intentionally untouched.
--========================================================--
local function MAWWW_FinalizeObsidianUI()
    -- The Mawww Hub UI UI owns its section layout and scroll canvases. Only remove
    -- the exact decorative popup image from older Mawww versions; never scan or
    -- destroy arbitrary ImageLabels because those belong to feature panels.
    pcall(function()
        local roots = MAWWW_GetGuiRoots()
        for _, root in ipairs(roots) do
            for _, object in ipairs(root:GetDescendants()) do
                if object:IsA("ImageLabel")
                    and string.lower(tostring(object.Name or "")) == "mawwdropdownscrollbackground" then
                    pcall(function() object:Destroy() end)
                end
            end
        end
    end)
    return true
end

-- Run after the Mawww Hub UI sections have finished registering; this only clears a
-- stale decorative popup image from older versions and preserves feature artwork.
task.defer(function()
    task.wait(0.75)
    MAWWW_FinalizeObsidianUI()
    task.wait(0.35)
    MAWWW_FinalizeObsidianUI()
end)

return VDUI

